// Deduplicated DR list
const DRS = [...new Set([
  "DR476820","DR1859967","DR473340","DR1859942","DR474214","DR1863004",
  "DR1862144","DR1858339","DR1858337","DR1861379","DR474258","DR474143",
  "DR469295","DR1861408","DR474197","DR1861254","DR1858409","DR1735764",
  "DR1735756","DR1735615","DR1863973","DR1863972","DR477163","DR477278",
  "DR476369","DR477276","DR476670","DR1863200","DR469884","DR1858667",
  "DR470546","DR472454","DR1856219","DR470200","DR470019","DR1853303",
  "DR473201","DR1863221","DR1862660","DR1730676","DR1858356","DR473263",
  "DR473237","DR470239","DR1752198","DR476560","DR1863256","DR472746",
  "DR473246","DR1730620","DR470343","DR1863233","DR470083","DR470201",
  "DR470131","DR477273","DR1856299","DR1730549","DR1862782","DR1863165",
  "DR1853585","DR1858723","DR1752155","DR470341","DR1752062","DR1856547",
  "DR1736250","DR1863022","DR1730786","DR471022","DR1855908","DR1859467",
  "DR470316","DR473274","DR1750767","DR1856297","DR1863330","DR470661",
  "DR1729577","DR1858536","DR472172","DR469872","DR1862833","DR1862602",
  "DR1857413","DR1863494","DR1858247","DR1858725","DR1730703","DR1752438",
  "DR1751902","DR1750912","DR1748851","DR1748753","DR1736503","DR1736321",
  "DR1735307","DR1733708","DR1730646"
])];

const BASE = "https://www.1map.co.za";

// Known layers to search
const LAYERS = [
  { id: "5121", name: "Home Installation - Aerial" },
  { id: "5122", name: "Home Installation - Underground" },
  { id: "4498", name: "Pole Permission" },
  { id: "4499", name: "Home Sign Ups" },
  { id: "4500", name: "Brand Awareness" },
  { id: "5171", name: "Maintenance" },
  { id: "5170", name: "Sales" },
];

async function auth() {
  const email = process.env.ONEMAP_EMAIL || "";
  const password = process.env.ONEMAP_PASSWORD || "";

  const loginPage = await fetch(BASE + "/login");
  const html = await loginPage.text();
  const csrfMatch = html.match(/name="_csrf".*?value="([^"]+)"/);
  const csrf = csrfMatch ? csrfMatch[1] : "";
  const pageCookies = loginPage.headers.get("set-cookie") || "";
  const sidMatch1 = pageCookies.match(/connect\.sid=([^;]+)/);
  const csrfCookie1 = pageCookies.match(/csrfToken=([^;]+)/);
  const initCookies: string[] = [];
  if (sidMatch1) initCookies.push("connect.sid=" + sidMatch1[1]);
  if (csrfCookie1) initCookies.push("csrfToken=" + csrfCookie1[1]);

  const loginResp = await fetch(BASE + "/login", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", "Cookie": initCookies.join("; ") },
    body: new URLSearchParams({ _csrf: csrf, email, password }).toString(),
    redirect: "manual",
  });
  const setCookie = loginResp.headers.get("set-cookie") || "";
  const sidMatch2 = setCookie.match(/connect\.sid=([^;]+)/);
  const csrfMatch2 = setCookie.match(/csrfToken=([^;]+)/);
  const sid = sidMatch2 ? sidMatch2[1] : (sidMatch1 ? sidMatch1[1] : "");
  const csrfToken = csrfMatch2 ? csrfMatch2[1] : (csrfCookie1 ? csrfCookie1[1] : "");
  const cookies = "connect.sid=" + sid + "; csrfToken=" + csrfToken;

  // Initialize all layers
  for (const layer of LAYERS) {
    await fetch(BASE + "/app?layer=" + layer.id, { headers: { Cookie: cookies } });
    await new Promise(r => setTimeout(r, 100));
  }

  return { email, cookies };
}

async function search(email: string, cookies: string, dr: string, layerId: string): Promise<any[]> {
  const resp = await fetch(BASE + "/api/apps/app/getattributes", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8", Cookie: cookies },
    body: new URLSearchParams({
      ungeocoded: "false", left: "0", bottom: "0", right: "0", top: "0",
      selfilter: "", action: "get", email, layerid: layerId, sort: "prop_id",
      templateExpression: "", q: dr, page: "1", start: "0", limit: "50",
    }).toString(),
    redirect: "manual",
  });

  try {
    const data = await resp.json() as any;
    if (data.success && data.result) {
      return data.result.filter((r: any) => r.drp === dr);
    }
  } catch {
    // non-JSON response, session issue
  }
  return [];
}

async function main() {
  console.log(`Checking ${DRS.length} unique DRs across ${LAYERS.length} layers...\n`);

  const { email, cookies } = await auth();
  console.log("Authenticated. Starting search...\n");

  const found: Map<string, { layer: string; site: string; status: string; propId: string }[]> = new Map();
  const notFound: string[] = [];
  let reqCount = 0;

  for (let i = 0; i < DRS.length; i++) {
    const dr = DRS[i];
    const matches: { layer: string; site: string; status: string; propId: string }[] = [];

    for (const layer of LAYERS) {
      const results = await search(email, cookies, dr, layer.id);
      reqCount++;

      if (results.length > 0) {
        for (const r of results) {
          matches.push({
            layer: layer.name,
            site: r.site || "?",
            status: r.status || "?",
            propId: r.prop_id || "?",
          });
        }
      }
      await new Promise(r => setTimeout(r, 150));
    }

    if (matches.length > 0) {
      found.set(dr, matches);
      const layerNames = [...new Set(matches.map(m => m.layer))].join(", ");
      const site = matches[0].site;
      const status = matches[0].status;
      console.log(`FOUND     ${dr} | site: ${site} | status: ${status} | layers: ${layerNames}`);
    } else {
      notFound.push(dr);
      console.log(`NOT FOUND ${dr}`);
    }

    // Progress update every 20
    if ((i + 1) % 20 === 0) {
      console.log(`  --- Progress: ${i + 1}/${DRS.length} checked (${reqCount} API calls) ---`);
    }
  }

  console.log("\n========================================");
  console.log("SUMMARY");
  console.log("========================================");
  console.log(`Total unique DRs: ${DRS.length}`);
  console.log(`Found:            ${found.size}`);
  console.log(`Not Found:        ${notFound.length}`);
  console.log(`API calls made:   ${reqCount}`);

  if (found.size > 0) {
    console.log("\n--- FOUND DRs ---");
    // Group by site
    const bySite: Record<string, string[]> = {};
    for (const [dr, matches] of found) {
      const site = matches[0].site;
      if (!bySite[site]) bySite[site] = [];
      bySite[site].push(dr);
    }
    for (const [site, drs] of Object.entries(bySite).sort()) {
      console.log(`\n  ${site}: ${drs.length} DRs`);
      for (const dr of drs) {
        const m = found.get(dr);
        if (m) {
          const layers = [...new Set(m.map(x => x.layer))].join(", ");
          console.log(`    ${dr} | ${m[0].status} | ${layers}`);
        }
      }
    }
  }

  if (notFound.length > 0) {
    console.log("\n--- NOT FOUND DRs ---");
    for (const dr of notFound) {
      console.log(`  ${dr}`);
    }
  }
}

main().catch(e => console.error(e));

