DATABASE_URL=$(grep '^DATABASE_URL=' .env.local | cut -d= -f2- | tr -d '"') node -e "
const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);
Promise.all([
  sql\`SELECT COUNT(*) as total FROM meeting_action_items\`,
  sql\`SELECT 
    m.source,
    COUNT(DISTINCT m.id) as meetings_with_actions,
    COUNT(mai.id) as total_actions
  FROM meeting_action_items mai
  JOIN meetings m ON m.id = mai.meeting_id
  GROUP BY m.source\`,
  sql\`SELECT 
    COUNT(*) FILTER (WHERE summary IS NOT NULL AND summary::text LIKE '%action_items%') as has_actions_in_summary,
    COUNT(*) FILTER (WHERE summary IS NULL) as no_summary,
    COUNT(*) as total
  FROM meetings\`,
  sql\`SELECT 
    m.source,
    COUNT(*) as meetings_with_summary_actions
  FROM meetings m
  WHERE summary IS NOT NULL 
    AND jsonb_array_length(summary->'action_items') > 0
  GROUP BY m.source\`,
  sql\`SELECT COUNT(*) as orphan_actions FROM meeting_action_items mai
  WHERE NOT EXISTS (SELECT 1 FROM meetings m WHERE m.id = mai.meeting_id)\`,
