                          </div>
                        </div>
                        {/* UPS transfer notice */}
                        {lookup.upsTransfer?.needed && (
                          <div className="flex items-center gap-2 px-3 py-1.5 bg-amber-500/10 rounded border border-amber-500/20">
                            <ArrowLeftRight className="w-3 h-3 text-amber-400" />
                            <span className="text-[10px] text-amber-400">UPS {lookup.upsTransfer.serial} will transfer: {lookup.upsTransfer.from} → {lookup.upsTransfer.to}</span>
                          </div>
                        )}
                        {/* Scenario + actions */}
                        <div className="flex items-center justify-between">
                          <span className={`text-xs font-medium ${sc.color}`}>Scenario: {sc.label}</span>
                          <div className="flex items-center gap-2">
                            {swapErrors[record.id] && <span className="text-[10px] text-red-400">{swapErrors[record.id]}</span>}
                            {lookup.scenario === 'clean_swap' && (
                              <button
                                onClick={(e) => { e.stopPropagation(); handleSwapFix(record, lookup, true); }}
                                disabled={isFixing}
                                className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white text-xs rounded hover:bg-green-700 disabled:opacity-50"
                              >
                                {isFixing ? <Loader2 className="w-3 h-3 animate-spin" /> : <ArrowLeftRight className="w-3 h-3" />}
                                Swap Both DRs
                              </button>
                            )}
                            <button
                              onClick={(e) => { e.stopPropagation(); handleSwapFix(record, lookup, false); }}
                              disabled={isFixing}
                              className={`flex items-center gap-1 px-3 py-1.5 text-white text-xs rounded disabled:opacity-50 ${lookup.upsTransfer?.needed ? 'bg-amber-600 hover:bg-amber-700' : 'bg-blue-600 hover:bg-blue-700'}`}
                            >
                              {isFixing ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wrench className="w-3 h-3" />}
                              {lookup.upsTransfer?.needed ? 'Fix A + Transfer UPS' : 'Fix DR A Only'}
                            </button>
                          </div>
                        </div>
                        <p className="text-[10px] text-[var(--ff-text-tertiary)] leading-relaxed">{lookup.recommendation}</p>
                      </div>
                    );
                  })()}
                </div>
              </div>
            )}
          </td>
        </tr>
      );
    } catch {
      return null;
    }
  };

  return (
    <>
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
        {/* Sub-filter bar + ticket actions */}
        {records.length > 0 && (
          <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--ff-border-light)]">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[var(--ff-text-secondary)] mr-1">Filter:</span>
              {([
                { key: 'all', label: 'All', count: stats.needs_investigation },
                { key: 'needs_investigation', label: 'Cross-DR Conflict', count: investigateSubCounts.cross_dr },
                { key: 'not_found', label: 'Not on 1Map', count: investigateSubCounts.not_found },
                { key: 'other', label: 'Other', count: investigateSubCounts.other },
              ] as const).map(({ key, label, count }) => (
                <button
                  key={key}
                  onClick={() => { setInvestigateSubFilter(key); setPage(1); }}
                  className={`px-3 py-1 text-xs rounded-full border transition-colors ${
                    investigateSubFilter === key
                      ? 'bg-[var(--ff-accent)] text-white border-[var(--ff-accent)]'
                      : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:border-[var(--ff-accent)]'
                  }`}
                >
                  {label} ({count})
                </button>
              ))}
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={handleSelectAllNotFound}
                disabled={selectingAll}
                className="px-3 py-1.5 bg-amber-600 text-white text-xs rounded hover:bg-amber-700
                           disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1.5"
              >
                {selectingAll ? (
                  <><Loader2 className="w-3 h-3 animate-spin" /> Loading...</>
                ) : (
                  <><Ticket className="w-3 h-3" /> Ticket All ({stats.needs_investigation})</>
                )}
              </button>
              {selectedIds.size > 0 && (
                <button
                  onClick={() => setShowTicketModal(true)}
                  className="px-3 py-1.5 bg-red-600 text-white text-xs rounded hover:bg-red-700
                             flex items-center gap-1.5"
                >
                  <Ticket className="w-3 h-3" />
                  Create {selectedIds.size} Ticket{selectedIds.size !== 1 ? 's' : ''}
                </button>
              )}
            </div>
          </div>
        )}

        <OltRecordTable
          records={records}
          mode="investigate"
          page={page}
          total={total}
          pageSize={pageSize}
          onPageChange={setPage}
          isLoading={isLoading}
          isStatusMismatch={isStatusMismatch}
          getInvestigationContext={getInvestigationContext}
          onResolve={(id) => setShowResolveModal(id)}
          onEscalate={(id) => setShowEscalateModal(id)}
          expandedContexts={expandedContexts}
          onToggleContext={toggleContext}
          renderContextRow={renderContextRow}
          selectedIds={selectedIds}
          onToggleSelect={toggleSelect}
          onToggleSelectAll={toggleSelectAll}
          isSelectable={isSelectable}
        />
      </div>

      {/* Modals */}
      {showResolveModal && (
        <OltResolveModal
          recordId={showResolveModal}
          onClose={() => setShowResolveModal(null)}
          onResolved={onResolved}
          setError={setError}
        />
      )}
      {showEscalateModal && (
        <OltEscalateModal
          recordId={showEscalateModal}
          onClose={() => setShowEscalateModal(null)}
          onEscalated={onResolved}
          setError={setError}
        />
      )}
      {showTicketModal && (
        <CreateOltTicketsModal
          selectedCount={selectedIds.size}
          onConfirm={handleCreateTickets}
          onClose={() => setShowTicketModal(false)}
          loading={creatingTickets}
        />
      )}
    </>
  );
}

/**
 * OLT Report Group Component — thin shell
 * Delegates to useOltState hook and per-tab components.
 */

'use client';

import React from 'react';
import { Loader2, Lock } from 'lucide-react';
import { useOltState, OLT_TABS } from '../../hooks/useOltState';
import { OltAutoDetectBanner } from './olt/OltAutoDetectBanner';
import { OltImportTab } from './olt/OltImportTab';
import { OltFixableTab } from './olt/OltFixableTab';
import { OltInvestigateTab } from './olt/OltInvestigateTab';
import { OltEscalationsTab } from './olt/OltEscalationsTab';
import { OltFixLogTab } from './olt/OltFixLogTab';
import { OltReportingTab } from './olt/OltReportingTab';

interface OltReportGroupProps {
  activeTab: string | null;
  onTabChange: (tabId: string) => void;
}

export function OltReportGroup({ activeTab, onTabChange }: OltReportGroupProps) {
  const state = useOltState(activeTab, onTabChange);

  // Loading state while permissions resolve
  if (state.permissionsLoading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-8 h-8 animate-spin text-[var(--ff-accent)]" />
        <span className="ml-3 text-[var(--ff-text-secondary)]">Loading...</span>
      </div>
    );
  }

  // Access denied
  if (state.accessibleTabs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center">
        <div className="w-16 h-16 mb-4 rounded-full bg-red-500/10 flex items-center justify-center">
          <Lock className="w-8 h-8 text-red-400" />
        </div>
        <h2 className="text-xl font-semibold text-[var(--ff-text-primary)] mb-2">Access Restricted</h2>
        <p className="text-[var(--ff-text-secondary)] max-w-md">
          You don&apos;t have permission to access any OLT Report tabs.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Auto-Detect Banner — visible on all tabs */}
      <OltAutoDetectBanner autoDetectStatus={state.autoDetectStatus} />

      {/* Tab Navigation */}
      <div className="border-b border-[var(--ff-border-light)]">
        <nav className="flex gap-1 overflow-x-auto scrollbar-hide" aria-label="OLT Report Tabs">
          {state.accessibleTabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = state.currentTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  state.setPage(1);
                  onTabChange(tab.id);
                }}
                className={`
                  flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap
                  ${isActive
                    ? 'border-[var(--ff-accent)] text-[var(--ff-accent)]'
                    : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-medium)]'
                  }
                `}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
                {tab.id === 'pending' && state.stats.pending > 0 && (
                  <span className="ml-1 px-2 py-0.5 text-xs bg-amber-500/20 text-amber-400 rounded-full">
                    {state.stats.pending}
                  </span>
                )}
                {tab.id === 'investigate' && state.stats.needs_investigation > 0 && (
                  <span className="ml-1 px-2 py-0.5 text-xs bg-red-500/20 text-red-400 rounded-full">
                    {state.stats.needs_investigation}
                  </span>
                )}
              </button>
            );
          })}
        </nav>
      </div>

      {/* Error Display */}
      {state.error && (
        <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400">
          {state.error}
          <button onClick={() => state.setError(null)} className="ml-4 text-sm underline hover:no-underline">
            Dismiss
          </button>
        </div>
      )}

      {/* Tab Content */}
      {state.currentTab === 'import' && (
        <OltImportTab
          autoDetectStatus={state.autoDetectStatus}
          fetchStats={state.fetchStats}
        />
      )}

      {state.currentTab === 'pending' && (
        <OltFixableTab
          records={state.records}
          stats={state.stats}
          isLoading={state.isLoading}
          page={state.page}
          total={state.total}
          pageSize={state.pageSize}
          setPage={state.setPage}
          fixing={state.fixing}
          fixErrors={state.fixErrors}
          setFixErrors={state.setFixErrors}
          handleFix={state.handleFix}
          isStatusMismatch={state.isStatusMismatch}
          getInvestigationContext={state.getInvestigationContext}
          fetchRecords={state.fetchRecords}
          fetchStats={state.fetchStats}
        />
      )}

      {state.currentTab === 'investigate' && (
        <OltInvestigateTab
          records={state.records}
          stats={state.stats}
          isLoading={state.isLoading}
          page={state.page}
          total={state.total}
          pageSize={state.pageSize}
          setPage={state.setPage}
          setError={state.setError}
          isStatusMismatch={state.isStatusMismatch}
          getInvestigationContext={state.getInvestigationContext}
          fetchRecords={state.fetchRecords}
          fetchStats={state.fetchStats}
        />
      )}

      {state.currentTab === 'escalations' && (
        <OltEscalationsTab
          records={state.records}
          isLoading={state.isLoading}
          page={state.page}
          total={state.total}
          pageSize={state.pageSize}
          setPage={state.setPage}
          isStatusMismatch={state.isStatusMismatch}
          getInvestigationContext={state.getInvestigationContext}
        />
      )}

      {state.currentTab === 'history' && (
        <OltFixLogTab
          fixHistory={state.fixHistory}
          imports={state.imports}
          stats={state.stats}
          isLoading={state.isLoading}
          total={state.total}
          dateFilter={state.dateFilter}
          customDate={state.customDate}
          statusFilter={state.statusFilter}
          setDateFilter={state.setDateFilter}
          setCustomDate={state.setCustomDate}
          setStatusFilter={state.setStatusFilter}
        />
      )}

      {state.currentTab === 'reporting' && (
        <OltReportingTab setError={state.setError} />
      )}
    </div>
  );
}

