  }
}

/**
 * Get ticket by ID
 *
 * @param id - Ticket UUID
 * @returns Ticket data
 * @throws {Error} If ticket not found or ID invalid
 */
export async function getTicketById(id: string): Promise<Ticket> {
  // 🟢 WORKING: Validate ID format
  if (!isValidUUID(id)) {
    throw new Error('Invalid ticket ID format');
  }

  logger.debug('Fetching ticket by ID', { id });

  try {
    // Include assigned user and team info via LEFT JOINs
    const sql = `
      SELECT
        t.*,
        CASE
          WHEN u.id IS NOT NULL THEN jsonb_build_object(
            'id', u.id,
            'name', COALESCE(u.first_name || ' ' || u.last_name, u.email),
            'email', u.email
          )
          ELSE NULL
        END as assigned_user,
        tm.name as assigned_team_name
      FROM maintenance_tickets t
      LEFT JOIN users u ON t.assigned_to = u.id
      LEFT JOIN teams tm ON t.assigned_team_id = tm.id
      WHERE t.id = $1
    `;
    const ticket = await queryOne<Ticket & { assigned_user?: { id: string; name: string; email: string }; assigned_team_name?: string }>(sql, [id]);

    if (!ticket) {
      throw new Error(`Ticket with ID ${id} not found`);
    }

    logger.debug('Ticket fetched successfully', { id, ticket_uid: ticket.ticket_uid });

    return ticket;
  } catch (error) {
    logger.error('Failed to fetch ticket', { error, id });
    throw error;
  }
}

/**
 * Update ticket (partial update)
 *
 * @param id - Ticket UUID
 * @param payload - Fields to update
 * @returns Updated ticket
 * @throws {Error} If ticket not found or update fails
 */
export async function updateTicket(
  id: string,
  payload: UpdateTicketPayload
): Promise<Ticket> {
  // 🟢 WORKING: Validate empty payload
  if (!payload || Object.keys(payload).length === 0) {
    throw new Error('Update payload cannot be empty');
  }

  logger.info('Updating ticket', { id, fields: Object.keys(payload) });

  try {
    // 🟢 WORKING: Build dynamic UPDATE query based on provided fields
    const updateFields: string[] = [];
    const values: any[] = [];
    let paramCounter = 1;

    // Map of payload keys to database columns
    const fieldMap: Record<string, string> = {
      title: 'title',
      description: 'description',
      status: 'status',
      priority: 'priority',
      assigned_to: 'assigned_to',
      assigned_contractor_id: 'assigned_contractor_id',
      assigned_team: 'assigned_team',
      assigned_team_id: 'assigned_team_id',
      dr_number: 'dr_number',
      project_id: 'project_id',
      zone_id: 'zone_id',
      pole_number: 'pole_number',
      pon_number: 'pon_number',
      address: 'address',
      ont_serial: 'ont_serial',
      ont_rx_level: 'ont_rx_level',
      ont_model: 'ont_model',
      fault_cause: 'fault_cause',
      fault_cause_details: 'fault_cause_details',
      guarantee_status: 'guarantee_status',
      guarantee_expires_at: 'guarantee_expires_at',
      is_billable: 'is_billable',
      billing_classification: 'billing_classification',
      qa_ready: 'qa_ready',
      sla_due_at: 'sla_due_at',
      sla_first_response_at: 'sla_first_response_at',
      sla_breached: 'sla_breached'
    };

    // Build SET clause dynamically
    for (const [key, value] of Object.entries(payload)) {
      if (key in fieldMap) {
        const dbColumn = fieldMap[key];
        updateFields.push(`${dbColumn} = $${paramCounter}`);
        values.push(value);
        paramCounter++;
      }
    }

    // Always update updated_at
    updateFields.push('updated_at = NOW()');

    // Add ID as last parameter
    values.push(id);

    const sql = `
      UPDATE maintenance_tickets
      SET ${updateFields.join(', ')}
      WHERE id = $${paramCounter}
      RETURNING *
    `;

    const updatedTicket = await queryOne<Ticket>(sql, values);

    if (!updatedTicket) {
      throw new Error(`Ticket with ID ${id} not found`);
    }

    logger.info('Ticket updated successfully', {
      id,
      ticket_uid: updatedTicket.ticket_uid
    });

    return updatedTicket;
  } catch (error) {
    logger.error('Failed to update ticket', { error, id, payload });
    throw error;
  }
}

/**
 * Delete ticket (soft delete - marks as CANCELLED)
 *
 * We never hard delete tickets for audit trail purposes.
 * Instead, we mark them as CANCELLED.
 *
 * @param id - Ticket UUID
 * @returns Deleted (cancelled) ticket
 * @throws {Error} If ticket not found
 */
export async function deleteTicket(id: string): Promise<Ticket> {
  logger.info('Soft deleting ticket (marking as CANCELLED)', { id });

  try {
    // 🟢 WORKING: Soft delete by updating status to CANCELLED
    const sql = `
      UPDATE maintenance_tickets
      SET status = $1, updated_at = NOW()
      WHERE id = $2
      RETURNING *
    `;

    const deletedTicket = await queryOne<Ticket>(sql, [TicketStatus.CANCELLED, id]);

    if (!deletedTicket) {
      throw new Error(`Ticket with ID ${id} not found`);
    }

    logger.info('Ticket soft deleted successfully', {
      id,
      ticket_uid: deletedTicket.ticket_uid
    });

    return deletedTicket;
  } catch (error) {
    logger.error('Failed to delete ticket', { error, id });
    throw error;
  }
}

/**
 * Combined filters and pagination interface
 */
export interface ListTicketsParams extends Partial<TicketFilters> {
  page?: number;
  pageSize?: number;
}

/**
 * List tickets with filters and pagination
 *
 * @param filters - Filter criteria (status, type, assignee, etc.) and pagination
 * @returns Paginated list of tickets
 */
export async function listTickets(
  filters: ListTicketsParams = {}
): Promise<TicketListResponse> {
  logger.debug('Listing tickets', { filters });

  try {
    // 🟢 WORKING: Build WHERE clause based on filters
    const whereClauses: string[] = [];
    const values: any[] = [];
    let paramCounter = 1;

    if (filters.status) {
      whereClauses.push(`status = $${paramCounter}`);
      values.push(filters.status);
      paramCounter++;
    }

    if (filters.ticket_type) {
      // Note: Using 'type' column which exists in the current schema
      whereClauses.push(`type = $${paramCounter}`);
      values.push(filters.ticket_type);
      paramCounter++;
    }

    if (filters.assigned_to) {
      // assigned_to column stores staff.id, but auth provides users.id
      // Look up staff_id first, fall back to the value as-is
      const staffLookup = await queryOne<{ id: string }>(
        `SELECT id FROM staff WHERE user_id = $1 LIMIT 1`,
        [filters.assigned_to]
      );
      const resolvedId = staffLookup?.id || filters.assigned_to;
      whereClauses.push(`assigned_to = $${paramCounter}`);
      values.push(resolvedId);
      paramCounter++;
    }

    if (filters.assigned_contractor_id) {
      // Note: Using 'contractor_id' column which exists in the current schema
      whereClauses.push(`contractor_id = $${paramCounter}`);
      values.push(filters.assigned_contractor_id);
      paramCounter++;
    }

    if (filters.priority) {
      whereClauses.push(`priority = $${paramCounter}`);
      values.push(filters.priority);
      paramCounter++;
    }

    if (filters.source) {
      whereClauses.push(`source = $${paramCounter}`);
      values.push(filters.source);
      paramCounter++;
    }

    if (filters.assigned_team_id) {
      whereClauses.push(`assigned_team_id = $${paramCounter}`);
      values.push(filters.assigned_team_id);
      paramCounter++;
    }

    if (filters.project_id) {
      whereClauses.push(`project_id = $${paramCounter}`);
      values.push(filters.project_id);
      paramCounter++;
    }

    if (filters.dr_number) {
      whereClauses.push(`dr_number = $${paramCounter}`);
      values.push(filters.dr_number);
      paramCounter++;
    }

    if (filters.qa_ready !== undefined) {
      // Note: Using 'qa_verified' column which exists in the current schema
      whereClauses.push(`qa_verified = $${paramCounter}`);
      values.push(filters.qa_ready);
      paramCounter++;
    }

    if (filters.sla_breached !== undefined) {
      whereClauses.push(`sla_breached = $${paramCounter}`);
      values.push(filters.sla_breached);
      paramCounter++;
    }

    // 🟢 WORKING: Search filter - searches ticket_uid, dr_number, title, and description
    // Each column needs its own parameter index because the neon HTTP driver
    // splits by $N placeholders to build tagged template literals.
    if (filters.search && filters.search.trim()) {
      const searchTerm = `%${filters.search.trim()}%`;
      const p1 = paramCounter++;
      const p2 = paramCounter++;
      const p3 = paramCounter++;
      const p4 = paramCounter++;
      whereClauses.push(`(
        ticket_uid ILIKE $${p1} OR
        dr_number ILIKE $${p2} OR
        title ILIKE $${p3} OR
        description ILIKE $${p4}
      )`);
      values.push(searchTerm, searchTerm, searchTerm, searchTerm);
    }

    // 🟢 WORKING: Build WHERE clause
    const whereClause = whereClauses.length > 0
      ? `WHERE ${whereClauses.join(' AND ')}`
      : '';

    // 🟢 WORKING: Pagination (default: page 1, pageSize 50)
    const page = filters.page || 1;
    const pageSize = filters.pageSize || 50;
    const offset = (page - 1) * pageSize;

    // Add LIMIT and OFFSET as last parameters
    values.push(pageSize);
    const limitParam = paramCounter;
    paramCounter++;

    values.push(offset);
    const offsetParam = paramCounter;

    // 🟢 WORKING: First get the total count (without pagination)
    const countSql = `
      SELECT COUNT(*) as count
      FROM maintenance_tickets t
      ${whereClause ? whereClause.replace(/\b(status|type|priority|source|assigned_to|contractor_id|project_id|dr_number|qa_verified|sla_breached|assigned_team_id|ticket_uid|title|description)\b/g, 't.$1') : ''}
    `;
    // Count query uses same filter values but without LIMIT/OFFSET
    const countValues = values.slice(0, -2); // Remove the last two values (limit and offset)
    const countResult = await queryOne<{ count: string }>(countSql, countValues);
    const totalCount = parseInt(countResult?.count || '0', 10);

    // 🟢 WORKING: Query with pagination, ordering, and assigned user/team info
    const sql = `
      SELECT
        t.*,
        CASE
          WHEN u.id IS NOT NULL THEN jsonb_build_object(
            'id', u.id,
            'name', COALESCE(u.first_name || ' ' || u.last_name, u.email),
            'email', u.email
          )
          ELSE NULL
        END as assigned_user,
        tm.name as assigned_team_name
      FROM maintenance_tickets t
      LEFT JOIN users u ON t.assigned_to = u.id
      LEFT JOIN teams tm ON t.assigned_team_id = tm.id
      ${whereClause ? whereClause.replace(/\b(status|type|priority|source|assigned_to|contractor_id|project_id|dr_number|qa_verified|sla_breached|assigned_team_id|ticket_uid|title|description)\b/g, 't.$1') : ''}
      ORDER BY t.created_at DESC
      LIMIT $${limitParam} OFFSET $${offsetParam}
    `;

    const tickets = await query<Ticket & { assigned_user?: { id: string; name: string; email: string }; assigned_team_name?: string }>(sql, values);

    logger.debug('Tickets fetched successfully', {
      count: tickets.length,
      total: totalCount,
      page,
      pageSize
    });

    return {
      tickets,
      total: totalCount,
      page,
      limit: pageSize,
      total_pages: Math.ceil(totalCount / pageSize)
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    if (errorMessage.includes('relation') && errorMessage.includes('does not exist')) {
      logger.warn('Tickets table does not exist - returning empty list. Run migrations to create tables.');
      return {
        tickets: [],
        total: 0,
        page: filters.page || 1,
        limit: filters.pageSize || 50,
        total_pages: 0
      };
    }
    logger.error('Failed to list tickets', { error, filters });
    throw error;
  }
}

/**
 * Export generateTicketUID for use in migration scripts
 */
export { generateTicketUID };

/**
 * Maintenance Module - Database Connection Utility
 *
 * Neon PostgreSQL serverless connection with:
 * - Connection pooling (lazy initialization)
 * - Query helpers (query, queryOne)
 * - Transaction support with automatic rollback
 * - SQL injection prevention (parameterized queries)
 * - Error handling and logging
 * - Health checks
 *
 * 🟢 WORKING: Production-ready database utility for maintenance module
 *
 * NOTE: Uses neon() HTTP driver with a query helper that converts
 * parameterized queries to tagged template literals.
 */

import { neon, NeonQueryFunction } from '@/lib/db-neon';
import { createLogger } from '@/lib/logger';

const logger = createLogger('maintenance:db');

/**
 * Database connection instance (lazy initialization)
 */
let connection: NeonQueryFunction<false, false> | null = null;

/**
 * Get database URL from environment
 * @throws {Error} If DATABASE_URL is not set
 */
function getDatabaseUrl(): string {
  // Server-only: never use NEXT_PUBLIC_ prefix (leaks credentials to client bundle)
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    const error = new Error('DATABASE_URL environment variable is required');
    logger.error('Database configuration error', { error: error.message });
    throw error;
  }

  return databaseUrl;
}

/**
 * Get or create database connection (lazy initialization)
 *
 * Connection is created once and reused for all queries.
 * This is safe for serverless environments as Neon HTTP is stateless.
 *
 * @returns {NeonQueryFunction} Neon SQL query function
 */
export function getConnection(): NeonQueryFunction<false, false> {
  if (!connection) {
    const databaseUrl = getDatabaseUrl();
    connection = neon(databaseUrl);
    // Log partial URL for debugging (hide password)
    const safeUrl = databaseUrl.replace(/:[^:@]+@/, ':***@');
    logger.info('Database connection initialized', { url: safeUrl });
  }

  return connection;
}

/**
 * Execute a parameterized query using the neon HTTP driver
 *
 * Converts $1, $2 placeholders to a tagged template literal call.
 * This is necessary because the neon() function only works as a
 * tagged template literal in newer versions.
 */
async function executeParameterizedQuery<T>(
  sql: NeonQueryFunction<false, false>,
  queryText: string,
  params: unknown[]
): Promise<T[]> {
  // Split query by $N placeholders and create template strings array
  const parts = queryText.split(/\$\d+/);

  // Create a mock TemplateStringsArray
  const strings = Object.assign([...parts], { raw: parts });

  // Call the sql function as if it were a tagged template
  const result = await (sql as Function)(strings, ...params);

  return result as T[];
}

/**
 * Execute a SQL query with parameters
 *
 * Uses parameterized queries to prevent SQL injection.
 * Parameters are passed as $1, $2, etc. in the query string.
 *
 * @param {string} queryText - SQL query with $1, $2... placeholders
 * @param {any[]} params - Query parameters
 * @returns {Promise<T[]>} Query results
 *
 * @example
 * const tickets = await query('SELECT * FROM maintenance_tickets WHERE status = $1', ['open']);
 */
export async function query<T = any>(
  queryText: string,
  params: any[] = []
): Promise<T[]> {
  const startTime = Date.now();

  try {
    const sql = getConnection();

    // Execute query using the parameterized query helper
    const result = await executeParameterizedQuery<T>(sql, queryText, params);

    const duration = Date.now() - startTime;

    logger.debug('Query executed', {
      duration,
      rowCount: Array.isArray(result) ? result.length : 0,
      query: queryText.substring(0, 100) // Log first 100 chars
    });

    return result;
  } catch (error) {
    const duration = Date.now() - startTime;

    logger.error('Query failed', {
      error: error instanceof Error ? error.message : String(error),
      duration,
      query: queryText.substring(0, 100),
      paramsCount: params.length
    });

    throw error;
  }
}

/**
 * Execute a query and return only the first result
 *
 * Useful for queries that should return a single row (e.g., SELECT by ID).
 *
 * @param {string} queryText - SQL query with $1, $2... placeholders
 * @param {any[]} params - Query parameters
 * @returns {Promise<T | null>} First row or null if no results
 *
 * @example
 * const ticket = await queryOne('SELECT * FROM maintenance_tickets WHERE id = $1', [ticketId]);
 */
export async function queryOne<T = any>(
  queryText: string,
  params: any[] = []
): Promise<T | null> {
  const results = await query<T>(queryText, params);
  return results.length > 0 ? results[0] : null;
}

/**
 * Transaction context for executing multiple queries atomically
 */
interface TransactionContext {
  /**
   * Execute a query within the transaction
   */
  query<T = any>(queryText: string, params?: any[]): Promise<T[]>;

  /**
   * Execute a query and return first result
   */
  queryOne<T = any>(queryText: string, params?: any[]): Promise<T | null>;
}

/**
 * Execute multiple queries in a transaction
 *
 * All queries succeed or all are rolled back on error.
 * Automatically handles BEGIN, COMMIT, and ROLLBACK.
 *
 * @param {Function} callback - Transaction callback with transaction context
 * @returns {Promise<T>} Result of the transaction callback
 *
 * @example
 * const result = await transaction(async (txn) => {
 *   const ticket = await txn.queryOne(
 *     'INSERT INTO maintenance_tickets (ticket_uid) VALUES ($1) RETURNING *',
 *     ['FT001']
 *   );
 *   await txn.query(
 *     'INSERT INTO maintenance_notes (ticket_id, content) VALUES ($1, $2)',
 *     [ticket.id, 'Created ticket']
 *   );
 *   return ticket;
 * });
 */
export async function transaction<T>(
  callback: (txn: TransactionContext) => Promise<T>
): Promise<T> {
  const sql = getConnection();
  const startTime = Date.now();

  // Note: Neon HTTP driver doesn't support true transactions.
  // This implementation runs queries sequentially but doesn't provide
  // atomicity guarantees. For true transactions, use Pool with WebSocket.
  logger.warn('Transaction called with HTTP driver - no atomicity guarantee');

  try {
    // Create transaction context using the query helper
    const txnContext: TransactionContext = {
      query: async <R = any>(queryText: string, params: any[] = []): Promise<R[]> => {
        return executeParameterizedQuery<R>(sql, queryText, params);
      },
      queryOne: async <R = any>(queryText: string, params: any[] = []): Promise<R | null> => {
        const results = await executeParameterizedQuery<R>(sql, queryText, params);
        return results.length > 0 ? results[0] : null;
      }
    };

    // Execute callback
    const result = await callback(txnContext);

    const duration = Date.now() - startTime;
    logger.debug('Transaction completed', { duration });

    return result;
  } catch (error) {
    const duration = Date.now() - startTime;
    logger.error('Transaction failed', {
      error: error instanceof Error ? error.message : String(error),
      duration
    });

    throw error;
  }
}

/**
 * Health check result
 */
export interface HealthCheckResult {
  /**
   * Whether the database is healthy
   */
  isHealthy: boolean;

  /**
   * Query latency in milliseconds
   */
  latency?: number;

  /**
   * Error message if unhealthy
   */
  error?: string;

  /**
   * Timestamp of the check
   */
  timestamp: Date;
}

/**
 * Check database connection health
 *
 * Executes a simple query to verify database connectivity and measure latency.
 *
 * @returns {Promise<HealthCheckResult>} Health check result
 */
export async function healthCheck(): Promise<HealthCheckResult> {
  const startTime = Date.now();

  try {
    const sql = getConnection();
    await executeParameterizedQuery(sql, 'SELECT NOW() as now', []);

    const latency = Date.now() - startTime;

    logger.debug('Health check passed', { latency });

    return {
      isHealthy: true,
      latency,
      timestamp: new Date()
    };
  } catch (error) {
    const latency = Date.now() - startTime;

    logger.error('Health check failed', {
      error: error instanceof Error ? error.message : String(error),
      latency
    });

    return {
      isHealthy: false,
      latency,
      error: error instanceof Error ? error.message : 'Unknown error',
      timestamp: new Date()
    };
  }
}

/**
 * Close database connection
 *
 * Resets the connection instance, forcing a new connection on next use.
 * Safe to call multiple times.
 */
export async function closeConnection(): Promise<void> {
  if (connection) {
    connection = null;
    logger.info('Database connection closed');
  }
}

/**
 * Export connection management utilities
 */
export const db = {
  /**
   * Get connection instance
   */
  getConnection,

  /**
   * Execute a query
   */
  query,

  /**
   * Execute a query and return first result
   */
  queryOne,

  /**
   * Execute a transaction
   */
  transaction,

  /**
   * Check database health
   */
  healthCheck,

  /**
   * Close connection
   */
  close: closeConnection
};

/**
 * Default export for convenience
 */
export default db;

