CREATE OR REPLACE FUNCTION public.generate_ticket_uid()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  current_year TEXT;
  next_sequence INTEGER;
  new_uid TEXT;
BEGIN
  IF NEW.ticket_uid IS NULL THEN
    current_year := TO_CHAR(NOW(), 'YYYY');

    SELECT COALESCE(MAX(
      CAST(SUBSTRING(ticket_uid FROM 'TKT-' || current_year || '-([0-9]+)$') AS INTEGER)
    ), 0) + 1
    INTO next_sequence
    FROM tickets
    WHERE ticket_uid LIKE 'TKT-' || current_year || '-%';

    new_uid := 'TKT-' || current_year || '-' || LPAD(next_sequence::TEXT, 5, '0');
    NEW.ticket_uid := new_uid;
  END IF;

  RETURN NEW;
END;
$function$

