(async () => {
  // Verify project IDs
  const projects = await sql`SELECT id, project_name FROM projects ORDER BY project_name`;
  const projMap = {};
  for (const p of projects) projMap[p.project_name] = p.id;

  for (const proj of PROJECTS) {
    const realId = projMap[proj.name];
    if (!realId) { console.log(`SKIP ${proj.name}: not found`); continue; }
    if (realId !== proj.ffId) {
      console.log(`FIX ${proj.name}: ${proj.ffId} -> ${realId}`);
      proj.ffId = realId;
    }

    const db = new Database(proj.gpkg);
    const rows = db.prepare(`SELECT * FROM [${proj.table}]`).all();
    db.close();

    const existing = await sql`SELECT pole_number FROM poles WHERE project_id = ${proj.ffId}::uuid`;
    const existingSet = new Set(existing.map(p => p.pole_number));

    const { cols } = proj;
    let created = 0, errors = 0;

    for (const row of rows) {
      const label = (row[cols.label] || '').toString().trim();
      if (!label || existingSet.has(label)) continue;

      const lat = row[cols.lat] ? Number(row[cols.lat]) : null;
      const lon = row[cols.lon] ? Number(row[cols.lon]) : null;
      const ponNo = cols.pon ? (row[cols.pon] != null ? String(row[cols.pon]).trim() : null) : null;
      const zoneNo = cols.zone ? (row[cols.zone] != null ? String(row[cols.zone]).trim() : null) : null;
      const status = cols.status ? mapStatus(row[cols.status]) : 'planned';
      const fieldAgent = cols.agent ? (row[cols.agent] || null) : null;

      try {
        await sql`
