/**
 * OltInvestigateTab — records needing investigation with cross-DR swap panel + bulk ticketing
 */

'use client';

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import {
  AlertTriangle,
  ChevronDown,
  ChevronRight,
  Search,
  ExternalLink,
  Loader2,
  Wrench,
  XCircle,
  CheckCircle,
  ArrowLeftRight,
  Ticket,
} from 'lucide-react';
import type { OltRecord, OltStats, InvestigationContext, SwapLookupResult } from '../../../types';
import { OltRecordTable } from './OltRecordTable';
import { OltResolveModal } from './OltResolveModal';
import { OltEscalateModal } from './OltEscalateModal';
import { CreateOltTicketsModal } from './CreateOltTicketsModal';

interface OltInvestigateTabProps {
  records: OltRecord[];
  stats: OltStats;
  isLoading: boolean;
  page: number;
  total: number;
  pageSize: number;
  setPage: (p: number | ((prev: number) => number)) => void;
  setError: (e: string | null) => void;
  isStatusMismatch: (record: OltRecord) => boolean;
  getInvestigationContext: (record: OltRecord) => InvestigationContext | null;
  fetchRecords: (status: string, subStatus?: string, search?: string) => Promise<void>;
  fetchStats: () => Promise<void>;
}

export function OltInvestigateTab({
  records,
  stats,
  isLoading,
  page,
  total,
  pageSize,
  setPage,
  setError,
  isStatusMismatch,
  getInvestigationContext,
  fetchRecords,
  fetchStats,
}: OltInvestigateTabProps) {
  // Local state
  const [investigateSubFilter, setInvestigateSubFilter] = useState<string>('all');
  const [expandedContexts, setExpandedContexts] = useState<Set<string>>(new Set());
  const [showResolveModal, setShowResolveModal] = useState<string | null>(null);
  const [showEscalateModal, setShowEscalateModal] = useState<string | null>(null);
  const [searchText, setSearchText] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Ticketing state
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showTicketModal, setShowTicketModal] = useState(false);
  const [creatingTickets, setCreatingTickets] = useState(false);
  const [selectingAll, setSelectingAll] = useState(false);

  // Cross-DR swap state
  const [swapLookups, setSwapLookups] = useState<Record<string, SwapLookupResult>>({});
  const [swapLoading, setSwapLoading] = useState<Set<string>>(new Set());
  const [swapErrors, setSwapErrors] = useState<Record<string, string>>({});

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchText);
      setPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchText, setPage]);

  // Re-fetch when sub-filter or search changes
  useEffect(() => {
    const sub = investigateSubFilter !== 'all' ? investigateSubFilter : undefined;
    fetchRecords('needs_investigation', sub, debouncedSearch || undefined);
    setSelectedIds(new Set());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [investigateSubFilter, debouncedSearch]);

  const toggleContext = (id: string) => {
    setExpandedContexts(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const investigateSubCounts = stats.investigateBreakdown || { cross_dr: 0, not_found: 0, other: 0 };

  // Selection helpers
  const isSelectable = (record: OltRecord) =>
    !record.maintenance_ticket_id &&
    ['needs_investigation', 'not_found', 'empty_serial'].includes(record.fix_status || '');

  const selectableOnPage = records.filter(isSelectable);

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === selectableOnPage.length && selectableOnPage.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(selectableOnPage.map(r => r.id)));
    }
  };

  const handleSelectAllNotFound = async () => {
    setSelectingAll(true);
    try {
      const res = await fetch('/api/system/olt-report/records?status=needs_investigation&limit=10000&fields=id,fix_status,maintenance_ticket_id');
      const data = await res.json();
      const allRecords = (data.data?.records || data.records || []) as OltRecord[];
      const ticketable = allRecords.filter((r: OltRecord) =>
        !r.maintenance_ticket_id &&
        ['needs_investigation', 'not_found', 'empty_serial'].includes(r.fix_status || '')
      );
      setSelectedIds(new Set(ticketable.map((r: OltRecord) => r.id)));
      toast.success(`Selected ${ticketable.length} records for ticketing`);
    } catch {
      toast.error('Failed to load all records');
    } finally {
      setSelectingAll(false);
    }
  };

  const handleCreateTickets = async (params: { ticket_type: string; priority: string; notes: string; assigned_team_id?: string }) => {
    setCreatingTickets(true);
    try {
      const res = await fetch('/api/system/olt-report/tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ record_ids: Array.from(selectedIds), ...params }),
      });
      const result = await res.json();
      if (!res.ok) throw new Error(result.error?.message || result.error || 'Failed to create tickets');
      const { created, skipped } = result.data;
      toast.success(`Created ${created} ticket${created !== 1 ? 's' : ''}${skipped > 0 ? ` (${skipped} skipped)` : ''}`);
      setShowTicketModal(false);
      setSelectedIds(new Set());
      fetchRecords('needs_investigation', investigateSubFilter !== 'all' ? investigateSubFilter : undefined);
      fetchStats();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create tickets');
    } finally {
      setCreatingTickets(false);
    }
  };

  // Cross-DR lookup
  const handleSwapLookup = async (record: OltRecord) => {
    if (!record.investigation_context) return;
    let ctx: InvestigationContext;
    try { ctx = JSON.parse(record.investigation_context); } catch { return; }

    setSwapLoading(prev => new Set(prev).add(record.id));
    setSwapErrors(prev => { const n = { ...prev }; delete n[record.id]; return n; });

    try {
      const res = await fetch('/api/system/olt-report/cross-dr-lookup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          recordId: record.id,
          drNumber: record.drop_number,
          wrongSerial: ctx.wrongSerial,
          belongsToDr: ctx.belongsToDr,
        }),
      });
      const data = await res.json();
      const result = data.data || data;
      if (result.drA) {
        setSwapLookups(prev => ({ ...prev, [record.id]: result }));
      } else {
        const errMsg = typeof result.error === 'string' ? result.error : result.error?.message || 'Lookup failed';
        setSwapErrors(prev => ({ ...prev, [record.id]: errMsg }));
      }
    } catch {
      setSwapErrors(prev => ({ ...prev, [record.id]: 'Network error' }));
    } finally {
      setSwapLoading(prev => { const n = new Set(prev); n.delete(record.id); return n; });
    }
  };

  // Cross-DR swap fix
  const handleSwapFix = async (record: OltRecord, lookup: SwapLookupResult, fixBothDrs: boolean) => {
    const scenario = fixBothDrs ? lookup.scenario : 'fix_a_only';

    setSwapLoading(prev => new Set(prev).add(`fix-${record.id}`));
    setSwapErrors(prev => { const n = { ...prev }; delete n[record.id]; return n; });

    try {
      const res = await fetch('/api/system/olt-report/swap-fix', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          recordId: record.id,
          drANumber: lookup.drA.drNumber,
          drACorrectSerial: lookup.drA.oesSerial,
          drAWrongSerial: lookup.drA.oneMapSerial,
          drBNumber: lookup.drB.drNumber,
          drBCorrectSerial: lookup.drB.oesSerial,
          drBWrongSerial: lookup.drB.oneMapSerial,
          scenario,
          upsTransfer: lookup.upsTransfer,
        }),
      });
      const data = await res.json();
      const result = data.data || data;
      if (result.success) {
        let msg = scenario === 'clean_swap'
          ? `Swapped serials on both ${lookup.drA.drNumber} and ${lookup.drB.drNumber}`
          : `Fixed ${lookup.drA.drNumber}` + (scenario === 'fix_a_flag_b' ? ` and flagged ${lookup.drB.drNumber}` : '');
        if (result.upsTransfer?.success) msg += ` | UPS transferred to ${lookup.drB.drNumber}`;
        if (result.photoCopy?.success) msg += ` | ${result.photoCopy.count} photos copied to ${lookup.drB.drNumber}`;
        toast.success(msg);

        // Re-sync DR A photos
        fetch('/api/activate/fetch-photos', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ dropNumber: lookup.drA.drNumber, force: true }),
        }).then(r => r.json()).then(d => {
          const photoResult = d.data || d;
          if (photoResult.count > 0) toast.success(`${lookup.drA.drNumber}: ${photoResult.count} photos refreshed`);
        }).catch(() => { /* non-fatal */ });

        setSwapLookups(prev => { const n = { ...prev }; delete n[record.id]; return n; });
        fetchRecords('needs_investigation');
        fetchStats();
      } else {
        const errMsg = typeof result.error === 'string' ? result.error : result.error?.message || 'Swap fix failed';
        setSwapErrors(prev => ({ ...prev, [record.id]: errMsg }));
      }
    } catch {
      setSwapErrors(prev => ({ ...prev, [record.id]: 'Network error' }));
    } finally {
      setSwapLoading(prev => { const n = new Set(prev); n.delete(`fix-${record.id}`); return n; });
    }
  };

  const onResolved = () => {
    fetchRecords('needs_investigation', investigateSubFilter !== 'all' ? investigateSubFilter : undefined);
    fetchStats();
  };

  // Render the investigation context row for each record
  const renderContextRow = (record: OltRecord) => {
    if (!record.investigation_context) return null;
    try {
      const ctx: InvestigationContext = JSON.parse(record.investigation_context);
      const isExpanded = expandedContexts.has(record.id);
      return (
        <tr key={`${record.id}-ctx`} className="border-b border-[var(--ff-border-light)]">
          <td colSpan={7} className="py-1.5 px-4">
            <button
              onClick={() => toggleContext(record.id)}
              className="w-full bg-purple-500/5 border border-purple-500/20 rounded-lg text-xs text-left hover:bg-purple-500/10 transition-colors"
            >
              <div className="flex items-center gap-2 px-3 py-2">
                {isExpanded ? <ChevronDown className="w-3.5 h-3.5 text-purple-400 flex-shrink-0" /> : <ChevronRight className="w-3.5 h-3.5 text-purple-400 flex-shrink-0" />}
                <AlertTriangle className="w-3.5 h-3.5 text-purple-400 flex-shrink-0" />
                <span className="font-semibold text-purple-300">Cross-DR Conflict</span>
                <span className="text-[var(--ff-text-secondary)]">
                  — ONT <span className="font-mono text-red-400">{ctx.wrongSerial}</span> belongs to <span className="font-mono text-[var(--ff-accent)]">{ctx.belongsToDr}</span> ({ctx.belongsToTeam})
                </span>
              </div>
            </button>
            {isExpanded && (
              <div className="bg-purple-500/5 border border-t-0 border-purple-500/20 rounded-b-lg px-3 py-2.5 -mt-1 space-y-2">
                <p className="text-xs text-[var(--ff-text-secondary)] leading-relaxed">
                  The ONT serial <span className="font-mono text-red-400">{ctx.wrongSerial}</span> currently on 1Map
                  belongs to <a
                    href={`https://www.1map.co.za/apps/app?workspace=Fibertime%20Installations&selected=${ctx.belongsToDr}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="font-mono text-[var(--ff-accent)] hover:underline"
                    onClick={e => e.stopPropagation()}
                  >{ctx.belongsToDr}</a> ({ctx.belongsToTeam}).
                  {ctx.wrongUps && <> UPS: <span className="font-mono text-orange-400">{ctx.wrongUps}</span>.</>}
                </p>
                <div className="flex gap-4 text-xs text-[var(--ff-text-tertiary)]">
                  <span>1Map records: {ctx.totalPropRecords}</span>
                  <span className="text-green-400">Correct: {ctx.correctRecords}</span>
                  <span className="text-red-400">Wrong: {ctx.wrongRecords}</span>
                  {ctx.swappedRecords > 0 && <span className="text-orange-400">Swapped: {ctx.swappedRecords}</span>}
                </div>
                {/* Cross-DR Swap Panel */}
                <div className="mt-1 pt-2 border-t border-purple-500/10">
                  {!swapLookups[record.id] ? (
                    <div className="flex items-center gap-2">
                      <button
                        onClick={(e) => { e.stopPropagation(); handleSwapLookup(record); }}
                        disabled={swapLoading.has(record.id)}
                        className="flex items-center gap-1.5 px-3 py-1.5 bg-purple-600 text-white text-xs rounded hover:bg-purple-700 disabled:opacity-50"
                      >
                        {swapLoading.has(record.id) ? <Loader2 className="w-3 h-3 animate-spin" /> : <Search className="w-3 h-3" />}
                        Check Other DR
                      </button>
                      {swapErrors[record.id] && <span className="text-[10px] text-red-400">{swapErrors[record.id]}</span>}
                    </div>
                  ) : (() => {
                    const lookup = swapLookups[record.id]!;
                    const isFixing = swapLoading.has(`fix-${record.id}`);
                    const scenarioLabels: Record<string, { label: string; color: string }> = {
                      clean_swap: { label: 'Clean Swap', color: 'text-green-400' },
                      fix_a_only: { label: lookup.upsTransfer?.needed ? 'Fix A + Transfer UPS' : 'Fix DR A Only', color: lookup.upsTransfer?.needed ? 'text-amber-400' : 'text-blue-400' },
                      fix_a_flag_b: { label: 'Fix A + Flag B', color: 'text-amber-400' },
                      fix_a_b_missing: { label: 'Fix A (B Missing)', color: 'text-amber-400' },
                    };
                    const sc = scenarioLabels[lookup.scenario] || { label: lookup.scenario, color: 'text-gray-400' };
                    return (
                      <div className="space-y-2">
                        {/* Comparison card */}
                        <div className="grid grid-cols-2 gap-3 bg-[var(--ff-bg-primary)] rounded-lg p-3 border border-[var(--ff-border-light)]">
                          <div>
                            <div className="flex items-center gap-2 mb-1">
                              <span className="text-[10px] font-semibold text-[var(--ff-text-secondary)] uppercase">DR A ({lookup.drA.drNumber})</span>
                              <a href={`/activate/${lookup.drA.drNumber}`} target="_blank" rel="noopener noreferrer" className="text-[var(--ff-accent)] hover:text-[var(--ff-accent)]/80" title="DR Review" onClick={e => e.stopPropagation()}><Search className="w-3 h-3" /></a>
                              <a href={`https://www.1map.co.za/apps/app?workspace=Fibertime%20Installations&selected=${lookup.drA.drNumber}`} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:text-blue-300" title="View in 1Map" onClick={e => e.stopPropagation()}><ExternalLink className="w-3 h-3" /></a>
                            </div>
                            <p className="text-xs text-[var(--ff-text-secondary)]">OES: <span className="font-mono text-green-400">{lookup.drA.oesSerial}</span></p>
                            <p className="text-xs text-[var(--ff-text-secondary)]">1Map: <span className="font-mono text-red-400">{lookup.drA.oneMapSerial}</span> <XCircle className="w-3 h-3 inline text-red-400" /></p>
                            {lookup.drA.oneMapUps && (
                              <p className="text-xs text-[var(--ff-text-secondary)]">UPS: <span className={`font-mono ${lookup.upsTransfer?.needed ? 'text-amber-400' : 'text-gray-400'}`}>{lookup.drA.oneMapUps}</span>
                                {lookup.upsTransfer?.needed && <span className="text-[10px] text-amber-400 ml-1">(belongs to DR B)</span>}
                              </p>
                            )}
                          </div>
                          <div>
                            <div className="flex items-center gap-2 mb-1">
                              <span className="text-[10px] font-semibold text-[var(--ff-text-secondary)] uppercase">DR B ({lookup.drB.drNumber})</span>
                              <a href={`/activate/${lookup.drB.drNumber}`} target="_blank" rel="noopener noreferrer" className="text-[var(--ff-accent)] hover:text-[var(--ff-accent)]/80" title="DR Review" onClick={e => e.stopPropagation()}><Search className="w-3 h-3" /></a>
                              <a href={`https://www.1map.co.za/apps/app?workspace=Fibertime%20Installations&selected=${lookup.drB.drNumber}`} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:text-blue-300" title="View in 1Map" onClick={e => e.stopPropagation()}><ExternalLink className="w-3 h-3" /></a>
                            </div>
                            <p className="text-xs text-[var(--ff-text-secondary)]">OES: <span className="font-mono text-green-400">{lookup.drB.oesSerial || 'N/A'}</span></p>
                            <p className="text-xs text-[var(--ff-text-secondary)]">1Map: {lookup.drB.foundOn1Map ? (
                              <><span className={`font-mono ${lookup.drB.oneMapSerial?.toUpperCase() === lookup.drB.oesSerial?.toUpperCase() ? 'text-green-400' : 'text-red-400'}`}>{lookup.drB.oneMapSerial}</span>
                              {lookup.drB.oneMapSerial?.toUpperCase() === lookup.drB.oesSerial?.toUpperCase() ? <CheckCircle className="w-3 h-3 inline text-green-400 ml-0.5" /> : <XCircle className="w-3 h-3 inline text-red-400 ml-0.5" />}</>
                            ) : <span className="text-muted-foreground italic">Not on 1Map</span>}</p>
                            {lookup.drB.foundOn1Map && (
                              <p className="text-xs text-[var(--ff-text-secondary)]">UPS: {lookup.drB.oneMapUps ? (
                                <span className="font-mono text-gray-400">{lookup.drB.oneMapUps}</span>
                              ) : (
                                <span className={`italic ${lookup.upsTransfer?.needed ? 'text-amber-400' : 'text-muted-foreground'}`}>
                                  {lookup.upsTransfer?.needed ? 'Empty — will receive transfer' : 'Empty'}
                                </span>
                              )}</p>
                            )}
                          </div>
                        </div>
                        {/* UPS transfer notice */}
                        {lookup.upsTransfer?.needed && (
                          <div className="flex items-center gap-2 px-3 py-1.5 bg-amber-500/10 rounded border border-amber-500/20">
                            <ArrowLeftRight className="w-3 h-3 text-amber-400" />
                            <span className="text-[10px] text-amber-400">UPS {lookup.upsTransfer.serial} will transfer: {lookup.upsTransfer.from} → {lookup.upsTransfer.to}</span>
                          </div>
                        )}
                        {/* Scenario + actions */}
                        <div className="flex items-center justify-between">
                          <span className={`text-xs font-medium ${sc.color}`}>Scenario: {sc.label}</span>
                          <div className="flex items-center gap-2">
                            {swapErrors[record.id] && <span className="text-[10px] text-red-400">{swapErrors[record.id]}</span>}
                            {lookup.scenario === 'clean_swap' && (
                              <button
                                onClick={(e) => { e.stopPropagation(); handleSwapFix(record, lookup, true); }}
                                disabled={isFixing}
                                className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white text-xs rounded hover:bg-green-700 disabled:opacity-50"
                              >
                                {isFixing ? <Loader2 className="w-3 h-3 animate-spin" /> : <ArrowLeftRight className="w-3 h-3" />}
                                Swap Both DRs
                              </button>
                            )}
                            <button
                              onClick={(e) => { e.stopPropagation(); handleSwapFix(record, lookup, false); }}
                              disabled={isFixing}
                              className={`flex items-center gap-1 px-3 py-1.5 text-white text-xs rounded disabled:opacity-50 ${lookup.upsTransfer?.needed ? 'bg-amber-600 hover:bg-amber-700' : 'bg-blue-600 hover:bg-blue-700'}`}
                            >
                              {isFixing ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wrench className="w-3 h-3" />}
                              {lookup.upsTransfer?.needed ? 'Fix A + Transfer UPS' : 'Fix DR A Only'}
                            </button>
                          </div>
                        </div>
                        <p className="text-[10px] text-[var(--ff-text-tertiary)] leading-relaxed">{lookup.recommendation}</p>
                      </div>
                    );
                  })()}
                </div>
              </div>
            )}
          </td>
        </tr>
      );
    } catch {
      return null;
    }
  };

  return (
    <>
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
        {/* Search + Sub-filter bar + ticket actions */}
        {(records.length > 0 || debouncedSearch) && (
          <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--ff-border-light)] gap-3">
            <div className="flex items-center gap-2 flex-1 min-w-0">
              {/* Search input */}
              <div className="relative w-52 shrink-0">
                <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--ff-text-tertiary)]" />
                <input
                  type="text"
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  placeholder="Search DR, serial..."
                  className="w-full pl-8 pr-7 py-1.5 rounded bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)]
                             text-[var(--ff-text-primary)] text-xs placeholder:text-[var(--ff-text-tertiary)]
                             focus:outline-none focus:ring-1 focus:ring-[var(--ff-accent)]/50"
                />
                {searchText && (
                  <button
                    onClick={() => setSearchText('')}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
                  >
                    <XCircle className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>
              <span className="text-xs text-[var(--ff-text-secondary)] mr-1">Filter:</span>
              {([
                { key: 'all', label: 'All', count: stats.needs_investigation },
                { key: 'needs_investigation', label: 'Cross-DR Conflict', count: investigateSubCounts.cross_dr },
                { key: 'not_found', label: 'Not on 1Map', count: investigateSubCounts.not_found },
                { key: 'other', label: 'Other', count: investigateSubCounts.other },
              ] as const).map(({ key, label, count }) => (
                <button
                  key={key}
                  onClick={() => { setInvestigateSubFilter(key); setPage(1); }}
                  className={`px-3 py-1 text-xs rounded-full border transition-colors ${
                    investigateSubFilter === key
                      ? 'bg-[var(--ff-accent)] text-white border-[var(--ff-accent)]'
                      : 'bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] border-[var(--ff-border-light)] hover:border-[var(--ff-accent)]'
                  }`}
                >
                  {label} ({count})
                </button>
              ))}
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={handleSelectAllNotFound}
                disabled={selectingAll}
                className="px-3 py-1.5 bg-amber-600 text-white text-xs rounded hover:bg-amber-700
                           disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1.5"
              >
                {selectingAll ? (
                  <><Loader2 className="w-3 h-3 animate-spin" /> Loading...</>
                ) : (
                  <><Ticket className="w-3 h-3" /> Ticket All ({stats.needs_investigation})</>
                )}
              </button>
              {selectedIds.size > 0 && (
                <button
                  onClick={() => setShowTicketModal(true)}
                  className="px-3 py-1.5 bg-red-600 text-white text-xs rounded hover:bg-red-700
                             flex items-center gap-1.5"
                >
                  <Ticket className="w-3 h-3" />
                  Create {selectedIds.size} Ticket{selectedIds.size !== 1 ? 's' : ''}
                </button>
              )}
            </div>
          </div>
        )}

        <OltRecordTable
          records={records}
          mode="investigate"
          page={page}
          total={total}
          pageSize={pageSize}
          onPageChange={setPage}
          isLoading={isLoading}
          isStatusMismatch={isStatusMismatch}
          getInvestigationContext={getInvestigationContext}
          onResolve={(id) => setShowResolveModal(id)}
          onEscalate={(id) => setShowEscalateModal(id)}
          expandedContexts={expandedContexts}
          onToggleContext={toggleContext}
          renderContextRow={renderContextRow}
          selectedIds={selectedIds}
          onToggleSelect={toggleSelect}
          onToggleSelectAll={toggleSelectAll}
          isSelectable={isSelectable}
        />
      </div>

      {/* Modals */}
      {showResolveModal && (
        <OltResolveModal
          recordId={showResolveModal}
          onClose={() => setShowResolveModal(null)}
          onResolved={onResolved}
          setError={setError}
        />
      )}
      {showEscalateModal && (
        <OltEscalateModal
          recordId={showEscalateModal}
          onClose={() => setShowEscalateModal(null)}
          onEscalated={onResolved}
          setError={setError}
        />
      )}
      {showTicketModal && (
        <CreateOltTicketsModal
          selectedCount={selectedIds.size}
          onConfirm={handleCreateTickets}
          onClose={() => setShowTicketModal(false)}
          loading={creatingTickets}
        />
      )}
    </>
  );
}

/**
 * OltRecordTable — shared record table used by Fixable, Investigate, Escalations tabs
 */

'use client';

import React from 'react';
import {
  ExternalLink,
  Wrench,
  CheckCircle,
  Loader2,
  CheckSquare,
  Square,
  Info,
} from 'lucide-react';
import type { OltRecord, InvestigationContext, DisplacedInfo } from '../../../types';

type TabMode = 'pending' | 'investigate' | 'escalations';

interface OltRecordTableProps {
  records: OltRecord[];
  mode: TabMode;
  page: number;
  total: number;
  pageSize: number;
  onPageChange: (p: number | ((prev: number) => number)) => void;
  isLoading: boolean;

  // Fixable-specific
  selectedIds?: Set<string>;
  onToggleSelect?: (id: string) => void;
  onToggleSelectAll?: () => void;
  allSelected?: boolean;
  fixableCount?: number;

  // Fix actions
  fixing?: string | null;
  fixErrors?: Record<string, string>;
  onFix?: (record: OltRecord) => void;
  bulkFixing?: boolean;

  // Investigate-specific
  onResolve?: (recordId: string) => void;
  onEscalate?: (recordId: string) => void;

  // Helpers
  isStatusMismatch: (record: OltRecord) => boolean;
  getInvestigationContext: (record: OltRecord) => InvestigationContext | null;

  // Displaced info (pending tab only)
  displacedInfo?: Record<string, DisplacedInfo>;

  // Investigation context expansion
  expandedContexts?: Set<string>;
  onToggleContext?: (id: string) => void;

  // Render investigation context row
  renderContextRow?: (record: OltRecord) => React.ReactNode;

  // Investigate ticketing selection
  isSelectable?: (record: OltRecord) => boolean;
}

export function OltRecordTable({
  records,
  mode,
  page,
  total,
  pageSize,
  onPageChange,
  isLoading,
  selectedIds,
  onToggleSelect,
  onToggleSelectAll,
  allSelected,
  fixableCount: _fixableCount,
  fixing,
  fixErrors,
  onFix,
  bulkFixing,
  onResolve,
  onEscalate,
  isStatusMismatch,
  getInvestigationContext,
  displacedInfo,
  renderContextRow,
  isSelectable,
}: OltRecordTableProps) {
  const showCheckboxes = mode === 'pending' || (mode === 'investigate' && !!onToggleSelect);
  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-[var(--ff-accent)]" />
        <span className="ml-2 text-[var(--ff-text-secondary)]">Loading records...</span>
      </div>
    );
  }

  if (records.length === 0) {
    return (
      <div className="text-center py-12 text-[var(--ff-text-tertiary)]">
        No records found
      </div>
    );
  }

  return (
    <>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
              {showCheckboxes && (
                <th className="w-12 py-3 px-4">
                  <button
                    onClick={onToggleSelectAll}
                    className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)]"
                  >
                    {allSelected ? (
                      <CheckSquare className="w-5 h-5 text-[var(--ff-accent)]" />
                    ) : (
                      <Square className="w-5 h-5" />
                    )}
                  </button>
                </th>
              )}
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">DR Number</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Project</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">OLT Serial</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">1Map Serial</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Status</th>
              <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actions</th>
            </tr>
          </thead>
          <tbody>
            {records.map((record) => (
              <React.Fragment key={record.id}>
                <tr
                  className={`border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] ${
                    selectedIds?.has(record.id) ? 'bg-[var(--ff-accent)]/10' : ''
                  }`}
                >
                  {showCheckboxes && (
                    <td className="w-12 py-3 px-4">
                      {(mode === 'pending' ? record.olt_serial : isSelectable?.(record)) ? (
                        <button
                          onClick={() => onToggleSelect?.(record.id)}
                          className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)]"
                        >
                          {selectedIds?.has(record.id) ? (
                            <CheckSquare className="w-5 h-5 text-[var(--ff-accent)]" />
                          ) : (
                            <Square className="w-5 h-5" />
                          )}
                        </button>
                      ) : (
                        <span className="w-5 h-5 block" />
                      )}
                    </td>
                  )}
                  <td className="py-3 px-4 text-[var(--ff-text-primary)] font-mono">{record.drop_number}</td>
                  <td className="py-3 px-4 text-[var(--ff-text-secondary)] text-xs truncate max-w-[140px]">{record.project || '-'}</td>
                  <td className="py-3 px-4 text-green-400 font-mono">{record.olt_serial || '-'}</td>
                  <td className={`py-3 px-4 font-mono ${isStatusMismatch(record) ? 'text-green-400' : 'text-red-400'}`}>
                    {isStatusMismatch(record)
                      ? <span title="Serial matches OES">{record.olt_serial} <CheckCircle className="w-3 h-3 inline" /></span>
                      : (record.wrong_onemap_serial || record.onemap_serial || '-')}
                  </td>
                  <td className="py-3 px-4">
                    <span
                      className={`px-2 py-1 rounded text-xs ${
                        record.fix_status === 'fixed'
                          ? 'bg-green-500/20 text-green-400'
                          : record.fix_status === 'escalated'
                          ? 'bg-red-500/20 text-red-400'
                          : record.fix_status === 'needs_investigation'
                          ? 'bg-purple-500/20 text-purple-400'
                          : 'bg-amber-500/20 text-amber-400'
                      }`}
                    >
                      {record.fix_status || 'pending'}
                    </span>
                    {record.has_ups_swap && (
                      <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-orange-500/20 text-orange-400">UPS Swap</span>
                    )}
                    {isStatusMismatch(record) && (() => {
                      const ctx = getInvestigationContext(record);
                      return (
                        <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-blue-500/20 text-blue-400" title={ctx?.message}>
                          Status: {ctx?.currentStatus || 'wrong'}
                        </span>
                      );
                    })()}
                    {mode === 'pending' && record.wrong_onemap_serial && displacedInfo?.[record.wrong_onemap_serial] && (() => {
                      const info = displacedInfo![record.wrong_onemap_serial!]!;
                      if (info.activated && info.ownerDr && info.ownerDr !== record.drop_number) {
                        return (
                          <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-red-500/20 text-red-400 inline-flex items-center gap-0.5" title={`Displaced ONT belongs to ${info.ownerDr} (${info.ownerTeam || 'unknown team'})`}>
                            <Info className="w-3 h-3" /> {info.ownerDr}
                          </span>
                        );
                      }
                      if (!info.activated) {
                        const ws = record.wrong_onemap_serial!.toUpperCase();
                        const isOntSerial = /^ALCL|^HWTC/.test(ws);
                        const isUpsSerial = ws.startsWith('GU18');
                        const label = isOntSerial ? 'Unactivated ONT' : isUpsSerial ? 'UPS Serial' : 'Invalid Serial';
                        const tooltip = isOntSerial
                          ? 'Displaced ONT is not activated in OES — untracked physical ONT'
                          : isUpsSerial
                          ? 'Wrong serial is a UPS, not an ONT'
                          : 'Wrong serial does not match any known ONT or UPS pattern';
                        return (
                          <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-amber-500/20 text-amber-400 inline-flex items-center gap-0.5" title={tooltip}>
                            <Info className="w-3 h-3" /> {label}
                          </span>
                        );
                      }
                      return null;
                    })()}
                  </td>
                  <td className="py-3 px-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <a
                        href={`https://www.1map.co.za/apps/app?workspace=Fibertime%20Installations&selected=${record.drop_number}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)] transition-colors"
                        title="View in 1Map"
                      >
                        <ExternalLink className="w-4 h-4" />
                      </a>
                      {mode === 'pending' && record.olt_serial && (
                        <div className="flex flex-col items-end gap-1">
                          <button
                            onClick={() => onFix?.(record)}
                            disabled={fixing === record.id || bulkFixing}
                            className="flex items-center gap-1 px-3 py-1.5 bg-[var(--ff-accent)] text-white text-xs rounded hover:bg-[var(--ff-accent)]/80 disabled:opacity-50"
                          >
                            {fixing === record.id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <Wrench className="w-3 h-3" />
                            )}
                            {isStatusMismatch(record) ? 'Fix Status' : 'Fix'}
                          </button>
                          {fixErrors?.[record.id] && (
                            <span className="text-[10px] text-red-400 max-w-[160px] text-right leading-tight">
                              {fixErrors[record.id]}
                            </span>
                          )}
                        </div>
                      )}
                      {mode === 'investigate' && (
                        <>
                          <button
                            onClick={() => onResolve?.(record.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white text-xs rounded hover:bg-green-700"
                            title="Mark as resolved"
                          >
                            <CheckCircle className="w-3 h-3" />
                            Resolve
                          </button>
                          <button
                            onClick={() => onEscalate?.(record.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-red-600 text-white text-xs rounded hover:bg-red-700"
                            title="Escalate to admin"
                          >
                            <ExternalLink className="w-3 h-3" />
                            Escalate
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
                {renderContextRow?.(record)}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {total > pageSize && (
        <div className="flex items-center justify-between p-4 border-t border-[var(--ff-border-light)]">
          <span className="text-sm text-[var(--ff-text-secondary)]">
            Showing {(page - 1) * pageSize + 1} - {Math.min(page * pageSize, total)} of {total}
          </span>
          <div className="flex gap-2">
            <button
              onClick={() => onPageChange((p: number) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-3 py-1 text-sm bg-[var(--ff-bg-tertiary)] rounded disabled:opacity-50"
            >
              Previous
            </button>
            <button
              onClick={() => onPageChange((p: number) => p + 1)}
              disabled={page * pageSize >= total}
              className="px-3 py-1 text-sm bg-[var(--ff-bg-tertiary)] rounded disabled:opacity-50"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import {
  Search, RefreshCw, Loader2, AlertCircle, XCircle, Download, CheckCircle2, Wrench,
} from 'lucide-react';
import { formatDisplayDate } from '@/utils/dateFormat';
import toast from 'react-hot-toast';
import { CreatePPTicketsModal } from './CreatePPTicketsModal';

interface PPRecord {
  id: number;
  serial_number: string;
  project: string;
  date_registered: string | null;
  resolution_status: string;
  resolved_drop_number: string | null;
  resolved_source: string | null;
  resolved_at: string | null;
  maintenance_ticket_id: string | null;
  ticket_uid: string | null;
  oes_team: string | null;
  activation_date: string | null;
  wa_phone: string | null;
  wa_name: string | null;
  wa_team: string | null;
}

interface PPStats {
  total: number;
  activated: number;
  located: number;
  notFound: number;
  projects: number;
  ticketed: number;
  unticketed: number;
  lastImport: {
    date: string;
    filename: string;
    totalRows: number;
  } | null;
}

interface LookupStatus {
  status: 'running' | 'success' | 'failed';
  startedAt: string;
  completedAt: string | null;
  total: number;
  searched: number;
  resolved: number;
  not_found: number;
  errors: number;
  elapsed_seconds?: number;
}

const STATUS_COLORS: Record<string, { bg: string; text: string; label: string }> = {
  not_found: { bg: 'bg-amber-100 dark:bg-amber-900/30', text: 'text-amber-800 dark:text-amber-300', label: 'Not Found' },
  located_oes: { bg: 'bg-blue-100 dark:bg-blue-900/30', text: 'text-blue-800 dark:text-blue-300', label: 'Found (OES)' },
  located_unified: { bg: 'bg-indigo-100 dark:bg-indigo-900/30', text: 'text-indigo-800 dark:text-indigo-300', label: 'Found (Unified)' },
  located_onemap: { bg: 'bg-purple-100 dark:bg-purple-900/30', text: 'text-purple-800 dark:text-purple-300', label: 'Found (OneMap)' },
  located_1map: { bg: 'bg-teal-100 dark:bg-teal-900/30', text: 'text-teal-800 dark:text-teal-300', label: 'Found (1Map)' },
  located_local: { bg: 'bg-cyan-100 dark:bg-cyan-900/30', text: 'text-cyan-800 dark:text-cyan-300', label: 'Found (Local)' },
  activated: { bg: 'bg-green-100 dark:bg-green-900/30', text: 'text-green-800 dark:text-green-300', label: 'Activated' },
};

/** Check if a record is eligible for ticket selection (any unticketed, non-activated record) */
function isSelectable(r: PPRecord): boolean {
  return r.maintenance_ticket_id === null && r.resolution_status !== 'activated';
}

export function PPDataTab() {
  const [isResolving, setIsResolving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<PPStats | null>(null);
  const [records, setRecords] = useState<PPRecord[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [filterProject, setFilterProject] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterDateFrom, setFilterDateFrom] = useState('');
  const [filterDateTo, setFilterDateTo] = useState('');
  const [searchText, setSearchText] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [lookupStatus, setLookupStatus] = useState<LookupStatus | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Selection & ticket modal state
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [showTicketModal, setShowTicketModal] = useState(false);
  const [creatingTickets, setCreatingTickets] = useState(false);

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchText);
      setPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchText]);

  // Clear selection when filters or page change
  useEffect(() => { setSelectedIds([]); }, [page, filterProject, filterStatus, filterDateFrom, filterDateTo, debouncedSearch]);

  const fetchStats = useCallback(async () => {
    try {
      const res = await fetch('/api/activate/import-pp-data?action=stats');
      const data = await res.json();
      if (data.success) setStats(data.data);
    } catch {
      // Non-fatal
    }
  }, []);

  const fetchRecords = useCallback(async () => {
    try {
      const params = new URLSearchParams({
        action: 'list',
        page: String(page),
        limit: '50',
      });
      if (filterProject) params.set('project', filterProject);
      if (filterStatus) params.set('status', filterStatus);
      if (filterDateFrom) params.set('dateFrom', filterDateFrom);
      if (filterDateTo) params.set('dateTo', filterDateTo);
      if (debouncedSearch) params.set('search', debouncedSearch);

      const res = await fetch(`/api/activate/import-pp-data?${params}`);
      const data = await res.json();
      if (data.success) {
        setRecords(data.data);
        setTotalPages(data.pagination.totalPages);
      }
    } catch {
      // Non-fatal
    }
  }, [page, filterProject, filterStatus, filterDateFrom, filterDateTo, debouncedSearch]);

  const fetchLookupStatus = useCallback(async () => {
    try {
      const res = await fetch('/api/activate/import-pp-data?action=lookup-status');
      const data = await res.json();
      if (data.success && data.data) {
        setLookupStatus(data.data);
        if (data.data.status === 'running') {
          if (!pollRef.current) {
            pollRef.current = setInterval(() => {
              fetch('/api/activate/import-pp-data?action=lookup-status')
                .then(r => r.json())
                .then(d => {
                  if (d.success && d.data) {
                    setLookupStatus(d.data);
                    if (d.data.status !== 'running' && pollRef.current) {
                      clearInterval(pollRef.current);
                      pollRef.current = null;
                    }
                  }
                })
                .catch(() => { /* non-fatal */ });
            }, 3000);
          }
        } else {
          if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
          if (data.data.status === 'success') { fetchStats(); fetchRecords(); }
        }
      }
    } catch { /* non-fatal */ }
  }, [fetchStats, fetchRecords]);

  useEffect(() => { fetchStats(); }, [fetchStats]);
  useEffect(() => { if (stats && stats.total > 0) fetchRecords(); }, [stats, fetchRecords]);

  useEffect(() => {
    fetchLookupStatus();
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [fetchLookupStatus]);

  const handleResolveAll = async () => {
    setIsResolving(true);
    setError(null);
    try {
      const res = await fetch('/api/activate/pp-data-resolve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'resolve-all' }),
      });
      const result = await res.json();
      if (!res.ok) throw new Error(result.error || 'Resolve all failed');
      const d = result.data;
      const parts: string[] = [];
      if (d.steps.local_scan.resolved > 0) parts.push(`Local: ${d.steps.local_scan.resolved}`);
      if (d.steps.wa_cross_ref.resolved > 0) parts.push(`WA cross-ref: ${d.steps.wa_cross_ref.resolved}`);
      if (d.steps.wa_photo_vlm.resolved > 0) parts.push(`VLM photos: ${d.steps.wa_photo_vlm.resolved}`);
      const msg = d.total_resolved > 0
        ? `Resolved ${d.total_resolved} PPs (${parts.join(', ')})`
        : 'No new matches found across all sources';
      toast.success(d.onemap_started ? `${msg} — 1Map search running...` : msg);
      fetchStats();
      fetchRecords();
      // 1Map lookup runs in background — start polling for its progress
      if (d.onemap_started) {
        setTimeout(() => fetchLookupStatus(), 2000);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Resolve all failed');
    } finally {
      setIsResolving(false);
    }
  };

  const handleCreateTickets = async (params: { ticket_type: string; priority: string; notes: string; assigned_team_id?: string }) => {
    setCreatingTickets(true);
    try {
      const res = await fetch('/api/activate/pp-data-tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pp_data_ids: selectedIds, ...params }),
      });
      const result = await res.json();
      if (!res.ok) throw new Error(result.error?.message || result.error || 'Failed to create tickets');
      const { created, skipped } = result.data;
      toast.success(`Created ${created} ticket${created !== 1 ? 's' : ''}${skipped > 0 ? ` (${skipped} skipped)` : ''}`);
      setShowTicketModal(false);
      setSelectedIds([]);
      fetchStats();
      fetchRecords();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create tickets');
    } finally {
      setCreatingTickets(false);
    }
  };

  // Select all unticketed records across all pages
  const [selectingAllUnticketed, setSelectingAllUnticketed] = useState(false);
  const handleSelectAllUnticketed = async () => {
    setSelectingAllUnticketed(true);
    try {
      const params = new URLSearchParams({ action: 'list', status: 'unticketed', limit: '10000' });
      const res = await fetch(`/api/activate/import-pp-data?${params}`);
      const data = await res.json();
      if (data.success && Array.isArray(data.data)) {
        const ids = data.data.map((r: PPRecord) => r.id);
        setSelectedIds(ids);
        setFilterStatus('unticketed');
        setPage(1);
        toast.success(`Selected ${ids.length} unticketed records`);
      }
    } catch {
      toast.error('Failed to fetch unticketed records');
    } finally {
      setSelectingAllUnticketed(false);
    }
  };

  // Selection helpers
  const selectableOnPage = records.filter(isSelectable);
  const allSelectableChecked = selectableOnPage.length > 0 && selectableOnPage.every(r => selectedIds.includes(r.id));

  const toggleSelectAll = () => {
    if (allSelectableChecked) {
      setSelectedIds(prev => prev.filter(id => !selectableOnPage.some(r => r.id === id)));
    } else {
      setSelectedIds(prev => {
        const newIds = new Set(prev);
        selectableOnPage.forEach(r => newIds.add(r.id));
        return Array.from(newIds);
      });
    }
  };

  const toggleSelect = (id: number) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };


  return (
    <div className="space-y-6">
      {/* Info Banner */}
      <div className="bg-blue-900/20 border border-blue-800 rounded-lg p-4 flex items-start gap-3">
        <AlertCircle className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
        <p className="text-sm text-blue-300">
          PP Data is automatically imported from the <strong>PP DATA</strong> sheet when you import an OES Excel file via the OES tab.
          Use the actions below to locate imported serials against local data or 1Map. Serials are marked <strong>Activated</strong> when they appear in OES activations.
        </p>
      </div>

      {/* Summary Cards */}
      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-6 gap-4">
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-2xl font-bold text-[var(--ff-text-primary)]">{stats.total}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Total Imported</p>
          </div>
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-2xl font-bold text-green-500">{stats.activated}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Activated</p>
          </div>
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-2xl font-bold text-blue-500">{stats.located}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Located</p>
          </div>
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-2xl font-bold text-amber-500">{stats.notFound}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Not Found</p>
          </div>
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-2xl font-bold text-orange-500">{stats.ticketed}</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">Ticketed</p>
          </div>
          <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
            <p className="text-sm text-[var(--ff-text-secondary)]">Last Import</p>
            <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
              {stats.lastImport
                ? formatDisplayDate(stats.lastImport.date)
                : 'Never'}
            </p>
          </div>
        </div>
      )}

      {/* No Data State */}
      {stats && stats.total === 0 && (
        <div className="text-center py-12 text-[var(--ff-text-tertiary)]">
          <p className="text-lg mb-2">No PP Data imported yet</p>
          <p className="text-sm">Import an OES Excel file from the OES tab to automatically extract PP Data.</p>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div className="bg-red-900/20 border border-red-800 rounded-lg p-4 flex items-start gap-3">
          <XCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
          <div>
            <p className="font-medium text-red-300">Error</p>
            <p className="text-sm text-red-400">{error}</p>
          </div>
        </div>
      )}

      {/* 1Map Lookup Progress */}
      {lookupStatus && lookupStatus.status === 'running' && lookupStatus.total > 0 && (
        <div className="bg-purple-900/20 border border-purple-800 rounded-lg p-4 space-y-3">
          <div className="flex items-center gap-2">
            <Loader2 className="w-4 h-4 text-purple-400 animate-spin" />
            <span className="text-sm font-medium text-purple-300">
              1Map Serial Search in Progress
            </span>
            <span className="text-xs text-purple-400 ml-auto">
              {lookupStatus.elapsed_seconds ? `${lookupStatus.elapsed_seconds}s elapsed` : ''}
            </span>
          </div>
          <div className="w-full bg-purple-900/40 rounded-full h-2">
            <div
              className="bg-purple-500 h-2 rounded-full transition-all duration-500"
              style={{ width: `${Math.round((lookupStatus.searched / lookupStatus.total) * 100)}%` }}
            />
          </div>
          <div className="flex gap-6 text-xs text-purple-300">
            <span>Searched: <strong>{lookupStatus.searched}</strong> / {lookupStatus.total}</span>
            <span className="text-teal-400">Found: <strong>{lookupStatus.resolved}</strong></span>
            <span className="text-amber-400">Not Found: <strong>{lookupStatus.not_found}</strong></span>
            {lookupStatus.errors > 0 && (
              <span className="text-red-400">Errors: <strong>{lookupStatus.errors}</strong></span>
            )}
          </div>
        </div>
      )}

      {/* 1Map Lookup Complete Banner */}
      {lookupStatus && lookupStatus.status === 'success' && lookupStatus.total > 0 && (
        <div className="bg-green-900/20 border border-green-800 rounded-lg p-4 flex items-center gap-3">
          <CheckCircle2 className="w-5 h-5 text-green-400 flex-shrink-0" />
          <div className="text-sm text-green-300">
            <strong>1Map search complete.</strong>{' '}
            Searched {lookupStatus.total} serials — found <strong>{lookupStatus.resolved}</strong>,
            not found {lookupStatus.not_found}
            {lookupStatus.elapsed_seconds ? ` in ${lookupStatus.elapsed_seconds}s` : ''}.
          </div>
          <button
            onClick={() => setLookupStatus(null)}
            className="ml-auto text-green-500 hover:text-green-300"
          >
            <XCircle className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Action Buttons */}
      {stats && stats.total > 0 && (
        <div className="flex flex-wrap gap-3">
          <button
            onClick={handleResolveAll}
            disabled={isResolving || lookupStatus?.status === 'running'}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700
                       disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isResolving ? (
              <><Loader2 className="w-4 h-4 animate-spin" /> Resolving...</>
            ) : lookupStatus?.status === 'running' ? (
              <><Loader2 className="w-4 h-4 animate-spin" /> 1Map Searching...</>
            ) : (
              <><Search className="w-4 h-4" /> Resolve All</>
            )}
          </button>
          {stats && stats.unticketed > 0 && (
            <button
              onClick={handleSelectAllUnticketed}
              disabled={selectingAllUnticketed}
              className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700
                         disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {selectingAllUnticketed ? (
                <><Loader2 className="w-4 h-4 animate-spin" /> Loading...</>
              ) : (
                <><Wrench className="w-4 h-4" /> Ticket All Unticketed ({stats.unticketed})</>
              )}
            </button>
          )}
          <button
            onClick={() => { fetchStats(); fetchRecords(); }}
            className="px-4 py-2 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]
                       border border-[var(--ff-border-light)] rounded-lg flex items-center gap-2"
          >
            <RefreshCw className="w-4 h-4" /> Refresh
          </button>
        </div>
      )}

      {/* Bulk Actions Bar */}
      {selectedIds.length > 0 && (
        <div className="bg-blue-900/30 border border-blue-700 rounded-lg px-4 py-3 flex items-center justify-between">
          <span className="text-sm text-blue-300">
            <strong>{selectedIds.length}</strong> record{selectedIds.length !== 1 ? 's' : ''} selected
          </span>
          <div className="flex gap-3">
            <button
              onClick={() => setSelectedIds([])}
              className="px-3 py-1.5 text-sm rounded border border-blue-700 text-blue-300 hover:text-blue-100"
            >
              Clear
            </button>
            <button
              onClick={() => setShowTicketModal(true)}
              className="px-3 py-1.5 text-sm rounded bg-blue-600 text-white hover:bg-blue-700
                         flex items-center gap-1.5"
            >
              <Wrench className="w-3.5 h-3.5" /> Create NOC Tickets
            </button>
          </div>
        </div>
      )}

      {/* Filters & Records Table */}
      {stats && stats.total > 0 && (
        <div className="border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
          <div className="bg-[var(--ff-bg-primary)] px-4 py-3 border-b border-[var(--ff-border-light)] flex flex-wrap gap-3 items-center">
            <div className="relative">
              <Search className="w-4 h-4 absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--ff-text-tertiary)]" />
              <input
                type="text"
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                placeholder="Search serial, DR, ticket..."
                className="pl-8 pr-3 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]
                           text-[var(--ff-text-primary)] text-sm w-56 placeholder:text-[var(--ff-text-tertiary)]"
              />
              {searchText && (
                <button
                  onClick={() => setSearchText('')}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
                >
                  <XCircle className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
            <select
              value={filterProject}
              onChange={(e) => { setFilterProject(e.target.value); setPage(1); }}
              className="px-3 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]
                         text-[var(--ff-text-primary)] text-sm"
            >
              <option value="">All Projects</option>
              <option value="Lawley">Lawley</option>
              <option value="Mohadin">Mohadin</option>
              <option value="Mamelodi">Mamelodi</option>
            </select>
            <select
              value={filterStatus}
              onChange={(e) => { setFilterStatus(e.target.value); setPage(1); }}
              className="px-3 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]
                         text-[var(--ff-text-primary)] text-sm"
            >
              <option value="">All Statuses</option>
              <option value="unticketed">Unticketed</option>
              <option value="not_found">Not Found</option>
              <option value="located_oes">Found (OES)</option>
              <option value="located_unified">Found (Unified)</option>
              <option value="located_onemap">Found (OneMap)</option>
              <option value="located_1map">Found (1Map)</option>
              <option value="located_local">Found (Local)</option>
              <option value="activated">Activated</option>
            </select>
            <div className="flex items-center gap-1.5">
              <label className="text-xs text-[var(--ff-text-tertiary)]">From</label>
              <input
                type="date"
                value={filterDateFrom}
                onChange={(e) => { setFilterDateFrom(e.target.value); setPage(1); }}
                className="px-2 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]
                           text-[var(--ff-text-primary)] text-sm"
              />
              <label className="text-xs text-[var(--ff-text-tertiary)]">To</label>
              <input
                type="date"
                value={filterDateTo}
                onChange={(e) => { setFilterDateTo(e.target.value); setPage(1); }}
                className="px-2 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]
                           text-[var(--ff-text-primary)] text-sm"
              />
              {(filterDateFrom || filterDateTo) && (
                <button
                  onClick={() => { setFilterDateFrom(''); setFilterDateTo(''); setPage(1); }}
                  className="p-1 text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
                  title="Clear dates"
                >
                  <XCircle className="w-4 h-4" />
                </button>
              )}
            </div>
            <div className="ml-auto">
              <button
                onClick={() => {
                  const params = new URLSearchParams({ action: 'export' });
                  if (filterProject) params.set('project', filterProject);
                  if (filterStatus) params.set('status', filterStatus);
                  if (filterDateFrom) params.set('dateFrom', filterDateFrom);
                  if (filterDateTo) params.set('dateTo', filterDateTo);
                  window.open(`/api/activate/import-pp-data?${params}`, '_blank');
                }}
                className="px-3 py-1.5 text-sm rounded border border-[var(--ff-border-light)]
                           text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]
                           flex items-center gap-1.5"
              >
                <Download className="w-3.5 h-3.5" /> Export Excel
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--ff-bg-tertiary)]">
                <tr>
                  <th className="px-3 py-2 w-10">
                    {selectableOnPage.length > 0 && (
                      <input
                        type="checkbox"
                        checked={allSelectableChecked}
                        onChange={toggleSelectAll}
                        className="rounded border-gray-600"
                      />
                    )}
                  </th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Serial</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Project</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Registered</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Status</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">DR</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Install Team</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Activation</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">WA Technician</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Source</th>
                  <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)]">Ticket</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-light)]">
                {records.map((record) => {
                  const statusStyle = STATUS_COLORS[record.resolution_status] || { bg: 'bg-background/30', text: 'text-foreground', label: record.resolution_status };
                  const selectable = isSelectable(record);
                  return (
                    <tr key={record.id} className={`bg-[var(--ff-bg-secondary)] ${selectedIds.includes(record.id) ? 'bg-blue-900/10' : ''}`}>
                      <td className="px-3 py-2">
                        {selectable ? (
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(record.id)}
                            onChange={() => toggleSelect(record.id)}
                            className="rounded border-gray-600"
                          />
                        ) : null}
                      </td>
                      <td className="px-3 py-2 font-mono text-[var(--ff-text-primary)]">{record.serial_number}</td>
                      <td className="px-3 py-2 text-[var(--ff-text-secondary)]">{record.project}</td>
                      <td className="px-3 py-2 text-[var(--ff-text-secondary)]">
                        {record.date_registered ? formatDisplayDate(record.date_registered) : '-'}
                      </td>
                      <td className="px-3 py-2">
                        <span className={`px-2 py-0.5 rounded text-xs font-medium ${statusStyle.bg} ${statusStyle.text}`}>
                          {statusStyle.label}
                        </span>
                      </td>
                      <td className="px-3 py-2 font-mono text-[var(--ff-text-primary)]">
                        {record.resolved_drop_number || '-'}
                      </td>
                      <td className="px-3 py-2 text-[var(--ff-text-secondary)] text-xs">
                        {record.oes_team || '-'}
                      </td>
                      <td className="px-3 py-2 text-[var(--ff-text-secondary)] text-xs">
                        {record.activation_date ? formatDisplayDate(record.activation_date) : '-'}
                      </td>
                      <td className="px-3 py-2 text-xs">
                        {record.wa_name ? (
                          <div>
                            <span className="text-[var(--ff-text-primary)]">{record.wa_name}</span>
                            {record.wa_phone && (
                              <span className="block text-[var(--ff-text-tertiary)] font-mono text-[10px]">{record.wa_phone}</span>
                            )}
                          </div>
                        ) : '-'}
                      </td>
                      <td className="px-3 py-2 text-[var(--ff-text-secondary)]">
                        {record.resolved_source || '-'}
                      </td>
                      <td className="px-3 py-2">
                        {record.ticket_uid ? (
                          <a
                            href={`/noc/tickets/${record.maintenance_ticket_id}`}
                            className="text-blue-400 hover:text-blue-300 text-xs font-mono"
                          >
                            {record.ticket_uid}
                          </a>
                        ) : (
                          <span className="text-[var(--ff-text-tertiary)]">-</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
                {records.length === 0 && (
                  <tr>
                    <td colSpan={11} className="px-3 py-8 text-center text-[var(--ff-text-tertiary)]">
                      No records found
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex justify-between items-center px-4 py-3 border-t border-[var(--ff-border-light)]">
              <button
                onClick={() => setPage(p => Math.max(1, p - 1))}
                disabled={page === 1}
                className="px-3 py-1 text-sm rounded border border-[var(--ff-border-light)]
                           text-[var(--ff-text-secondary)] disabled:opacity-50"
              >
                Previous
              </button>
              <span className="text-sm text-[var(--ff-text-secondary)]">
                Page {page} of {totalPages}
              </span>
              <button
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                disabled={page === totalPages}
                className="px-3 py-1 text-sm rounded border border-[var(--ff-border-light)]
                           text-[var(--ff-text-secondary)] disabled:opacity-50"
              >
                Next
              </button>
            </div>
          )}
        </div>
      )}

      {/* Create Tickets Modal */}
      {showTicketModal && (
        <CreatePPTicketsModal
          selectedCount={selectedIds.length}
          onConfirm={handleCreateTickets}
          onClose={() => setShowTicketModal(false)}
          loading={creatingTickets}
        />
      )}
    </div>
  );
}

/**
 * OltRecordTable — shared record table used by Fixable, Investigate, Escalations tabs
 */

'use client';

import React from 'react';
import {
  ExternalLink,
  Wrench,
  CheckCircle,
  Loader2,
  CheckSquare,
  Square,
  Info,
} from 'lucide-react';
import type { OltRecord, InvestigationContext, DisplacedInfo } from '../../../types';

type TabMode = 'pending' | 'investigate' | 'escalations';

interface OltRecordTableProps {
  records: OltRecord[];
  mode: TabMode;
  page: number;
  total: number;
  pageSize: number;
  onPageChange: (p: number | ((prev: number) => number)) => void;
  isLoading: boolean;

  // Fixable-specific
  selectedIds?: Set<string>;
  onToggleSelect?: (id: string) => void;
  onToggleSelectAll?: () => void;
  allSelected?: boolean;
  fixableCount?: number;

  // Fix actions
  fixing?: string | null;
  fixErrors?: Record<string, string>;
  onFix?: (record: OltRecord) => void;
  bulkFixing?: boolean;

  // Investigate-specific
  onResolve?: (recordId: string) => void;
  onEscalate?: (recordId: string) => void;

  // Helpers
  isStatusMismatch: (record: OltRecord) => boolean;
  getInvestigationContext: (record: OltRecord) => InvestigationContext | null;

  // Displaced info (pending tab only)
  displacedInfo?: Record<string, DisplacedInfo>;

  // Investigation context expansion
  expandedContexts?: Set<string>;
  onToggleContext?: (id: string) => void;

  // Render investigation context row
  renderContextRow?: (record: OltRecord) => React.ReactNode;

  // Investigate ticketing selection
  isSelectable?: (record: OltRecord) => boolean;
}

export function OltRecordTable({
  records,
  mode,
  page,
  total,
  pageSize,
  onPageChange,
  isLoading,
  selectedIds,
  onToggleSelect,
  onToggleSelectAll,
  allSelected,
  fixableCount: _fixableCount,
  fixing,
  fixErrors,
  onFix,
  bulkFixing,
  onResolve,
  onEscalate,
  isStatusMismatch,
  getInvestigationContext,
  displacedInfo,
  renderContextRow,
  isSelectable,
}: OltRecordTableProps) {
  const showCheckboxes = mode === 'pending' || (mode === 'investigate' && !!onToggleSelect);
  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-[var(--ff-accent)]" />
        <span className="ml-2 text-[var(--ff-text-secondary)]">Loading records...</span>
      </div>
    );
  }

  if (records.length === 0) {
    return (
      <div className="text-center py-12 text-[var(--ff-text-tertiary)]">
        No records found
      </div>
    );
  }

  return (
    <>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
              {showCheckboxes && (
                <th className="w-12 py-3 px-4">
                  <button
                    onClick={onToggleSelectAll}
                    className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)]"
                  >
                    {allSelected ? (
                      <CheckSquare className="w-5 h-5 text-[var(--ff-accent)]" />
                    ) : (
                      <Square className="w-5 h-5" />
                    )}
                  </button>
                </th>
              )}
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">DR Number</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Project</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">OLT Serial</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">1Map Serial</th>
              <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Status</th>
              <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actions</th>
            </tr>
          </thead>
          <tbody>
            {records.map((record) => (
              <React.Fragment key={record.id}>
                <tr
                  className={`border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)] ${
                    selectedIds?.has(record.id) ? 'bg-[var(--ff-accent)]/10' : ''
                  }`}
                >
                  {showCheckboxes && (
                    <td className="w-12 py-3 px-4">
                      {(mode === 'pending' ? record.olt_serial : isSelectable?.(record)) ? (
                        <button
                          onClick={() => onToggleSelect?.(record.id)}
                          className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)]"
                        >
                          {selectedIds?.has(record.id) ? (
                            <CheckSquare className="w-5 h-5 text-[var(--ff-accent)]" />
                          ) : (
                            <Square className="w-5 h-5" />
                          )}
                        </button>
                      ) : (
                        <span className="w-5 h-5 block" />
                      )}
                    </td>
                  )}
                  <td className="py-3 px-4 text-[var(--ff-text-primary)] font-mono">{record.drop_number}</td>
                  <td className="py-3 px-4 text-[var(--ff-text-secondary)] text-xs truncate max-w-[140px]">{record.project || '-'}</td>
                  <td className="py-3 px-4 text-green-400 font-mono">{record.olt_serial || '-'}</td>
                  <td className={`py-3 px-4 font-mono ${isStatusMismatch(record) ? 'text-green-400' : 'text-red-400'}`}>
                    {isStatusMismatch(record)
                      ? <span title="Serial matches OES">{record.olt_serial} <CheckCircle className="w-3 h-3 inline" /></span>
                      : (record.wrong_onemap_serial || record.onemap_serial || '-')}
                  </td>
                  <td className="py-3 px-4">
                    <span
                      className={`px-2 py-1 rounded text-xs ${
                        record.fix_status === 'fixed'
                          ? 'bg-green-500/20 text-green-400'
                          : record.fix_status === 'escalated'
                          ? 'bg-red-500/20 text-red-400'
                          : record.fix_status === 'needs_investigation'
                          ? 'bg-purple-500/20 text-purple-400'
                          : 'bg-amber-500/20 text-amber-400'
                      }`}
                    >
                      {record.fix_status || 'pending'}
                    </span>
                    {record.has_ups_swap && (
                      <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-orange-500/20 text-orange-400">UPS Swap</span>
                    )}
                    {isStatusMismatch(record) && (() => {
                      const ctx = getInvestigationContext(record);
                      return (
                        <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-blue-500/20 text-blue-400" title={ctx?.message}>
                          Status: {ctx?.currentStatus || 'wrong'}
                        </span>
                      );
                    })()}
                    {mode === 'pending' && record.wrong_onemap_serial && displacedInfo?.[record.wrong_onemap_serial] && (() => {
                      const info = displacedInfo![record.wrong_onemap_serial!]!;
                      if (info.activated && info.ownerDr && info.ownerDr !== record.drop_number) {
                        return (
                          <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-red-500/20 text-red-400 inline-flex items-center gap-0.5" title={`Displaced ONT belongs to ${info.ownerDr} (${info.ownerTeam || 'unknown team'})`}>
                            <Info className="w-3 h-3" /> {info.ownerDr}
                          </span>
                        );
                      }
                      if (!info.activated) {
                        const ws = record.wrong_onemap_serial!.toUpperCase();
                        const isOntSerial = /^ALCL|^HWTC/.test(ws);
                        const isUpsSerial = ws.startsWith('GU18');
                        const label = isOntSerial ? 'Unactivated ONT' : isUpsSerial ? 'UPS Serial' : 'Invalid Serial';
                        const tooltip = isOntSerial
                          ? 'Displaced ONT is not activated in OES — untracked physical ONT'
                          : isUpsSerial
                          ? 'Wrong serial is a UPS, not an ONT'
                          : 'Wrong serial does not match any known ONT or UPS pattern';
                        return (
                          <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-amber-500/20 text-amber-400 inline-flex items-center gap-0.5" title={tooltip}>
                            <Info className="w-3 h-3" /> {label}
                          </span>
                        );
                      }
                      return null;
                    })()}
                  </td>
                  <td className="py-3 px-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <a
                        href={`https://www.1map.co.za/apps/app?workspace=Fibertime%20Installations&selected=${record.drop_number}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="p-1.5 text-[var(--ff-text-secondary)] hover:text-[var(--ff-accent)] transition-colors"
                        title="View in 1Map"
                      >
                        <ExternalLink className="w-4 h-4" />
                      </a>
                      {mode === 'pending' && record.olt_serial && (
                        <div className="flex flex-col items-end gap-1">
                          <button
                            onClick={() => onFix?.(record)}
                            disabled={fixing === record.id || bulkFixing}
                            className="flex items-center gap-1 px-3 py-1.5 bg-[var(--ff-accent)] text-white text-xs rounded hover:bg-[var(--ff-accent)]/80 disabled:opacity-50"
                          >
                            {fixing === record.id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <Wrench className="w-3 h-3" />
                            )}
                            {isStatusMismatch(record) ? 'Fix Status' : 'Fix'}
                          </button>
                          {fixErrors?.[record.id] && (
                            <span className="text-[10px] text-red-400 max-w-[160px] text-right leading-tight">
                              {fixErrors[record.id]}
                            </span>
                          )}
                        </div>
                      )}
                      {mode === 'investigate' && (
                        <>
                          <button
                            onClick={() => onResolve?.(record.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white text-xs rounded hover:bg-green-700"
                            title="Mark as resolved"
                          >
                            <CheckCircle className="w-3 h-3" />
                            Resolve
                          </button>
                          <button
                            onClick={() => onEscalate?.(record.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-red-600 text-white text-xs rounded hover:bg-red-700"
                            title="Escalate to admin"
                          >
                            <ExternalLink className="w-3 h-3" />
                            Escalate
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
                {renderContextRow?.(record)}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {total > pageSize && (
        <div className="flex items-center justify-between p-4 border-t border-[var(--ff-border-light)]">
          <span className="text-sm text-[var(--ff-text-secondary)]">
            Showing {(page - 1) * pageSize + 1} - {Math.min(page * pageSize, total)} of {total}
          </span>
          <div className="flex gap-2">
            <button
              onClick={() => onPageChange((p: number) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-3 py-1 text-sm bg-[var(--ff-bg-tertiary)] rounded disabled:opacity-50"
            >
              Previous
            </button>
            <button
              onClick={() => onPageChange((p: number) => p + 1)}
              disabled={page * pageSize >= total}
              className="px-3 py-1 text-sm bg-[var(--ff-bg-tertiary)] rounded disabled:opacity-50"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </>
  );
}

