/**
 * LocationList Component
 * Displays list of stock locations with filters and actions
 */

'use client';

import { useState } from 'react';
import { Loader2, MapPin, Plus, Search, Filter, Building2, Truck, User, Package } from 'lucide-react';
import { useLocations } from '../../hooks';
import type { StockLocation, LocationType } from '../../types';

interface LocationListProps {
  onSelectLocation?: (location: StockLocation) => void;
  selectedLocationId?: string;
  showCreateButton?: boolean;
  onCreateClick?: () => void;
}

const locationTypeIcons: Record<LocationType, React.ReactNode> = {
  warehouse: <Building2 className="h-4 w-4" />,
  site_store: <Package className="h-4 w-4" />,
  transit: <Truck className="h-4 w-4" />,
  technician: <User className="h-4 w-4" />,
  customer: <MapPin className="h-4 w-4" />,
  scrap: <Package className="h-4 w-4" />,
  adjustment: <Package className="h-4 w-4" />,
};

const locationTypeLabels: Record<LocationType, string> = {
  warehouse: 'Warehouse',
  site_store: 'Site Store',
  transit: 'In Transit',
  technician: 'Technician Van',
  customer: 'Customer',
  scrap: 'Scrap',
  adjustment: 'Adjustment',
};

const locationTypeColors: Record<LocationType, string> = {
  warehouse: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  site_store: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  transit: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',
  technician: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
  customer: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
  scrap: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300',
  adjustment: 'bg-secondary text-gray-800 dark:bg-gray-700 dark:text-gray-300',
};

export function LocationList({
  onSelectLocation,
  selectedLocationId,
  showCreateButton = true,
  onCreateClick,
}: LocationListProps) {
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<LocationType | ''>('');
  const [showFilters, setShowFilters] = useState(false);

  const { locations, loading, error, fetchLocations } = useLocations({
    filters: {
      search: search || undefined,
      locationType: typeFilter || undefined,
      isActive: true,
    },
    autoFetch: true,
  });

  const handleSearch = (value: string) => {
    setSearch(value);
    fetchLocations({
      search: value || undefined,
      locationType: typeFilter || undefined,
      isActive: true,
    });
  };

  const handleTypeFilter = (type: LocationType | '') => {
    setTypeFilter(type);
    fetchLocations({
      search: search || undefined,
      locationType: type || undefined,
      isActive: true,
    });
  };

  if (error) {
    return (
      <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
        <p className="font-medium">Error loading locations</p>
        <p className="text-sm">{error}</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with Search and Filters */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            placeholder="Search locations..."
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            className="w-full rounded-lg border border-border bg-card py-2 pl-10 pr-4 text-sm text-foreground placeholder-gray-500 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-white dark:placeholder-gray-400"
          />
        </div>

        <div className="flex gap-2">
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium ${
              showFilters
                ? 'border-blue-500 bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300'
                : 'border-border bg-card text-muted-foreground hover:bg-gray-50 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600'
            }`}
          >
            <Filter className="h-4 w-4" />
            Filters
          </button>

          {showCreateButton && (
            <button
              onClick={onCreateClick}
              className="flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              <Plus className="h-4 w-4" />
              Add Location
            </button>
          )}
        </div>
      </div>

      {/* Filters Panel */}
      {showFilters && (
        <div className="rounded-lg border border-border bg-background p-4 dark:border-gray-700 dark:bg-gray-800">
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => handleTypeFilter('')}
              className={`rounded-full px-3 py-1 text-sm font-medium ${
                typeFilter === ''
                  ? 'bg-blue-600 text-white'
                  : 'bg-card text-muted-foreground hover:bg-secondary dark:text-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              All Types
            </button>
            {Object.entries(locationTypeLabels).map(([type, label]) => (
              <button
                key={type}
                onClick={() => handleTypeFilter(type as LocationType)}
                className={`rounded-full px-3 py-1 text-sm font-medium ${
                  typeFilter === type
                    ? 'bg-blue-600 text-white'
                    : 'bg-card text-muted-foreground hover:bg-secondary dark:text-gray-200 dark:hover:bg-gray-600'
                }`}
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Loading State */}
      {loading && (
        <div className="flex h-32 items-center justify-center">
          <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
        </div>
      )}

      {/* Location List */}
      {!loading && locations.length === 0 && (
        <div className="rounded-lg border border-border bg-background p-8 text-center dark:border-gray-700 dark:bg-gray-800">
          <MapPin className="mx-auto h-12 w-12 text-gray-400" />
          <p className="mt-2 text-muted-foreground">No locations found</p>
          <p className="text-sm text-muted-foreground">
            {search ? 'Try a different search term' : 'Create your first location to get started'}
          </p>
        </div>
      )}

      {!loading && locations.length > 0 && (
        <div className="divide-y divide-gray-200 rounded-lg border border-border bg-white dark:divide-gray-700 dark:border-gray-700 dark:bg-gray-800">
          {locations.map((location) => (
            <button
              key={location.id}
              onClick={() => onSelectLocation?.(location)}
              className={`flex w-full items-center justify-between p-4 text-left transition-colors hover:bg-accent ${
                selectedLocationId === location.id ? 'bg-blue-50 dark:bg-blue-900/20' : ''
              }`}
            >
              <div className="flex items-center gap-4">
                <div className={`rounded-lg p-2 ${locationTypeColors[location.locationType]}`}>
                  {locationTypeIcons[location.locationType]}
                </div>
                <div>
                  <p className="font-medium text-foreground">{location.name}</p>
                  <p className="text-sm text-muted-foreground">
                    {location.code}
                    {location.assignedToName && ` • ${location.assignedToName}`}
                  </p>
                </div>
              </div>
              <span
                className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${
                  locationTypeColors[location.locationType]
                }`}
              >
                {locationTypeLabels[location.locationType]}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Location Service
 * CRUD operations for stock locations
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { query } from './db';
import type {
  StockLocation,
  CreateLocationInput,
  UpdateLocationInput,
  LocationFilters,
  LocationType,
} from '../types';

const sql = neon(process.env.DATABASE_URL!);

/**
 * Get all locations with optional filters
 */
export async function getLocations(
  filters?: LocationFilters
): Promise<StockLocation[]> {
  try {
    let queryText = `
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE 1=1
    `;

    const params: unknown[] = [];
    let paramIndex = 1;

    if (filters?.locationType) {
      queryText += ` AND location_type = $${paramIndex++}`;
      params.push(filters.locationType);
    }

    if (filters?.projectId) {
      queryText += ` AND project_id = $${paramIndex++}`;
      params.push(filters.projectId);
    }

    if (filters?.assignedToId) {
      queryText += ` AND assigned_to_id = $${paramIndex++}`;
      params.push(filters.assignedToId);
    }

    if (filters?.isActive !== undefined) {
      queryText += ` AND is_active = $${paramIndex++}`;
      params.push(filters.isActive);
    }

    if (filters?.parentId) {
      queryText += ` AND parent_id = $${paramIndex++}`;
      params.push(filters.parentId);
    }

    if (filters?.search) {
      queryText += ` AND (name ILIKE $${paramIndex} OR code ILIKE $${paramIndex})`;
      params.push(`%${filters.search}%`);
      paramIndex++;
    }

    queryText += ' ORDER BY name ASC';

    const results = await query<StockLocation>(queryText, params);
    return results;
  } catch (error) {
    log.error('Failed to get locations', error, 'locationService');
    throw error;
  }
}

/**
 * Get a single location by ID
 */
export async function getLocationById(id: string): Promise<StockLocation | null> {
  try {
    const results = await sql`
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE id = ${id}
    `;

    return (results[0] as StockLocation) || null;
  } catch (error) {
    log.error('Failed to get location by ID', error, 'locationService');
    throw error;
  }
}

/**
 * Get a location by code
 */
export async function getLocationByCode(code: string): Promise<StockLocation | null> {
  try {
    const results = await sql`
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE code = ${code}
    `;

    return (results[0] as StockLocation) || null;
  } catch (error) {
    log.error('Failed to get location by code', error, 'locationService');
    throw error;
  }
}

/**
 * Create a new location
 */
export async function createLocation(
  input: CreateLocationInput,
  createdBy?: string
): Promise<StockLocation> {
  try {
    const results = await sql`
      INSERT INTO stock_locations (
        parent_id,
        code,
        name,
        location_type,
        address,
        coordinates,
        assigned_to_id,
        assigned_to_name,
        assigned_to_phone,
        project_id,
        is_virtual,
        created_by
      ) VALUES (
        ${input.parentId || null},
        ${input.code},
        ${input.name},
        ${input.locationType},
        ${input.address || null},
        ${input.coordinates ? JSON.stringify(input.coordinates) : null},
        ${input.assignedToId || null},
        ${input.assignedToName || null},
        ${input.assignedToPhone || null},
        ${input.projectId || null},
        ${input.isVirtual || false},
        ${createdBy || null}
      )
      RETURNING
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
    `;

    log.info(`Created location: ${input.code}`, undefined, 'locationService');
    return results[0] as StockLocation;
  } catch (error) {
    log.error('Failed to create location', error, 'locationService');
    throw error;
  }
}

/**
 * Update a location
 */
export async function updateLocation(
  id: string,
  input: UpdateLocationInput
): Promise<StockLocation> {
  try {
    const setClauses: string[] = [];
    const params: unknown[] = [];
    let paramIndex = 1;

    if (input.name !== undefined) {
      setClauses.push(`name = $${paramIndex++}`);
      params.push(input.name);
    }

    if (input.address !== undefined) {
      setClauses.push(`address = $${paramIndex++}`);
      params.push(input.address);
    }

    if (input.coordinates !== undefined) {
      setClauses.push(`coordinates = $${paramIndex++}`);
      params.push(JSON.stringify(input.coordinates));
    }

    if (input.assignedToId !== undefined) {
      setClauses.push(`assigned_to_id = $${paramIndex++}`);
      params.push(input.assignedToId);
    }

    if (input.assignedToName !== undefined) {
      setClauses.push(`assigned_to_name = $${paramIndex++}`);
      params.push(input.assignedToName);
    }

    if (input.assignedToPhone !== undefined) {
      setClauses.push(`assigned_to_phone = $${paramIndex++}`);
      params.push(input.assignedToPhone);
    }

    if (input.projectId !== undefined) {
      setClauses.push(`project_id = $${paramIndex++}`);
      params.push(input.projectId);
    }

    if (input.isActive !== undefined) {
      setClauses.push(`is_active = $${paramIndex++}`);
      params.push(input.isActive);
    }

    setClauses.push(`updated_at = NOW()`);
    params.push(id);

    const queryText = `
      UPDATE stock_locations
      SET ${setClauses.join(', ')}
      WHERE id = $${paramIndex}
      RETURNING
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
    `;

    const results = await query<StockLocation>(queryText, params);
    if (!results[0]) {
      throw new Error(`Location ${id} not found`);
    }
    log.info(`Updated location: ${id}`, undefined, 'locationService');
    return results[0];
  } catch (error) {
    log.error('Failed to update location', error, 'locationService');
    throw error;
  }
}

/**
 * Delete a location (soft delete by setting is_active = false)
 */
export async function deleteLocation(id: string): Promise<void> {
  try {
    await sql`
      UPDATE stock_locations
      SET is_active = false, updated_at = NOW()
      WHERE id = ${id}
    `;
    log.info(`Deleted location: ${id}`, undefined, 'locationService');
  } catch (error) {
    log.error('Failed to delete location', error, 'locationService');
    throw error;
  }
}

/**
 * Get all technician van stock locations
 */
export async function getTechnicianLocations(): Promise<StockLocation[]> {
  try {
    const results = await sql`
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE location_type = 'technician'
        AND is_active = true
      ORDER BY assigned_to_name ASC
    `;

    return results as StockLocation[];
  } catch (error) {
    log.error('Failed to get technician locations', error, 'locationService');
    throw error;
  }
}

/**
 * Get or create a technician's van stock location
 */
export async function getOrCreateTechnicianLocation(
  technicianId: string,
  technicianName: string,
  technicianPhone?: string
): Promise<StockLocation> {
  try {
    // Check if location exists
    const existing = await sql`
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE location_type = 'technician'
        AND assigned_to_id = ${technicianId}
      LIMIT 1
    `;

    if (existing.length > 0) {
      return existing[0] as StockLocation;
    }

    // Create new technician location
    const code = `TECH-${technicianId.slice(0, 8).toUpperCase()}`;
    return await createLocation({
      code,
      name: `${technicianName}'s Van Stock`,
      locationType: 'technician',
      assignedToId: technicianId,
      assignedToName: technicianName,
      assignedToPhone: technicianPhone,
      isVirtual: true,
    });
  } catch (error) {
    log.error('Failed to get or create technician location', error, 'locationService');
    throw error;
  }
}

/**
 * Get location hierarchy (tree structure)
 */
export async function getLocationHierarchy(
  rootType?: LocationType
): Promise<StockLocation[]> {
  try {
    let queryText = `
      SELECT
        id,
        parent_id as "parentId",
        code,
        name,
        location_type as "locationType",
        address,
        coordinates,
        assigned_to_id as "assignedToId",
        assigned_to_name as "assignedToName",
        assigned_to_phone as "assignedToPhone",
        project_id as "projectId",
        is_active as "isActive",
        is_virtual as "isVirtual",
        created_at as "createdAt",
        updated_at as "updatedAt",
        created_by as "createdBy"
      FROM stock_locations
      WHERE is_active = true
    `;

    const params: unknown[] = [];

    if (rootType) {
      queryText += ` AND location_type = $1`;
      params.push(rootType);
    }

    queryText += ' ORDER BY location_type, name';

    const locations = await query<StockLocation>(queryText, params);

    // Build tree structure
    const locationMap = new Map<string, StockLocation>();
    const rootLocations: StockLocation[] = [];

    // First pass: create map
    for (const loc of locations) {
      loc.children = [];
      locationMap.set(loc.id, loc);
    }

    // Second pass: build tree
    for (const loc of locations) {
      if (loc.parentId && locationMap.has(loc.parentId)) {
        const parent = locationMap.get(loc.parentId)!;
        parent.children = parent.children || [];
        parent.children.push(loc);
      } else {
        rootLocations.push(loc);
      }
    }

    return rootLocations;
  } catch (error) {
    log.error('Failed to get location hierarchy', error, 'locationService');
    throw error;
  }
}

/**
 * Get stock count for a location
 */
export async function getLocationStockCount(locationId: string): Promise<number> {
  try {
    const results = await sql`
      SELECT COALESCE(SUM(quantity), 0) as count
      FROM stock_quants
      WHERE location_id = ${locationId}
    `;

    return Number(results[0]?.count || 0);
  } catch (error) {
    log.error('Failed to get location stock count', error, 'locationService');
    throw error;
  }
}

/**
 * useLocations Hook
 * CRUD operations for stock locations
 */

import { useState, useCallback, useEffect, useRef } from 'react';
import { log } from '@/lib/logger';
import type {
  StockLocation,
  CreateLocationInput,
  UpdateLocationInput,
  LocationFilters,
} from '../types';

interface UseLocationsOptions {
  filters?: LocationFilters;
  autoFetch?: boolean;
}

interface UseLocationsReturn {
  locations: StockLocation[];
  loading: boolean;
  error: string | null;
  fetchLocations: (filters?: LocationFilters) => Promise<void>;
  getLocation: (id: string) => Promise<StockLocation | null>;
  createLocation: (input: CreateLocationInput) => Promise<StockLocation>;
  updateLocation: (id: string, input: UpdateLocationInput) => Promise<StockLocation>;
  deleteLocation: (id: string) => Promise<void>;
  refresh: () => Promise<void>;
}

export function useLocations(options: UseLocationsOptions = {}): UseLocationsReturn {
  const { filters: initialFilters, autoFetch = true } = options;

  const [locations, setLocations] = useState<StockLocation[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentFilters, setCurrentFilters] = useState<LocationFilters | undefined>(initialFilters);

  const fetchLocations = useCallback(async (filters?: LocationFilters) => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams();
      const activeFilters = filters || currentFilters;

      if (activeFilters) {
        if (activeFilters.locationType) {
          params.append('locationType', activeFilters.locationType);
        }
        if (activeFilters.projectId) {
          params.append('projectId', activeFilters.projectId);
        }
        if (activeFilters.assignedToId) {
          params.append('assignedToId', activeFilters.assignedToId);
        }
        if (activeFilters.isActive !== undefined) {
          params.append('isActive', String(activeFilters.isActive));
        }
        if (activeFilters.search) {
          params.append('search', activeFilters.search);
        }
      }

      const queryString = params.toString();
      const url = `/api/procurement/field-stock/locations${queryString ? `?${queryString}` : ''}`;

      const response = await fetch(url);
      const result = await response.json();

      if (!result.success) {
        throw new Error(result.error?.message || 'Failed to fetch locations');
      }

      setLocations(result.data);
      setCurrentFilters(filters || currentFilters);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch locations';
      setError(message);
      log.error('Failed to fetch locations', err, 'useLocations');
    } finally {
      setLoading(false);
    }
  }, [currentFilters]);

  const getLocation = useCallback(async (id: string): Promise<StockLocation | null> => {
    try {
      const response = await fetch(`/api/procurement/field-stock/locations/${id}`);
      const result = await response.json();

      if (!result.success) {
        throw new Error(result.error?.message || 'Failed to fetch location');
      }

      return result.data;
    } catch (err) {
      log.error('Failed to fetch location', err, 'useLocations');
      throw err;
    }
  }, []);

  const createLocation = useCallback(async (input: CreateLocationInput): Promise<StockLocation> => {
    try {
      const response = await fetch('/api/procurement/field-stock/locations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });

      const result = await response.json();

      if (!result.success) {
        throw new Error(result.error?.message || 'Failed to create location');
      }

      // Refresh the list
      await fetchLocations();

      return result.data;
    } catch (err) {
      log.error('Failed to create location', err, 'useLocations');
      throw err;
    }
  }, [fetchLocations]);

  const updateLocation = useCallback(async (
    id: string,
    input: UpdateLocationInput
  ): Promise<StockLocation> => {
    try {
      const response = await fetch(`/api/procurement/field-stock/locations/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });

      const result = await response.json();

      if (!result.success) {
        throw new Error(result.error?.message || 'Failed to update location');
      }

      // Refresh the list
      await fetchLocations();

      return result.data;
    } catch (err) {
      log.error('Failed to update location', err, 'useLocations');
      throw err;
    }
  }, [fetchLocations]);

  const deleteLocation = useCallback(async (id: string): Promise<void> => {
    try {
      const response = await fetch(`/api/procurement/field-stock/locations/${id}`, {
        method: 'DELETE',
      });

      const result = await response.json();

      if (!result.success) {
        throw new Error(result.error?.message || 'Failed to delete location');
      }

      // Refresh the list
      await fetchLocations();
    } catch (err) {
      log.error('Failed to delete location', err, 'useLocations');
      throw err;
    }
  }, [fetchLocations]);

  const refresh = useCallback(async () => {
    await fetchLocations(currentFilters);
  }, [fetchLocations, currentFilters]);

  // Track if initial fetch has been done
  const hasFetched = useRef(false);

  // Auto-fetch on mount if enabled (only once)
  useEffect(() => {
    if (autoFetch && !hasFetched.current) {
      hasFetched.current = true;
      fetchLocations(initialFilters);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoFetch]);

  return {
    locations,
    loading,
    error,
    fetchLocations,
    getLocation,
    createLocation,
    updateLocation,
    deleteLocation,
    refresh,
  };
}

