/**
 * Field Stock Locations API
 * GET /api/procurement/field-stock/locations - List all locations
 * POST /api/procurement/field-stock/locations - Create a new location
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import {
  getLocations,
  createLocation,
  getTechnicianLocations,
} from '@/modules/procurement/field-stock/services/locationService';
import type { CreateLocationInput, LocationFilters, LocationType } from '@/modules/procurement/field-stock/types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    if (req.method === 'GET') {
      // Parse query parameters for filters
      const filters: LocationFilters = {};

      if (req.query.locationType) {
        filters.locationType = req.query.locationType as LocationType;
      }
      if (req.query.projectId) {
        filters.projectId = req.query.projectId as string;
      }
      if (req.query.isActive !== undefined) {
        filters.isActive = req.query.isActive === 'true';
      }
      if (req.query.parentId) {
        filters.parentId = req.query.parentId as string;
      }
      if (req.query.search) {
        filters.search = req.query.search as string;
      }

      // Special case: get technician locations only
      if (req.query.techniciansOnly === 'true') {
        const locations = await getTechnicianLocations();
        return apiResponse.success(res, locations);
      }

      const locations = await getLocations(filters);
      return apiResponse.success(res, locations);
    }

    if (req.method === 'POST') {
      const input = req.body as CreateLocationInput;

      // Validate required fields
      if (!input.code || !input.name || !input.locationType) {
        return apiResponse.validationError(res, { error: 'Missing required fields: code, name, locationType' });
      }

      const location = await createLocation(input);
      return apiResponse.created(res, location);
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
  } catch (error) {
    log.error('Field stock locations API error', error, 'field-stock/locations');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Field Stock Location by ID API
 * GET /api/procurement/field-stock/locations/[locationId] - Get location details
 * PUT /api/procurement/field-stock/locations/[locationId] - Update location
 * DELETE /api/procurement/field-stock/locations/[locationId] - Delete location
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import {
  getLocationById,
  updateLocation,
  deleteLocation,
} from '@/modules/procurement/field-stock/services/locationService';
import type { UpdateLocationInput } from '@/modules/procurement/field-stock/types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { locationId } = req.query;

  if (!locationId || typeof locationId !== 'string') {
    return apiResponse.validationError(res, { locationId: 'Location ID is required' });
  }

  try {
    if (req.method === 'GET') {
      const location = await getLocationById(locationId);
      if (!location) {
        return apiResponse.notFound(res, 'Location', locationId);
      }
      return apiResponse.success(res, location);
    }

    if (req.method === 'PUT') {
      const input = req.body as UpdateLocationInput;
      const location = await updateLocation(locationId, input);
      return apiResponse.success(res, location);
    }

    if (req.method === 'DELETE') {
      await deleteLocation(locationId);
      return apiResponse.success(res, { message: 'Location deleted successfully' });
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT', 'DELETE']);
  } catch (error) {
    log.error('Field stock location API error', error, 'field-stock/locations/[id]');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Field Stock Control Types
 * PRD-027: Comprehensive type definitions for field stock management
 */

// ============================================================================
// ENUMS
// ============================================================================

export type LocationType =
  | 'warehouse'
  | 'site_store'
  | 'transit'
  | 'technician'
  | 'customer'
  | 'scrap'
  | 'adjustment';

export type ItemCategory =
  | 'ont'
  | 'router'
  | 'mini_ups'
  | 'drop_cable'
  | 'fiber_cable'
  | 'connector'
  | 'consumable'
  | 'tool'
  | 'ppe';

export type TrackingType = 'serial' | 'lot' | 'quantity' | 'drum';

export type SerialStatus =
  | 'available'
  | 'reserved'
  | 'issued'
  | 'installed'
  | 'faulty'
  | 'returned'
  | 'scrapped';

export type SerialCondition =
  | 'new'
  | 'good'
  | 'fair'
  | 'poor'
  | 'damaged'
  | 'non_functional';

export type PickingType = 'issue' | 'receipt' | 'return' | 'transfer' | 'scrap';

export type PickingStatus =
  | 'draft'
  | 'confirmed'
  | 'processing'
  | 'done'
  | 'cancelled';

export type JobType = 'drop' | 'home_install' | 'maintenance';

export type ReturnStatus =
  | 'pending'
  | 'received'
  | 'inspected'
  | 'accepted'
  | 'rejected'
  | 'restocked';

export type ReturnReason =
  | 'unused'
  | 'job_cancelled'
  | 'wrong_item'
  | 'excess'
  | 'faulty'
  | 'customer_refused';

export type Disposition = 'restock' | 'repair' | 'scrap' | 'supplier_return';

export type MovementType =
  | 'receipt'
  | 'issue'
  | 'transfer'
  | 'consumption'
  | 'return'
  | 'adjustment'
  | 'scrap';

export type AccountabilityEventType =
  | 'issue'
  | 'consumption'
  | 'return'
  | 'reconciliation'
  | 'block'
  | 'unblock'
  | 'recovery_added'
  | 'recovery_paid'
  | 'adjustment';

// ============================================================================
// CORE ENTITIES
// ============================================================================

export interface StockLocation {
  id: string;
  parentId?: string;
  code: string;
  name: string;
  locationType: LocationType;
  address?: string;
  coordinates?: { lat: number; lng: number };
  assignedToId?: string;
  assignedToName?: string;
  assignedToPhone?: string;
  projectId?: string;
  isActive: boolean;
  isVirtual: boolean;
  createdAt: Date;
  updatedAt: Date;
  createdBy?: string;
  // Computed/joined
  children?: StockLocation[];
  stockCount?: number;
}

export interface StockItem {
  id: string;
  itemCode: string;
  name: string;
  description?: string;
  category: ItemCategory;
  trackingType: TrackingType;
  uom: string;
  standardCost?: number;
  currency: string;
  minStockLevel: number;
  maxStockLevel?: number;
  reorderQuantity?: number;
  isActive: boolean;
  isReturnable: boolean;
  createdAt: Date;
  updatedAt: Date;
  // Computed
  totalStock?: number;
  availableStock?: number;
}

export interface StockSerial {
  id: string;
  stockItemId: string;
  serialNumber: string;
  macAddress?: string;
  imei?: string;
  currentLocationId?: string;
  status: SerialStatus;
  installedAtDropId?: string;
  installedAtDropNumber?: string;
  installedAtHomeInstallId?: string;
  installedDate?: Date;
  installedBy?: string;
  receivedDate?: Date;
  receivedReference?: string;
  warrantyEndDate?: Date;
  condition: SerialCondition;
  createdAt: Date;
  updatedAt: Date;
  // Joined flat fields (from query joins)
  itemCode?: string;
  itemName?: string;
  itemCategory?: ItemCategory;
  locationCode?: string;
  locationName?: string;
  // Joined object references (alternative)
  stockItem?: StockItem;
  currentLocation?: StockLocation;
}

export interface StockQuant {
  id: string;
  stockItemId: string;
  locationId: string;
  projectId?: string;
  quantity: number;
  reservedQuantity: number;
  lotNumber?: string;
  unitCost?: number;
  totalValue?: number;
  lastMovementDate?: Date;
  createdAt: Date;
  updatedAt: Date;
  // Joined
  stockItem?: StockItem;
