export DATABASE_URL="$(grep '^DATABASE_URL=' .env.local | sed 's/^DATABASE_URL=//')" && node -e "
const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);
(async () => {
  // Check approved reviews and their photos as ground truth
  const stats = await sql\`
    SELECT p.project_name,
      COUNT(DISTINCT r.id)::int AS approved_reviews,
      COUNT(ph.id)::int AS approved_photos,
      COUNT(ph.id) FILTER (WHERE ph.checklist_step > 0)::int AS labeled_photos
    FROM construction_qa_reviews r
    JOIN construction_qa_photos ph ON ph.review_id = r.id
    JOIN projects p ON p.id = r.project_id
    WHERE r.workflow_status = 'approved'
    GROUP BY p.project_name ORDER BY p.project_name
  \`;
  console.log('APPROVED REVIEWS WITH LABELED PHOTOS (ground truth):');
  for (const s of stats) {
    console.log('  ' + s.project_name.padEnd(20) + s.approved_reviews + ' reviews, ' + s.labeled_photos + '/' + s.approved_photos + ' labeled photos');
  }

  // Check qa_decision_by field
  const deciders = await sql\`
    SELECT qa_decision_by, COUNT(*)::int AS cnt
    FROM construction_qa_reviews
    WHERE workflow_status = 'approved'
    GROUP BY qa_decision_by ORDER BY cnt DESC
  \`;
  console.log('\\nWho approved (qa_decision_by):');
  for (const d of deciders) console.log('  ' + (d.qa_decision_by || 'NULL') + ': ' + d.cnt);

  // Sample of labeled photos from approved reviews - step distribution
  const stepDist = await sql\`
    SELECT ph.checklist_step, ph.step_label, COUNT(*)::int AS cnt
    FROM construction_qa_photos ph
    JOIN construction_qa_reviews r ON r.id = ph.review_id
    WHERE r.workflow_status = 'approved' AND ph.checklist_step > 0
    GROUP BY ph.checklist_step, ph.step_label
    ORDER BY ph.checklist_step
  \`;
  console.log('\\nStep distribution in approved photos:');
  for (const s of stepDist) console.log('  Step ' + s.checklist_step + ' (' + (s.step_label || '?') + '): ' + s.cnt);

  // Check if photos have storage_key pointing to MinIO
  const storage = await sql\`
    SELECT 
      COUNT(*) FILTER (WHERE ph.storage_key LIKE 'projects/%')::int AS minio,
      COUNT(*) FILTER (WHERE ph.storage_key NOT LIKE 'projects/%' OR ph.storage_key IS NULL)::int AS other
    FROM construction_qa_photos ph
    JOIN construction_qa_reviews r ON r.id = ph.review_id
    WHERE r.workflow_status = 'approved' AND ph.checklist_step > 0
  \`;
  console.log('\\nStorage: MinIO=' + storage[0].minio + ', Other=' + storage[0].other);
})();
"

