/**
 * Build evaluation prompt for a specific step
 */
function buildStepPrompt(step: number, photoCount: number): string {
  const stepDescriptions: Record<number, string> = {
    1: 'House Photo - Verify clear view of property with visible address or landmarks',
    2: 'Cable from Pole - Check cable routing from pole to house is visible and properly secured',
    3: 'Cable Entry Outside - Verify cable entry point outside house is properly sealed',
    4: 'Cable Entry Inside - Check cable entry point inside house is neat and sealed',
    5: 'Wall Installation - Verify ONT mounting location is appropriate and secure',
    6: 'ONT Back - Check ONT is properly mounted with all connections visible',
    7: 'Power Meter - Verify power meter reading is clear and legible',
    8: 'ONT Barcode - Check ONT serial/barcode is clearly visible and legible',
    9: 'UPS Serial - Verify UPS serial number is clearly visible (if applicable)',
    10: 'Final Installation - Check overall installation quality and cable management',
    11: 'Green Lights on ONT - Verify all required lights are green/operational',
    12: 'Signature - Verify customer signature is present and legible',
  };

  const stepDescription = stepDescriptions[step] || `Step ${step}`;

  return `You are evaluating fiber installation photos for quality and compliance.

Step ${step}: ${stepDescription}

You have ${photoCount} photo(s) for this step.

Evaluate the photo(s) and provide:
1. A score from 0-10 (where 10 is perfect, 6+ is passing)
2. Pass/Fail status (pass if score >= 6)
3. A brief comment explaining your evaluation

Focus on:
- Photo clarity and quality
- Visibility of required elements
- Compliance with installation standards
- Safety and workmanship

Respond in JSON format:
{
  "step": ${step},
  "score": <number 0-10>,
  "passed": <boolean>,
  "comment": "<your evaluation comment>"
}`;
}

/**
 * Group photos by step number
 */
function groupPhotosByStep(photos: Photo[]): Record<number, Photo[]> {
  const grouped: Record<number, Photo[]> = {};

  photos.forEach((photo) => {
    if (!grouped[photo.step]) {
      grouped[photo.step] = [];
    }
    const step = grouped[photo.step];
    if (step) {
      step.push(photo);
    }
  });

  return grouped;
}

/**
 * Calculate overall status and average score
 */
function calculateOverallStatus(stepResults: AIStepResult[]): {
  overallStatus: 'PASS' | 'FAIL';
  averageScore: number;
} {
  if (stepResults.length === 0) {
    return {
      overallStatus: 'FAIL',
      averageScore: 0,
    };
  }

  const totalScore = stepResults.reduce((sum, result) => sum + result.score, 0);
  const averageScore = parseFloat((totalScore / stepResults.length).toFixed(1));

  // Pass if >= 9 steps passed (75% pass rate)
  const passedCount = stepResults.filter((result) => result.passed).length;
  const overallStatus = passedCount >= 9 ? 'PASS' : 'FAIL';

  return {
    overallStatus,
    averageScore,
  };
}

/**
 * Generate markdown report
 */
function generateMarkdownReport(
  dropNumber: string,
  stepResults: AIStepResult[],
  averageScore: number,
  overallStatus: 'PASS' | 'FAIL'
): string {
  const passedCount = stepResults.filter((result) => result.passed).length;
  const failedCount = stepResults.length - passedCount;

  let report = `# AI Evaluation Report - ${dropNumber}\n\n`;
  report += `**Overall Status:** ${overallStatus === 'PASS' ? '✅ PASS' : '❌ FAIL'}\n`;
  report += `**Average Score:** ${averageScore.toFixed(1)}/10\n`;
  report += `**Passed Steps:** ${passedCount}/${stepResults.length}\n`;
  report += `**Failed Steps:** ${failedCount}/${stepResults.length}\n\n`;

  report += `## Summary\n\n`;

  if (overallStatus === 'PASS') {
    report += `This installation meets quality standards with ${passedCount} out of ${stepResults.length} steps passing.\n\n`;
  } else {
    report += `This installation requires attention. ${failedCount} step(s) did not meet quality standards.\n\n`;
  }

  report += `## Step-by-Step Results\n\n`;

  stepResults.forEach((result) => {
    const emoji = result.passed ? '✅' : '❌';
    const stepLabels: Record<number, string> = {
      1: 'House Photo',
      2: 'Cable from Pole',
      3: 'Cable Entry Outside',
      4: 'Cable Entry Inside',
      5: 'Wall Installation',
      6: 'ONT Back',
      7: 'Power Meter',
      8: 'ONT Barcode',
      9: 'UPS Serial',
      10: 'Final Installation',
      11: 'Green Lights',
      12: 'Signature',
    };

    const stepLabel = stepLabels[result.step] || `Step ${result.step}`;

    report += `### ${emoji} Step ${result.step}: ${stepLabel}\n\n`;
    report += `**Score:** ${result.score.toFixed(1)}/10\n`;
    report += `**Status:** ${result.passed ? 'PASS' : 'FAIL'}\n\n`;
    report += `**Comment:** ${result.comment}\n\n`;
  });

  report += `---\n\n`;
  report += `## Recommendations\n\n`;

  if (overallStatus === 'FAIL') {
    report += `Please address the following steps that failed evaluation:\n\n`;

    stepResults
      .filter((result) => !result.passed)
      .forEach((result) => {
        report += `- **Step ${result.step}:** ${result.comment}\n`;
      });

    report += `\nRetake photos for failed steps and resubmit for review.\n\n`;
  } else {
    report += `Installation meets quality standards. No major issues identified.\n\n`;
  }

  report += `---\n\n`;
  report += `*Generated by AI Evaluation System (MiniCPM-V-2_6 VLM)*\n`;
  report += `*Evaluation Date: ${new Date().toISOString()}*\n`;

  return report;
}

/**
 * Create batches of photos for VLM processing
 * Limits batch size to avoid context overflow
 */
export function createPhotoBatches(photos: Photo[], batchSize: number = 6): Photo[][] {
  const batches: Photo[][] = [];

  for (let i = 0; i < photos.length; i += batchSize) {
    batches.push(photos.slice(i, i + batchSize));
  }

  return batches;
}

/**
 * API Route: /api/activate/categorize-photos
 *
 * Purpose: Run VLM categorization on photos for a DR
 * Method: POST
 *
 * This endpoint:
 * 1. Fetches ALL photos from OneMap (raw, without pre-categorization)
 * 2. Sends photos to Qwen3 VLM for category prediction
 * 3. Stores VLM predictions for human review
 */

import type { NextApiRequest, NextApiResponse } from 'next';

import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import {
  categorizePhotos,
  PhotoInput,
} from '@/modules/activate/services/categorizationVlmService';
import {
  fetchPhotosWithRetry,
  checkPhotosExist,
} from '@/modules/activate/services/photoFetchService';
import {
  CategorizePhotosRequest,
  CategorizePhotosResponse,
  VlmCategorizationResult,
} from '@/modules/activate/types/unified.types';
import {
  getStepAccuracy,
  assignTiers,
  buildSummary,
} from '@/modules/activate/services/autoApprovalService';


/**
 * POST /api/activate/categorize-photos
 * Run VLM categorization on photos
 */
async function handlePost(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  const startTime = Date.now();

  try {
    const { dropNumber, force, batchSize } = req.body as CategorizePhotosRequest;

    if (!dropNumber) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber is required');
    }

    log.info('CategorizePhotos', `Starting categorization for ${dropNumber}`, { force, batchSize });

    // Check if already categorized (skip unless forced)
    if (!force) {
      const existingResult = await pool.query(
        `SELECT vlm_categorization_status, vlm_categorization_results
         FROM dr_photo_unified_reviews
         WHERE drop_number = $1`,
        [dropNumber]
      );

      if (existingResult.rows.length > 0) {
        const existing = existingResult.rows[0];

        if (existing.vlm_categorization_status === 'categorized' ||
            existing.vlm_categorization_status === 'approved') {
          log.info('CategorizePhotos', `Already categorized for ${dropNumber}, skipping`);

          return apiResponse.success(res, {
            dropNumber,
            status: existing.vlm_categorization_status,
            photoCount: existing.vlm_categorization_results?.length || 0,
            categorizations: existing.vlm_categorization_results || [],
            processingTimeMs: Date.now() - startTime,
            skipped: true,
          } as CategorizePhotosResponse & { skipped: boolean });
        }
      }
    }

    // Update status to processing
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET vlm_categorization_status = 'processing', updated_at = NOW()
       WHERE drop_number = $1`,
      [dropNumber]
    );

    // Fetch photos from OneMap with robust retry logic
    log.info('CategorizePhotos', `Fetching photos for ${dropNumber} with retry`);
    const fetchResult = await fetchPhotosWithRetry(dropNumber, {
      maxRetries: 5,
      initialDelayMs: 2000,
      onStatusUpdate: (status) => {
        log.debug('CategorizePhotos', `Photo fetch status: ${status.message}`, {
          dropNumber,
          attempt: status.attempt,
          status: status.status,
        });
      },
    });

    const { photos, ont_barcode, ups_serial, fetchAttempts, downloadTriggered, totalWaitTimeMs } = fetchResult;

    log.info('CategorizePhotos', `Photo fetch complete for ${dropNumber}`, {
      photoCount: photos.length,
      fetchAttempts,
      downloadTriggered,
      totalWaitTimeMs,
    });

    if (photos.length === 0) {
      await pool.query(
        `UPDATE dr_photo_unified_reviews
         SET vlm_categorization_status = 'failed', updated_at = NOW()
         WHERE drop_number = $1`,
        [dropNumber]
      );

      return apiResponse.error(res, ErrorCode.NOT_FOUND, `No photos found for ${dropNumber}`);
    }

    log.info('CategorizePhotos', `Found ${photos.length} photos for ${dropNumber}`);

    // Run VLM categorization
    const categorizations = await categorizePhotos(dropNumber, photos, batchSize);

    // Store results in database
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET
         vlm_categorization_status = 'categorized',
         vlm_categorization_results = $1,
         vlm_categorized_at = NOW(),
         ont_serial_scanned = COALESCE($2, ont_serial_scanned),
         ups_serial_scanned = COALESCE($3, ups_serial_scanned),
         updated_at = NOW()
       WHERE drop_number = $4`,
      [JSON.stringify(categorizations), ont_barcode, ups_serial, dropNumber]
    );

    // Auto-approval: assign tiers based on confidence + historical accuracy
    let autoApprovalTiers;
    let autoApprovalSummary;
    try {
      const stepAccuracy = await getStepAccuracy();
      autoApprovalTiers = assignTiers(categorizations, stepAccuracy);
      autoApprovalSummary = buildSummary(autoApprovalTiers, stepAccuracy);

      log.info('CategorizePhotos', `Auto-approval tiers for ${dropNumber}`, {
        auto: autoApprovalSummary.autoApproved,
        review: autoApprovalSummary.reviewRecommended,
        human: autoApprovalSummary.humanRequired,
        overallAccuracy: autoApprovalSummary.overallAccuracy
          ? `${Math.round(autoApprovalSummary.overallAccuracy * 100)}%`
          : 'N/A',
      });
    } catch (tierError) {
      log.warn('CategorizePhotos', 'Auto-approval tier assignment failed, falling back', tierError);
    }

    const processingTimeMs = Date.now() - startTime;

    log.info('CategorizePhotos', `Categorization complete for ${dropNumber}`, {
      photoCount: categorizations.length,
      processingTimeMs,
    });

    const response: CategorizePhotosResponse = {
      dropNumber,
      status: 'categorized',
      photoCount: categorizations.length,
      categorizations,
      processingTimeMs,
      autoApprovalTiers,
      autoApprovalSummary,
    };

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('CategorizePhotos', 'Error during categorization', error);

    // Try to update status to failed
    try {
      const { dropNumber } = req.body as CategorizePhotosRequest;
      if (dropNumber) {
        await pool.query(
          `UPDATE dr_photo_unified_reviews
           SET vlm_categorization_status = 'failed', updated_at = NOW()
           WHERE drop_number = $1`,
          [dropNumber]
        );
      }
    } catch (dbError) {
      log.error('CategorizePhotos', 'Failed to update status to failed', dbError);
    }

    return apiResponse.internalError(res, error);
  }
}

/**
 * GET /api/activate/categorize-photos?dropNumber=XXX
 * Get existing categorization results
 */
async function handleGet(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  try {
    const { dropNumber } = req.query;

    if (!dropNumber || typeof dropNumber !== 'string') {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber query param is required');
    }

    const result = await pool.query(
      `SELECT vlm_categorization_status, vlm_categorization_results, vlm_categorized_at,
              vlm_approved_by, vlm_approved_at
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1`,
      [dropNumber]
    );

    if (result.rows.length === 0) {
      return apiResponse.notFound(res, 'Review', dropNumber);
    }

    const row = result.rows[0];
    let categorizations = row.vlm_categorization_results || [];
    let status = row.vlm_categorization_status;

    // Detect corrupted results: status is 'categorized' but results are empty objects
    // This happens when cron job stored data with wrong property names
    if (
      (status === 'categorized' || status === 'approved') &&
      categorizations.length > 0 &&
      categorizations.every((c: Record<string, unknown>) => !c.vlm_predicted_step && !c.photo_filename)
    ) {
      log.warn('CategorizePhotos', `Detected corrupted VLM results for ${dropNumber}, resetting to pending`);
      status = 'pending';
      categorizations = [];
    }

    // Compute auto-approval tiers for existing results
    let autoApprovalTiers;
    let autoApprovalSummary;
    if (categorizations.length > 0 && (status === 'categorized' || status === 'approved')) {
      try {
        const stepAccuracy = await getStepAccuracy();
        autoApprovalTiers = assignTiers(categorizations, stepAccuracy);
        autoApprovalSummary = buildSummary(autoApprovalTiers, stepAccuracy);
      } catch (tierError) {
        log.warn('CategorizePhotos', 'Failed to compute auto-approval tiers for GET', tierError);
      }
    }

    return apiResponse.success(res, {
      dropNumber,
      status,
      categorizations,
      categorizedAt: row.vlm_categorized_at,
      approvedBy: row.vlm_approved_by,
      approvedAt: row.vlm_approved_at,
      autoApprovalTiers,
      autoApprovalSummary,
    });
  } catch (error) {
    log.error('CategorizePhotos', 'Error getting categorization', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * Main handler
 */
async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method === 'POST') {
    return handlePost(req, res);
  } else if (req.method === 'GET') {
    return handleGet(req, res);
  } else {
    return apiResponse.error(res, ErrorCode.METHOD_NOT_ALLOWED, 'Method not allowed');
  }
}

export default withAuth(handler);

