/**
 * Get correction statistics for a workflow
 *
 * @param workflowType - Workflow type
 */
export async function getCorrectionStats(workflowType: WorkflowType): Promise<CorrectionStats> {
  try {
    // Get counts
    const countsResult = await db.query<{
      total: string;
      canonical: string;
      recent: string;
    }>(
      `SELECT
        COUNT(*) as total,
        COUNT(*) FILTER (WHERE is_canonical = true) as canonical,
        COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '30 days') as recent
       FROM qa_correction_examples
       WHERE workflow_type = $1`,
      [workflowType]
    );

    // Get top confused step pairs
    const confusedResult = await db.query<{
      vlm_step: number;
      correct_step: number;
      count: string;
    }>(
      `SELECT
        vlm_predicted_step as vlm_step,
        correct_step,
        COUNT(*) as count
       FROM qa_correction_examples
       WHERE workflow_type = $1
       GROUP BY vlm_predicted_step, correct_step
       ORDER BY count DESC
       LIMIT 5`,
      [workflowType]
    );

    const counts = countsResult.rows[0] || { total: '0', canonical: '0', recent: '0' };

    return {
      workflowType,
      totalCorrections: parseInt(counts.total, 10),
      canonicalCount: parseInt(counts.canonical, 10),
      recentCorrections: parseInt(counts.recent, 10),
      topConfusedSteps: confusedResult.rows.map((row) => ({
        vlmStep: row.vlm_step,
        correctStep: row.correct_step,
        count: parseInt(row.count, 10),
      })),
    };
  } catch (error) {
    log.error('CorrectionService', {
      action: 'getCorrectionStats',
      workflowType,
      error: error instanceof Error ? error.message : String(error),
    });

    throw new CorrectionServiceError(
      `Failed to get correction stats: ${error instanceof Error ? error.message : String(error)}`,
      'DB_QUERY_FAILED',
      error
    );
  }
}

/**
 * API Route: /api/activate/extract-data
 *
 * Purpose: Phase 3 of QA Wizard - Extract technical data from photos using VLM
 * Method: POST
 *
 * Extracts:
 * - Power meter dBm reading (Step 7)
 * - ONT serial from back (Step 6)
 * - ONT serial and DR number from front label (Step 9)
 */

import type { NextApiRequest, NextApiResponse } from 'next';

import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import {
  runFullExtraction,
  serialsMatch,
  drNumbersMatch,
  type FullExtractionResult,
} from '@/modules/activate/services/vlmExtractionService';
import {
  validatePowerMeter,
  validateSerialCrossReference,
  type DrValidationData,
  type PowerMeterResult,
  type SerialValidationResult,
} from '@/modules/activate/services/qaAutoFailService';

interface ExtractDataRequest {
  dropNumber: string;
  /** Force re-extraction even if already done */
  force?: boolean;
}

interface ExtractDataResponse {
  drNumber: string;
  extraction: FullExtractionResult;
  validation: {
    powerMeter: PowerMeterResult;
    serialCrossReference: SerialValidationResult;
  };
  summary: {
    powerMeterStatus: string;
    serialStatus: string;
    drNumberStatus: string;
    canProceed: boolean;
  };
  /** Whether confirmation mode was used (OneMap serial available) */
  usedConfirmationMode: boolean;
  processingTimeMs: number;
}

/**
 * POST /api/activate/extract-data
 */
async function handlePost(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  const startTime = Date.now();

  try {
    const { dropNumber, force = false } = req.body as ExtractDataRequest;

    if (!dropNumber) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber is required');
    }

    log.info('ExtractData', `Starting data extraction for ${dropNumber}`, { force });

    // Get categorized photos and VLM results from unified table (after migration 127)
    const reviewResult = await pool.query(
      `SELECT
         drop_number as dr_number,
         photos_metadata::text as photos,
         vlm_categorization_results::text as vlm_categorization,
         ont_serial_scanned as onemap_ont_serial,
         ups_serial_scanned as onemap_ups_serial,
         vlm_power_meter_dbm,
         vlm_ont_serial_step6,
         vlm_ont_serial_step9,
         vlm_dr_number_step9
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1
       LIMIT 1`,
      [dropNumber]
    );

    if (reviewResult.rows.length === 0) {
      return apiResponse.notFound(res, 'DR review', dropNumber);
    }

    const review = reviewResult.rows[0];

    // Check if extraction already done and not forcing
    if (
      !force &&
      (review.vlm_power_meter_dbm !== null ||
        review.vlm_ont_serial_step6 !== null ||
        review.vlm_ont_serial_step9 !== null)
    ) {
      log.info('ExtractData', `Extraction already done for ${dropNumber}, returning cached results`);

      // Return cached results
      const cachedValidation = buildValidationFromCached(review, dropNumber);

      return apiResponse.success(res, {
        drNumber: dropNumber,
        extraction: {
          drNumber: dropNumber,
          powerMeter: review.vlm_power_meter_dbm !== null
            ? { success: true, value: review.vlm_power_meter_dbm, unit: 'dBm', confidence: 1, rawText: null }
            : null,
          ontSerialStep6: review.vlm_ont_serial_step6
            ? { success: true, serial: review.vlm_ont_serial_step6, confidence: 1, location: 'back', rawText: null }
            : null,
          step9: review.vlm_ont_serial_step9 || review.vlm_dr_number_step9
            ? {
                ontSerial: review.vlm_ont_serial_step9
                  ? { success: true, serial: review.vlm_ont_serial_step9, confidence: 1, location: 'front_label', rawText: null }
                  : { success: false, serial: null, confidence: 0, location: 'front_label', rawText: null },
                drNumber: review.vlm_dr_number_step9
                  ? { success: true, drNumber: review.vlm_dr_number_step9, confidence: 1, rawText: null }
                  : { success: false, drNumber: null, confidence: 0, rawText: null },
                greenLightsVisible: true,
                processingTimeMs: 0,
              }
            : null,
          usedConfirmationMode: !!review.onemap_ont_serial, // Was confirmation mode used
          totalProcessingTimeMs: 0,
        },
        validation: cachedValidation.validation,
        summary: cachedValidation.summary,
        usedConfirmationMode: !!review.onemap_ont_serial,
        processingTimeMs: Date.now() - startTime,
        cached: true,
      });
    }

    // Parse photos to find URLs for Step 6, 7, 9
    let photos: Array<{ filename: string; url?: string; step?: number }> = [];
    try {
      const parsedPhotos = review.photos ? JSON.parse(review.photos) : [];
      const parsedCategorization = review.vlm_categorization ? JSON.parse(review.vlm_categorization) : [];

      // Merge photos with categorization
      photos = parsedPhotos.map((p: { filename: string; url?: string }) => {
        const cat = parsedCategorization.find(
          (c: { photo_filename: string; vlm_predicted_step?: number; human_override_step?: number }) =>
            c.photo_filename === p.filename
        );
        return {
          filename: p.filename,
          url: p.url || `/api/activate/photo/${dropNumber}/${p.filename}`,
          step: cat?.human_override_step ?? cat?.vlm_predicted_step ?? null,
        };
      });
    } catch (e) {
      log.warn('ExtractData', `Failed to parse photos for ${dropNumber}: ${e}`);
    }

    // Find ALL photos for each extraction step - VLM will try each to find best result
    const step6Photos = photos.filter((p) => p.step === 6);
    const step7Photos = photos.filter((p) => p.step === 7);
    const step9Photos = photos.filter((p) => p.step === 9);

    // Use full OneMap URLs for extraction (relative URLs don't work in server context)
    const ONEMAP_HOST = process.env.ONEMAP_HOST || 'http://100.96.203.105:8003';
    const makeOneMapUrl = (filename: string) => `${ONEMAP_HOST}/api/photo/${dropNumber}/${filename}`;

    log.info('ExtractData', `Found photos: Step6=${step6Photos.length}, Step7=${step7Photos.length}, Step9=${step9Photos.length}`);

    // Run VLM extraction with multiple photos per step
    // SMART MODE: If OneMap has serial, use CONFIRMATION mode (more accurate)
    // Otherwise use EXTRACTION mode (fallback)
    const onemapOntSerial = review.onemap_ont_serial;
    log.info('ExtractData', onemapOntSerial
      ? `Using CONFIRMATION mode with OneMap serial: ${onemapOntSerial}`
      : 'Using EXTRACTION mode (no OneMap serial)');

    const extraction = await runFullExtraction(
      dropNumber,
      {
        step6Urls: step6Photos.length > 0 ? step6Photos.map(p => makeOneMapUrl(p.filename)) : undefined,
        step7Urls: step7Photos.length > 0 ? step7Photos.map(p => makeOneMapUrl(p.filename)) : undefined,
        step9Urls: step9Photos.length > 0 ? step9Photos.map(p => makeOneMapUrl(p.filename)) : undefined,
      },
      {
        // Pass OneMap serial for confirmation mode (when available)
        expectedOntSerial: onemapOntSerial,
      }
    );

    // Build validation data
    const validationData: DrValidationData = {
      drNumber: dropNumber,
      photoCount: photos.length,
      photos: photos.map((p) => ({ filename: p.filename, step: p.step ?? null })),
      ontSerial: review.onemap_ont_serial,
      upsSerial: review.onemap_ups_serial,
      powerMeterDbm: extraction.powerMeter?.value ?? null,
      vlmOntSerialStep6: extraction.ontSerialStep6?.serial ?? null,
      vlmOntSerialStep9: extraction.step9?.ontSerial.serial ?? null,
      vlmDrNumberStep9: extraction.step9?.drNumber.drNumber ?? null,
    };

    // Run validations
    const powerMeterResult = validatePowerMeter(validationData.powerMeterDbm);
    const serialResult = validateSerialCrossReference(validationData);

    // Build summary
    const summary = buildSummary(powerMeterResult, serialResult, validationData);

    // Update database with extraction results
    const serialValidationDetails = JSON.stringify({
      onemapSerial: serialResult.onemapSerial,
      step6Serial: serialResult.step6Serial,
      step9Serial: serialResult.step9Serial,
      step9DrNumber: serialResult.step9DrNumber,
      ontMatch: serialResult.ontMatch,
      drMatch: serialResult.drMatch,
    });

    // Update extraction results directly in unified table (after migration 127)
    await pool.query(
      `UPDATE dr_photo_unified_reviews SET
         vlm_power_meter_dbm = $1,
         vlm_power_meter_status = $2,
         vlm_ont_serial_step6 = $3,
         vlm_ont_serial_step9 = $4,
         vlm_dr_number_step9 = $5,
         serial_validation_status = $6,
         serial_validation_details = $7,
         serial_extraction_method_step6 = $8,
         serial_extraction_method_step9 = $9,
         data_validation_completed = true,
         data_validation_completed_at = NOW(),
         qa_phase = 'final_decision',
         onemap_ont_serial = COALESCE($10, onemap_ont_serial),
         onemap_ups_serial = COALESCE($11, onemap_ups_serial),
         overall_status = 'PASS',
         updated_at = NOW()
       WHERE drop_number = $12`,
      [
        extraction.powerMeter?.value ?? null,
        powerMeterResult.status,
        extraction.ontSerialStep6?.serial ?? null,
        extraction.step9?.ontSerial.serial ?? null,
        extraction.step9?.drNumber.drNumber ?? null,
        serialResult.status,
        serialValidationDetails,
        extraction.ontSerialStep6?.extractionMethod ?? 'vlm',
        extraction.step9?.ontSerial.extractionMethod ?? 'vlm',
        review.onemap_ont_serial ?? null,
        review.onemap_ups_serial ?? null,
        dropNumber,
      ]
    );

    const processingTimeMs = Date.now() - startTime;

    log.info('ExtractData', `Data extraction complete for ${dropNumber}`, {
      processingTimeMs,
      powerMeter: powerMeterResult.status,
      serialStatus: serialResult.status,
    });

    const response: ExtractDataResponse = {
      drNumber: dropNumber,
      extraction,
      validation: {
        powerMeter: powerMeterResult,
        serialCrossReference: serialResult,
      },
      summary,
      usedConfirmationMode: extraction.usedConfirmationMode,
      processingTimeMs,
    };

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('ExtractData', 'Error extracting data', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * Build validation from cached DB values
 */
function buildValidationFromCached(
  review: {
    vlm_power_meter_dbm: number | null;
    vlm_ont_serial_step6: string | null;
    vlm_ont_serial_step9: string | null;
    vlm_dr_number_step9: string | null;
    onemap_ont_serial: string | null;
    onemap_ups_serial: string | null;
    dr_number: string;
  },
  dropNumber: string
) {
  const validationData: DrValidationData = {
    drNumber: dropNumber,
    photoCount: 0,
    photos: [],
    ontSerial: review.onemap_ont_serial,
    upsSerial: review.onemap_ups_serial,
    powerMeterDbm: review.vlm_power_meter_dbm,
    vlmOntSerialStep6: review.vlm_ont_serial_step6,
    vlmOntSerialStep9: review.vlm_ont_serial_step9,
    vlmDrNumberStep9: review.vlm_dr_number_step9,
  };

  const powerMeterResult = validatePowerMeter(validationData.powerMeterDbm);
  const serialResult = validateSerialCrossReference(validationData);
  const summary = buildSummary(powerMeterResult, serialResult, validationData);

  return { validation: { powerMeter: powerMeterResult, serialCrossReference: serialResult }, summary };
}

/**
 * Build human-readable summary
 */
function buildSummary(
  powerMeter: PowerMeterResult,
  serial: SerialValidationResult,
  data: DrValidationData
): ExtractDataResponse['summary'] {
  // Power meter status
  let powerMeterStatus: string;
  if (powerMeter.status === 'pass') {
    powerMeterStatus = `✅ ${powerMeter.value} dBm (in range -18 to -24)`;
  } else if (powerMeter.status === 'fail_high') {
    powerMeterStatus = `❌ ${powerMeter.value} dBm (too high, > -18)`;
  } else if (powerMeter.status === 'fail_low') {
    powerMeterStatus = `❌ ${powerMeter.value} dBm (too low, < -24)`;
  } else if (powerMeter.status === 'pending') {
    powerMeterStatus = '⏳ Not yet extracted';
  } else {
    powerMeterStatus = '🔧 Manual entry needed';
  }

  // Serial status
  let serialStatus: string;
  if (serial.status === 'match') {
    serialStatus = `✅ 3-way match: ${serial.onemapSerial}`;
  } else if (serial.status === 'mismatch') {
    serialStatus = `❌ Mismatch: ${serial.details}`;
  } else if (serial.status === 'pending') {
    serialStatus = '⏳ Not yet extracted';
  } else {
    serialStatus = '🔧 Partial match - review needed';
  }

  // DR number status
  let drNumberStatus: string;
  if (serial.drMatch) {
    drNumberStatus = `✅ Label matches ${data.drNumber}`;
  } else if (serial.step9DrNumber) {
    drNumberStatus = `❌ Label shows ${serial.step9DrNumber}, expected ${data.drNumber}`;
  } else {
    drNumberStatus = '⏳ Not yet extracted';
  }

  // Can proceed?
  const canProceed =
    powerMeter.status === 'pass' && serial.status === 'match' && serial.drMatch;

  return {
    powerMeterStatus,
    serialStatus,
    drNumberStatus,
    canProceed,
  };
}

/**
 * Main handler
 */
async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method === 'POST') {
    return handlePost(req, res);
  } else {
    return apiResponse.error(res, ErrorCode.METHOD_NOT_ALLOWED, 'Method not allowed');
  }
}

export default withAuth(handler);

/**
 * API Route: /api/activate/human-review
 *
 * Purpose: Phase 3 - Human review actions (approve/reject steps)
 * Method: POST (submit review), GET (get review status)
 *
 * This endpoint handles:
 * - Starting a human review session
 * - Approving individual steps
 * - Rejecting steps with reasons
 * - Completing the review
 */

import type { NextApiRequest, NextApiResponse } from 'next';

import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import {
  logHumanReviewStarted,
  logHumanReviewCompleted,
  logStepApproval,
  logStepRejection,
} from '@/modules/activate/services/activityLogService';
import { STEP_LABELS } from '@/modules/activate/utils/stepMapper';

// ============================================================================
// TYPES
// ============================================================================

interface StepReviewAction {
  step: number;
  action: 'approve' | 'reject';
  reason?: string;
  overrideVlm?: boolean;
}

interface StartReviewRequest {
  action: 'start';
  dropNumber: string;
  userId: string;
}

interface SubmitStepRequest {
  action: 'step';
  dropNumber: string;
  userId: string;
  stepReview: StepReviewAction;
}

interface CompleteReviewRequest {
  action: 'complete';
  dropNumber: string;
  userId: string;
}

type HumanReviewRequest = StartReviewRequest | SubmitStepRequest | CompleteReviewRequest;

// ============================================================================
// HANDLERS
// ============================================================================

/**
 * Handle starting a review session
 */
async function handleStartReview(
  dropNumber: string,
  userId: string,
  res: NextApiResponse
): Promise<void> {
  log.info('HumanReview', `Starting review for ${dropNumber} by ${userId}`);

  // Check if already being reviewed
  const lockResult = await pool.query(
    `SELECT locked_by, locked_at
     FROM dr_photo_unified_reviews
     WHERE drop_number = $1`,
    [dropNumber]
  );

  if (lockResult.rows.length === 0) {
    return apiResponse.notFound(res, 'Review', dropNumber);
  }

  const current = lockResult.rows[0];

  // Check if locked by another user (within 10 minutes)
  if (current.locked_by && current.locked_by !== userId) {
    const lockTime = new Date(current.locked_at);
    const tenMinutesAgo = new Date(Date.now() - 10 * 60 * 1000);

    if (lockTime > tenMinutesAgo) {
      return apiResponse.error(
        res,
        ErrorCode.CONFLICT,
        `Review is locked by another user (${current.locked_by})`
      );
    }
  }

  // Lock the review and set status
  await pool.query(
    `UPDATE dr_photo_unified_reviews
     SET
       locked_by = $1,
       locked_at = NOW(),
       human_review_status = 'in_progress',
       updated_at = NOW()
     WHERE drop_number = $2`,
    [userId, dropNumber]
  );

  // Log activity
  await logHumanReviewStarted(dropNumber, userId);

  return apiResponse.success(res, {
    dropNumber,
    status: 'started',
    lockedBy: userId,
    message: 'Review session started',
  });
}

/**
 * Handle step approval/rejection
 */
async function handleStepReview(
  dropNumber: string,
  userId: string,
  stepReview: StepReviewAction,
  res: NextApiResponse
): Promise<void> {
  const { step, action, reason, overrideVlm } = stepReview;
  const stepLabel = STEP_LABELS[step] || `Step ${step}`;

  log.info('HumanReview', `${action} step ${step} for ${dropNumber}`, { reason, overrideVlm });

  // Verify the user has the lock
  const lockResult = await pool.query(
    `SELECT locked_by, human_qa_overrides
     FROM dr_photo_unified_reviews
     WHERE drop_number = $1`,
    [dropNumber]
  );

  if (lockResult.rows.length === 0) {
    return apiResponse.notFound(res, 'Review', dropNumber);
  }

  const current = lockResult.rows[0];

  if (current.locked_by !== userId) {
    return apiResponse.error(
      res,
      ErrorCode.FORBIDDEN,
      'You do not have the review lock'
    );
  }

  // Get current overrides
  const overrides = current.human_qa_overrides || {};

  // Add the new override
  overrides[step] = {
    action,
    reason: reason || null,
    overrideVlm: overrideVlm || false,
    reviewedBy: userId,
    reviewedAt: new Date().toISOString(),
  };

  // Update database
  await pool.query(
    `UPDATE dr_photo_unified_reviews
     SET
       human_qa_overrides = $1,
       updated_at = NOW()
     WHERE drop_number = $2`,
    [JSON.stringify(overrides), dropNumber]
  );

  // Log activity
  if (action === 'approve') {
    await logStepApproval(dropNumber, step, stepLabel, userId);
  } else {
    await logStepRejection(dropNumber, step, stepLabel, reason || 'No reason provided', userId);
  }

  return apiResponse.success(res, {
    dropNumber,
    step,
    stepLabel,
    action,
    reason,
    overrideVlm,
    message: `Step ${step} ${action}d`,
  });
}

/**
 * Handle completing the review
 */
async function handleCompleteReview(
  dropNumber: string,
  userId: string,
  res: NextApiResponse
): Promise<void> {
  log.info('HumanReview', `Completing review for ${dropNumber} by ${userId}`);

  // Verify the user has the lock
  const lockResult = await pool.query(
    `SELECT locked_by, human_qa_overrides
     FROM dr_photo_unified_reviews
     WHERE drop_number = $1`,
    [dropNumber]
  );

  if (lockResult.rows.length === 0) {
    return apiResponse.notFound(res, 'Review', dropNumber);
  }

  const current = lockResult.rows[0];

  if (current.locked_by !== userId) {
    return apiResponse.error(
      res,
      ErrorCode.FORBIDDEN,
      'You do not have the review lock'
    );
  }

  // Count approved and rejected
  const overrides = current.human_qa_overrides || {};
  let approved = 0;
  let rejected = 0;

  for (const stepData of Object.values(overrides) as Array<{ action: string }>) {
    if (stepData.action === 'approve') approved++;
    if (stepData.action === 'reject') rejected++;
  }

  // Complete the review
  await pool.query(
    `UPDATE dr_photo_unified_reviews
     SET
       locked_by = NULL,
       locked_at = NULL,
       human_review_status = 'completed',
       human_review_completed_at = NOW(),
       human_reviewer_id = $1,
       updated_at = NOW()
     WHERE drop_number = $2`,
    [userId, dropNumber]
  );

  // Log activity
  await logHumanReviewCompleted(dropNumber, userId, approved, rejected);

  return apiResponse.success(res, {
    dropNumber,
    status: 'completed',
    reviewedBy: userId,
    approved,
    rejected,
    message: 'Review completed',
  });
}

/**
 * POST /api/activate/human-review
 * Handle review actions
 */
async function handlePost(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  try {
    const body = req.body as HumanReviewRequest;

    if (!body.dropNumber) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber is required');
    }

    if (!body.userId) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'userId is required');
    }

    switch (body.action) {
      case 'start':
        return handleStartReview(body.dropNumber, body.userId, res);

      case 'step':
        if (!body.stepReview) {
          return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'stepReview is required');
        }
        return handleStepReview(body.dropNumber, body.userId, body.stepReview, res);

      case 'complete':
        return handleCompleteReview(body.dropNumber, body.userId, res);

      default:
        return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'Invalid action');
    }
  } catch (error) {
    log.error('HumanReview', 'Error during human review', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * GET /api/activate/human-review?dropNumber=XXX
 * Get review status
 */
async function handleGet(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  try {
    const { dropNumber } = req.query;

    if (!dropNumber || typeof dropNumber !== 'string') {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber query param is required');
    }

    const result = await pool.query(
      `SELECT
         locked_by, locked_at,
         human_review_status, human_review_completed_at, human_reviewer_id,
         human_qa_overrides, vlm_qa_results, vlm_qa_summary
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1`,
      [dropNumber]
    );

    if (result.rows.length === 0) {
      return apiResponse.notFound(res, 'Review', dropNumber);
    }

    const row = result.rows[0];
    const overrides = row.human_qa_overrides || {};
    const qaResults = row.vlm_qa_results || {};

    // Count stats
    let approved = 0;
    let rejected = 0;
    let pending = 0;

    const stepResults = qaResults.stepResults || [];
    for (const stepResult of stepResults) {
      const override = overrides[stepResult.step];
      if (override) {
        if (override.action === 'approve') approved++;
        if (override.action === 'reject') rejected++;
      } else {
        pending++;
      }
    }

    return apiResponse.success(res, {
      dropNumber,
      lockedBy: row.locked_by,
      lockedAt: row.locked_at,
      status: row.human_review_status || 'pending',
      completedAt: row.human_review_completed_at,
      reviewerId: row.human_reviewer_id,
      overrides,
      vlmSummary: row.vlm_qa_summary,
      stats: {
        total: stepResults.length,
        approved,
        rejected,
        pending,
      },
    });
  } catch (error) {
    log.error('HumanReview', 'Error getting review status', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * DELETE /api/activate/human-review?dropNumber=XXX&userId=YYY
 * Release review lock
 */
async function handleDelete(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  try {
    const { dropNumber, userId } = req.query;

    if (!dropNumber || typeof dropNumber !== 'string') {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber query param is required');
    }

    if (!userId || typeof userId !== 'string') {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'userId query param is required');
    }

    // Verify the user has the lock
    const lockResult = await pool.query(
      `SELECT locked_by
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1`,
      [dropNumber]
    );

    if (lockResult.rows.length === 0) {
      return apiResponse.notFound(res, 'Review', dropNumber);
    }

    const current = lockResult.rows[0];

    if (current.locked_by !== userId) {
      return apiResponse.error(
        res,
        ErrorCode.FORBIDDEN,
        'You do not have the review lock'
      );
    }

    // Release the lock
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET
         locked_by = NULL,
         locked_at = NULL,
         updated_at = NOW()
       WHERE drop_number = $1`,
      [dropNumber]
    );

    return apiResponse.success(res, {
      dropNumber,
      message: 'Review lock released',
    });
  } catch (error) {
    log.error('HumanReview', 'Error releasing lock', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * Main handler
 */
async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method === 'POST') {
    return handlePost(req, res);
  } else if (req.method === 'GET') {
    return handleGet(req, res);
  } else if (req.method === 'DELETE') {
    return handleDelete(req, res);
  } else {
    return apiResponse.error(res, ErrorCode.METHOD_NOT_ALLOWED, 'Method not allowed');
  }
}

export default withAuth(handler);

/**
 * API Route: /api/activate/approve-categorization
 *
 * Purpose: Human approval/override of VLM photo categorizations
 * Method: POST
 *
 * This endpoint:
 * 1. Accepts human approvals/overrides for VLM predictions
 * 2. Updates photos_metadata with final step assignments
 * 3. Marks categorization as approved
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  ApproveCategorizeRequest,
  ApproveCategorizeResponse,
  VlmCategorizationResult,
  Photo,
} from '@/modules/activate/types/unified.types';
import { recordCorrection, RecordCorrectionInput } from '@/modules/qa-learning';
import { STEP_LABELS } from '@/modules/activate/utils/stepMapper';

/**
 * POST /api/activate/approve-categorization
 * Approve or override VLM categorizations
 */
async function handlePost(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  try {
    // Get authenticated user
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const approvedBy = userId || 'anonymous';

    const { dropNumber, approvals, approve_all, confirm_auto } = req.body as ApproveCategorizeRequest & { confirm_auto?: boolean };

    if (!dropNumber) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'dropNumber is required');
    }

    log.info('ApproveCategorization', `Processing approval for ${dropNumber}`, {
      approve_all,
      confirm_auto,
      approvalCount: approvals?.length || 0,
    });

    // Get current categorization results
    const result = await pool.query(
      `SELECT vlm_categorization_status, vlm_categorization_results, photos_metadata
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1`,
      [dropNumber]
    );

    if (result.rows.length === 0) {
      return apiResponse.notFound(res, 'Review', dropNumber);
    }

    const row = result.rows[0];

    if (row.vlm_categorization_status !== 'categorized') {
      return apiResponse.error(
        res,
        ErrorCode.BAD_REQUEST,
        `Cannot approve: categorization status is '${row.vlm_categorization_status}', expected 'categorized'`
      );
    }

    const currentResults: VlmCategorizationResult[] = row.vlm_categorization_results || [];
    const currentPhotos: Photo[] = row.photos_metadata || [];

    if (currentResults.length === 0) {
      return apiResponse.error(res, ErrorCode.BAD_REQUEST, 'No categorization results to approve');
    }

    // Process approvals
    let approvedCount = 0;
    let overriddenCount = 0;

    const updatedResults: VlmCategorizationResult[] = currentResults.map((catResult) => {
      if (approve_all) {
        // Approve all predictions
        approvedCount++;
        return {
          ...catResult,
          human_approved: true,
          human_override_step: null,
          human_override_reason: null,
        };
      }

      // Find specific approval for this photo
      const approval = approvals?.find((a) => a.photo_filename === catResult.photo_filename);

      if (!approval) {
        // No approval provided, keep as-is
        return catResult;
      }

      if (approval.approved) {
        // Approved as-is
        approvedCount++;
        return {
          ...catResult,
          human_approved: true,
          human_override_step: null,
          human_override_reason: null,
        };
      } else if (approval.override_step !== undefined) {
        // Overridden with different step
        overriddenCount++;
        return {
          ...catResult,
          human_approved: false,
          human_override_step: approval.override_step,
          human_override_reason: approval.override_reason || null,
        };
      }

      return catResult;
    });

    // Build updated photos_metadata with final step assignments
    const updatedPhotos: Photo[] = currentPhotos.map((photo) => {
      const catResult = updatedResults.find((r) => r.photo_filename === photo.filename);

      if (!catResult) {
        return photo;
      }

      // Determine final step: human override takes precedence, then VLM prediction
      const finalStep =
        catResult.human_override_step !== null
          ? catResult.human_override_step
          : catResult.vlm_predicted_step;

      return {
        ...photo,
        step: finalStep,
      };
    });

    // If no photos in metadata, create from categorization results
    const photosToStore =
      updatedPhotos.length > 0
        ? updatedPhotos
        : updatedResults.map((catResult) => ({
            filename: catResult.photo_filename,
            step:
              catResult.human_override_step !== null
                ? catResult.human_override_step
                : catResult.vlm_predicted_step,
            url: `/api/activate/photo/${dropNumber}/${catResult.photo_filename}`,
            original_type: catResult.original_type,
          }));

    // Update database
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET
         vlm_categorization_status = 'approved',
         vlm_categorization_results = $1,
         vlm_approved_by = $2,
         vlm_approved_at = NOW(),
         photos_metadata = $3,
         updated_at = NOW()
       WHERE drop_number = $4`,
      [JSON.stringify(updatedResults), approvedBy, JSON.stringify(photosToStore), dropNumber]
    );

    log.info('ApproveCategorization', `Approved categorization for ${dropNumber}`, {
      approvedCount,
      overriddenCount,
      totalPhotos: photosToStore.length,
    });

    // HITL Learning: Record human overrides as corrections for few-shot learning
    // Only record when human disagreed with VLM (override_step differs from vlm_predicted_step)
    const correctionsToRecord: RecordCorrectionInput[] = [];

    for (const catResult of updatedResults) {
      // Check if this was an override (human_override_step is set and differs from VLM prediction)
      if (
        catResult.human_override_step !== null &&
        catResult.human_override_step !== catResult.vlm_predicted_step
      ) {
        correctionsToRecord.push({
          workflowType: 'dr_photo',
          photoFilename: catResult.photo_filename,
          photoDescription: catResult.vlm_identified_as || undefined,
          vlmPredictedStep: catResult.vlm_predicted_step,
          vlmPredictedCategory: catResult.vlm_predicted_category,
          vlmConfidence: catResult.vlm_confidence,
          vlmReasoning: catResult.vlm_reasoning || undefined,
          correctStep: catResult.human_override_step,
          correctCategory: STEP_LABELS[catResult.human_override_step] || `Step ${catResult.human_override_step}`,
          correctionReason: catResult.human_override_reason || undefined,
          correctedBy: approvedBy,
        });
      }
    }

    // Record corrections asynchronously (don't block response)
    if (correctionsToRecord.length > 0) {
      Promise.all(
        correctionsToRecord.map((correction) =>
          recordCorrection(correction).catch((err) => {
            log.warn('ApproveCategorization', 'Failed to record correction for few-shot learning', {
              photoFilename: correction.photoFilename,
              error: err instanceof Error ? err.message : String(err),
            });
          })
        )
      ).then((results) => {
        const successCount = results.filter((r) => r !== undefined).length;
        log.info('ApproveCategorization', `Recorded ${successCount}/${correctionsToRecord.length} corrections for HITL learning`);
      });
    }

    const response: ApproveCategorizeResponse = {
      dropNumber,
      status: 'approved',
      approved_count: approvedCount,
      overridden_count: overriddenCount,
      photos_metadata: photosToStore,
    };

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('ApproveCategorization', 'Error during approval', error);
    return apiResponse.internalError(res, error);
  }
}

/**
 * Main handler
 */
async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method === 'POST') {
    return handlePost(req, res);
  } else {
    return apiResponse.error(res, ErrorCode.METHOD_NOT_ALLOWED, 'Method not allowed');
  }
}

export default withAuth(handler);

