                  {formatDisplayDateTime(step.completed_at)}
                </span>
              </div>
              {step.completed_by && (
                <div className="flex items-center gap-1">
                  <User className="w-3 h-3" />
                  <span>Completed by user</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </li>
  );
