          disabled || isUploading ? 'opacity-50 cursor-not-allowed' : '',
          error ? 'border-red-400' : ''
        )}
      >
        {isUploading ? (
          // Upload progress
          <div className="flex flex-col items-center justify-center space-y-2">
            <div className="w-full bg-[var(--ff-bg-tertiary)] rounded-full h-2">
