      photo_url,
      photo_verified,
      notes,
      created_at
    FROM maintenance_verification_steps
    WHERE ticket_id = $1
    ORDER BY step_number ASC`,
    [ticketId]
  );

  logger.debug('Retrieved verification steps', {
