              <span className="text-xs text-[var(--ff-text-secondary)]">Drop, paste, or click to upload</span>
            </div>
          )}
        </div>
      )}
    </div>

    {/* Error message */}
    {error && (
      <div className="mt-2 flex items-center space-x-1 text-red-400 text-xs">
        <AlertCircle className="w-3 h-3" />
        <span>{error}</span>
      </div>
    )}
  </div>
);

