 * @returns Ordered array of VerificationStepTemplate
 */
export function getStepsForTicketType(ticketType: string): VerificationStepTemplate[] {
  return VERIFICATION_STEPS_BY_TICKET_TYPE[ticketType] ?? VERIFICATION_STEPS;
}

