 * // WORKING: Initialize type-specific verification steps for a ticket
 *
 * Creates verification steps based on the ticket's type column.
 * Returns error if steps already exist.
 *
 * Response (201):
 * {
 *   success: true,
 *   data: VerificationStep[],
 *   message: string
 * }
 */
export async function POST(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const ticketId = params.id;

    // Validate UUID format
    if (!isValidUUID(ticketId)) {
      return validationError('Invalid ticket ID format. Must be a valid UUID');
    }

    logger.info('Initializing verification steps', { ticketId });

    // Fetch ticket type so we can select the correct step checklist
    const ticketRows = await sql`
      SELECT type FROM maintenance_tickets WHERE id = ${ticketId}
    `;

    if (ticketRows.length === 0) {
      return notFoundError('Ticket', ticketId);
    }

    const ticketType = (ticketRows[0].type as string) ?? 'new_installation';

    // Initialize type-specific verification steps
    const steps = await initializeVerificationSteps(ticketId, ticketType);

    return NextResponse.json({
      success: true,
      data: steps,
      message: `Initialized ${steps.length} verification steps`,
      meta: {
        timestamp: new Date().toISOString(),
        count: steps.length,
      },
    }, { status: 201 });
  } catch (error) {
    logger.error('Error initializing verification steps', {
      error,
      ticketId: params.id,
    });

    const errorMessage = error instanceof Error ? error.message : String(error);

    if (errorMessage.includes('not found')) {
      return notFoundError('Ticket', params.id);
    }

    if (errorMessage.includes('already initialized')) {
      return NextResponse.json({
        success: false,
        error: {
          code: 'ALREADY_EXISTS',
          message: 'Verification steps already initialized for this ticket',
        },
        meta: {
          timestamp: new Date().toISOString(),
        },
      }, { status: 409 });
    }

    return databaseError('Failed to initialize verification steps');
  }
}

