            </svg>
            Asset
          </div>
        )}
      </div>

      {/* Footer: Assignee, Time in Status, Created */}
      <div className="flex items-center justify-between mt-2 pt-2 border-t border-[var(--ff-border-light)]">
        <div className="flex items-center gap-2">
