              <button
                onClick={() => handleScopeChange('my_team')}
                className={`
                  flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium transition-all
                  ${ticketScope === 'my_team'
                    ? 'bg-purple-500 text-white shadow-sm'
