                  ${ticketScope === 'my_tickets'
                    ? 'bg-blue-500 text-white shadow-sm'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-secondary)]'
                  }
                `}
