    needsInvestigation: number;
    escalated: number;
    fixedThisWeek: number;
    totalImported: number;
  };
  qfield: {
    totalProjects: number;
    activeProjects: number;
    lastSync: string | null;
  };
}

// API response type
export interface DataSyncStatsResponse {
  success: boolean;
  data: DataSyncStats;
  error?: string;
}

// Maintenance tab IDs
export type NocTabId =
  | 'qcontact'
  | 'alignment'
  | 'three-way'
  | 'weekly'
  | 'wa-tracking';

// Activate tab IDs
export type ActivateTabId = 'oes' | 'arch' | 'manual' | 'pp-data';

// OLT Report tab IDs
export type OltTabId =
  | 'import'
  | 'pending'
  | 'investigate'
  | 'escalations'
  | 'history'
  | 'reporting';

// QField tab IDs
export type QFieldTabId = 'projects';

// History tab IDs
export type HistoryTabId = 'timeline';

// Sync operation type for history
export type SyncOperationType =
  | 'oes_import'
  | 'arch_import'
  | 'qcontact_sync'
  | 'qfield_sync'
  | 'olt_import';

// Unified sync history entry (from UNION query)
export interface SyncHistoryEntry {
