    FROM construction_qa_photos
    WHERE project_id = 'ce3bf310-d6ba-4ede-ab36-a8c902a5efc6'
    GROUP BY source\`;
  console.log('Photos by source:', JSON.stringify(photos));

  // Total poles with reviews vs without
  const coverage = await sql\`
    SELECT 
      COUNT(DISTINCT p.pole_number)::int AS total_poles,
