    JOIN construction_qa_reviews r ON r.id = ph.review_id
    WHERE ph.project_id = 'ce3bf310-d6ba-4ede-ab36-a8c902a5efc6'
    ORDER BY ph.created_at DESC LIMIT 5\`;
  console.log('Recent photos:', JSON.stringify(sample, null, 2));

  // Poles with status=installed but NO review
  const noReview = await sql\`
