// 🟢 WORKING: Enable auto-recording on upcoming Teams meetings via Graph API
// Requires: Calendars.Read + OnlineMeetings.ReadWrite.All application permissions
// Also requires Teams Application Access Policy (PowerShell)
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const LOGGER = 'AutoRecording';

// Only scan calendars for users in these email domains
const INTERNAL_DOMAINS = ['velocityfibre.co.za', 'blitzfibre.com'];

/** Calendar event from Graph calendarView API */
interface CalendarEvent {
  id: string;
  subject: string;
  start: { dateTime: string; timeZone: string };
  end: { dateTime: string; timeZone: string };
  isOnlineMeeting: boolean;
  isCancelled?: boolean;
  onlineMeeting?: { joinUrl: string };
  organizer?: { emailAddress: { address: string; name: string } };
}

/** Online meeting resource from Graph */
interface OnlineMeeting {
  id: string;
  subject: string;
  recordAutomatically: boolean;
}

/** Result of enabling auto-recording for a batch of meetings */
export interface AutoRecordingResult {
  usersChecked: number;
  meetingsFound: number;
  alreadyEnabled: number;
  newlyEnabled: number;
  failed: number;
  errors: string[];
  calendarAccessDenied?: boolean;
  meetingAccessDenied?: boolean;
}

/**
 * Fetches internal users in the tenant (VelocityFibre/BlitzFibre domains only).
 * Skips external/guest accounts (#EXT#) and service accounts.
 */
async function getInternalUsers(): Promise<{ id: string; displayName: string; mail: string }[]> {
  const users: { id: string; displayName: string; mail: string }[] = [];
  let url = `${GRAPH_BASE}/users?$filter=accountEnabled eq true&$select=id,displayName,mail,userPrincipalName&$top=100`;

  while (url) {
    const response = await graphFetch(url);
    if (!response.ok) {
      const err = await response.text();
      log.error('Failed to fetch users', { status: response.status, error: err }, LOGGER);
      throw new Error(`Graph API /users failed: ${response.status} — ${err.slice(0, 200)}`);
    }

    const data = await response.json();
    const pageUsers = (data.value || [])
      .map((u: Record<string, string>) => ({
        id: u.id,
        displayName: u.displayName || '',
        mail: u.mail || u.userPrincipalName || '',
        upn: u.userPrincipalName || '',
      }))
      .filter((u: { mail: string; upn: string }) => {
        // Skip external/guest users
        if (u.upn.includes('#EXT#')) return false;
        // Only keep internal domain users
        const domain = u.mail.split('@')[1]?.toLowerCase();
        return domain && INTERNAL_DOMAINS.includes(domain);
      })
      .map((u: { id: string; displayName: string; mail: string }) => ({
        id: u.id,
        displayName: u.displayName,
        mail: u.mail,
      }));

    users.push(...pageUsers);
    url = data['@odata.nextLink'] || '';
  }

  return users;
}

/**
 * Fetches upcoming calendar events for a user within a time window.
 * Only returns Teams online meetings.
 *
 * @returns events array, or null if calendar access is denied (missing Calendars.Read)
 */
async function getUpcomingTeamsMeetings(
  userId: string,
  hoursAhead: number
): Promise<CalendarEvent[] | null> {
  const now = new Date();
  const end = new Date(now.getTime() + hoursAhead * 60 * 60 * 1000);

  // Note: isOnlineMeeting does not support $filter — filter client-side
  const url = `${GRAPH_BASE}/users/${userId}/calendarView` +
    `?startDateTime=${now.toISOString()}` +
    `&endDateTime=${end.toISOString()}` +
    `&$select=id,subject,start,end,isOnlineMeeting,isCancelled,onlineMeeting,organizer` +
    `&$top=50`;

  const response = await graphFetch(url);
  if (!response.ok) {
    const err = await response.text();
    // 403 = Access Denied — missing Calendars.Read permission
    if (response.status === 403) return null;
    // 404 = Mailbox not found (shared/inactive mailbox) — skip user
    if (response.status === 404) return [];
    log.warn('Failed to fetch calendar', { userId, status: response.status, error: err }, LOGGER);
    return [];
  }

  const data = await response.json();
  // Client-side filter: only active Teams online meetings with a join URL
  return ((data.value || []) as CalendarEvent[]).filter(
    e => e.isOnlineMeeting && e.onlineMeeting?.joinUrl && !e.isCancelled
  );
}

/**
 * Resolves a join URL to an online meeting ID, then PATCHes it to enable
 * auto-recording.
 *
 * @returns 'enabled' | 'already' | 'failed' | 'access_denied'
 */
async function enableAutoRecordForMeeting(
  organizerUserId: string,
  joinUrl: string,
  subject: string
): Promise<'enabled' | 'already' | 'failed' | 'access_denied'> {
  // encodeURIComponent the $filter value (NOT the $filter key — $ must stay literal)
  // Join URLs contain %3a etc. that corrupt query strings if embedded raw
  const filterValue = encodeURIComponent(`JoinWebUrl eq '${joinUrl}'`);
  const findUrl = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings?$filter=${filterValue}`;

  const findResp = await graphFetch(findUrl);
  if (findResp.status === 403) {
    log.warn('OnlineMeetings access denied — application access policy required', { subject }, LOGGER);
    return 'access_denied';
  }
  if (!findResp.ok) {
    const err = await findResp.text();
    log.warn('Cannot find online meeting', { subject, status: findResp.status, error: err.slice(0, 200) }, LOGGER);
    return 'failed';
  }

  const data = await findResp.json();
  const meetings = (data.value || []) as OnlineMeeting[];
  if (meetings.length === 0) {
    log.warn('Online meeting not found for join URL', { subject }, LOGGER);
    return 'failed';
  }

  return await patchMeeting(organizerUserId, meetings[0]!, subject);
}

async function patchMeeting(
  organizerUserId: string,
  meeting: OnlineMeeting,
  subject: string
): Promise<'enabled' | 'already' | 'access_denied'> {
  if (meeting.recordAutomatically) {
    return 'already';
  }

  const patchUrl = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${meeting.id}`;
  const patchResp = await graphFetch(patchUrl, {
    method: 'PATCH',
    body: JSON.stringify({ recordAutomatically: true }),
  });

  if (patchResp.status === 403) {
    log.warn('PATCH denied — application access policy required', { subject, meetingId: meeting.id }, LOGGER);
    return 'access_denied';
  }

  if (!patchResp.ok) {
    const err = await patchResp.text();
    log.error('Failed to PATCH meeting', { subject, meetingId: meeting.id, error: err }, LOGGER);
    return 'already'; // Don't count as failed — unknown permission issue
  }

  log.info('Auto-recording enabled', { subject, meetingId: meeting.id }, LOGGER);
  return 'enabled';
}

/**
 * Main entry point: scans internal users' calendars for upcoming Teams meetings
 * and enables auto-recording on each one.
 *
 * @param hoursAhead - How far ahead to look for meetings (default: 24)
 */
export async function enableAutoRecordingForUpcomingMeetings(
  hoursAhead = 24
): Promise<AutoRecordingResult> {
  const result: AutoRecordingResult = {
    usersChecked: 0,
    meetingsFound: 0,
    alreadyEnabled: 0,
    newlyEnabled: 0,
    failed: 0,
    errors: [],
  };

  const users = await getInternalUsers();
  result.usersChecked = users.length;

  log.info('Auto-recording scan started', { users: users.length, hoursAhead }, LOGGER);

  // Fast-fail: check calendar access on first user
  if (users.length > 0) {
    const testEvents = await getUpcomingTeamsMeetings(users[0]!.id, hoursAhead);
    if (testEvents === null) {
      result.calendarAccessDenied = true;
      result.errors.push(
        'Calendar access denied (403). Add Calendars.Read application permission ' +
        'in Azure AD → API permissions → Grant admin consent.'
      );
      log.error('Calendar access denied — Calendars.Read permission missing', {}, LOGGER);
      return result;
    }
  }

  // Track meetings: seenUrls for counting, processedUrls for organizer-processed
  const seenUrls = new Set<string>();
  const processedUrls = new Set<string>();

  for (const user of users) {
    try {
      const events = await getUpcomingTeamsMeetings(user.id, hoursAhead);
      if (events === null) continue; // Skip users with no calendar access

      for (const event of events) {
        const joinUrl = event.onlineMeeting?.joinUrl;
        if (!joinUrl) continue;

        // Count each unique meeting once
        if (!seenUrls.has(joinUrl)) {
          seenUrls.add(joinUrl);
          result.meetingsFound++;
        }

        // Skip if already processed by the organizer
        if (processedUrls.has(joinUrl)) continue;

        // Only the organizer can modify meeting settings
        const isOrganizer = event.organizer?.emailAddress?.address?.toLowerCase() === user.mail?.toLowerCase();
        if (!isOrganizer) continue;

        processedUrls.add(joinUrl);

        try {
          const status = await enableAutoRecordForMeeting(user.id, joinUrl, event.subject);
          if (status === 'enabled') result.newlyEnabled++;
          else if (status === 'already') result.alreadyEnabled++;
          else if (status === 'access_denied') {
            result.meetingAccessDenied = true;
            result.failed++;
            result.errors.push(
              `${event.subject}: OnlineMeetings access denied. ` +
              'Create a Teams Application Access Policy via PowerShell.'
            );
            break;
          } else {
            result.failed++;
          }
        } catch (error: unknown) {
          result.failed++;
          const msg = error instanceof Error ? error.message : String(error);
          result.errors.push(`${event.subject}: ${msg}`);
        }
      }

      if (result.meetingAccessDenied) break;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      log.warn('Failed to scan user calendar', { user: user.mail, error: msg }, LOGGER);
    }
  }

  log.info('Auto-recording scan complete', result, LOGGER);
  return result;
}

// 🟢 WORKING: Microsoft Graph API OAuth2 client-credentials auth with token caching
import { log } from '@/lib/logger';

/** Required environment configuration for Microsoft Graph API */
interface GraphConfig {
  tenantId: string;
  clientId: string;
  clientSecret: string;
}

/** In-memory token cache entry */
interface TokenCache {
  token: string;
  expiresAt: number;
}

/** Module-level token cache — survives across requests within the same Node.js process */
let tokenCache: TokenCache | null = null;

/**
 * Reads and validates Graph API credentials from environment variables.
 * Throws if any required variable is missing.
 */
export function getGraphConfig(): GraphConfig {
  const tenantId = process.env.GRAPH_TENANT_ID;
  const clientId = process.env.GRAPH_CLIENT_ID;
  const clientSecret = process.env.GRAPH_CLIENT_SECRET;

  if (!tenantId || !clientId || !clientSecret) {
    throw new Error(
      'Missing Graph API configuration: GRAPH_TENANT_ID, GRAPH_CLIENT_ID, GRAPH_CLIENT_SECRET required'
    );
  }

  return { tenantId, clientId, clientSecret };
}

/**
 * Returns a valid Graph API access token, using the cached token when possible.
 * Automatically refreshes 5 minutes before expiry.
 */
export async function getGraphAccessToken(): Promise<string> {
  // Return cached token if still valid (with 5-minute buffer)
  if (tokenCache && tokenCache.expiresAt > Date.now() + 300_000) {
    return tokenCache.token;
  }

  const config = getGraphConfig();
  const tokenUrl = `https://login.microsoftonline.com/${config.tenantId}/oauth2/v2.0/token`;

  const params = new URLSearchParams({
    client_id: config.clientId,
    client_secret: config.clientSecret,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  });

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 30_000);

  try {
    const response = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
      signal: controller.signal,
    });

    clearTimeout(timeout);

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Graph OAuth failed: ${response.status} ${errorText}`);
    }

    const data = await response.json();
    tokenCache = {
      token: data.access_token as string,
      expiresAt: Date.now() + (data.expires_in as number) * 1000,
    };

    log.info('Graph access token acquired', { expiresIn: data.expires_in }, 'GraphAuth');
    return tokenCache.token;
  } catch (error: unknown) {
    clearTimeout(timeout);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('Graph OAuth token request timed out after 30s');
    }
    throw error;
  }
}

/**
 * Authenticated fetch wrapper for Microsoft Graph API endpoints.
 * Automatically injects the Bearer token and retries once on 401.
 *
 * @param url - Full Graph API URL
 * @param options - Standard fetch RequestInit options (headers will be merged)
 */
export async function graphFetch(url: string, options: RequestInit = {}): Promise<Response> {
  const token = await getGraphAccessToken();

  const response = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

  // Retry once on 401 — token may have expired between cache check and use
  if (response.status === 401) {
    tokenCache = null;
    const freshToken = await getGraphAccessToken();
    return fetch(url, {
      ...options,
      headers: {
        Authorization: `Bearer ${freshToken}`,
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  return response;
}

// 🟢 WORKING: Fallback cron — polls Teams call records every 15 min via CRON_SECRET
// Used as a safety net when Graph webhook subscriptions lapse or miss events
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { fetchRecentCallRecords } from '@/lib/graph/call-records';
import { processMeetingFromCallRecord } from '@/lib/graph/meeting-processor';
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);

const LOGGER = 'TeamsCron';

/** Look-back window — covers two cron intervals with overlap for safety */
const POLL_WINDOW_MINUTES = 60;

/**
 * POST /api/cron/poll-teams
 *
 * Polls the Graph callRecords API for the last POLL_WINDOW_MINUTES and processes
 * any call records that do not yet have a meetings row.
 *
 * Auth: CRON_SECRET bearer token (same pattern as meetings-sync-cron.ts).
 * Schedule: every 15 minutes via system cron or Vercel Cron.
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/poll-teams \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const since = new Date(Date.now() - POLL_WINDOW_MINUTES * 60 * 1000);
    const records = await fetchRecentCallRecords(since);

    log.info(
      'Teams poll: call records fetched',
      { count: records.length, since: since.toISOString() },
      LOGGER
    );

    let processed = 0;
    let skipped = 0;
    let failed = 0;

    for (const record of records) {
      // Any non-failed status means we have already attempted this record
      const existing = await sql`
        SELECT id
        FROM meetings
        WHERE teams_call_record_id = ${record.id}
      `;

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      try {
        const meetingId = await processMeetingFromCallRecord(record.id);
        if (meetingId > 0) processed++;
      } catch (error: unknown) {
        failed++;
        const errorMsg = error instanceof Error ? error.message : String(error);
        log.error(
          'Teams poll: failed to process call record',
          { callRecordId: record.id, error: errorMsg },
          LOGGER
        );
      }
    }

    log.info(
      'Teams poll cron complete',
      { total: records.length, processed, skipped, failed },
      LOGGER
    );

    res.status(200).json({
      success: true,
      fetched: records.length,
      processed,
      skipped,
      failed,
    });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Teams poll cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

// 🟢 WORKING: Core orchestrator — processes a single Teams call record into a meeting row
import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { fetchCallRecordById } from './call-records';
import {
  fetchOnlineMeetingInfo,
  listTranscripts,
  downloadTranscriptContent,
  parseVttSpeakers,
} from './transcripts';
import { listRecordings, downloadRecordingToDisk } from './recordings';
import { resolveParticipants } from './speaker-resolver';
import { processWithLLM } from '@/lib/llm/meeting-processor';

const sql = neon(process.env.DATABASE_URL!);

/** Transcripts larger than this are spilled to the meeting_transcripts table */
const TRANSCRIPT_INLINE_LIMIT = 500_000;

/** Minimum call duration to process (very short calls are noise) */
const MIN_DURATION_SECONDS = 60;

const LOGGER = 'MeetingProcessor';

/**
 * Processes a single Teams call record into a fully enriched meeting row.
 *
 * Execution order:
 *   1. Fetch the full call record (with sessions/segments expanded)
 *   2. Skip calls shorter than MIN_DURATION_SECONDS
 *   3. Resolve all participants via Graph /users
 *   4. Upsert the meeting row (idempotent on teams_call_record_id)
 *   5. Fetch transcript (inline or spill to meeting_transcripts)
 *   6. Download recording to disk
 *   7. Run LLM enrichment (summary, action items, topics)
 *   8. Mark status = 'completed'
 *
 * On any failure after the upsert, status is set to 'failed' with the
 * error message persisted in processing_error so ops can inspect.
 *
 * @param callRecordId - Graph callRecord ID (UUID)
 * @returns The database ID of the meeting row, or 0 if the call was skipped
 */
export async function processMeetingFromCallRecord(callRecordId: string): Promise<number> {
  // 1. Fetch full call record with sessions expanded
  const callRecord = await fetchCallRecordById(callRecordId);

  // 2. Skip calls shorter than minimum duration
  const startMs = new Date(callRecord.startDateTime).getTime();
  const endMs = new Date(callRecord.endDateTime).getTime();
  const durationSeconds = Math.floor((endMs - startMs) / 1000);

  if (durationSeconds < MIN_DURATION_SECONDS) {
    log.info(
      'Skipping short call',
      { callRecordId, durationSeconds, minRequired: MIN_DURATION_SECONDS },
      LOGGER
    );
    return 0;
  }

  // 3. Resolve participants (deduped by Graph user ID)
  const participants = await resolveParticipants(callRecord);

  const participantsJson = JSON.stringify(
    participants.map(p => ({
      name: p.displayName,
      email: p.email,
      displayName: p.displayName,
    }))
  );

  // Identify organizer from the call record organizer field
  const organizer = callRecord.organizer?.user;
  const organizerParticipant = organizer?.id
    ? participants.find(p => p.graphUserId === organizer.id) ?? null
    : null;

  // 4. Upsert meeting row — idempotent on teams_call_record_id
  const title = `Teams Meeting - ${new Date(callRecord.startDateTime).toLocaleDateString('en-ZA')}`;
  const durationMinutes = Math.floor(durationSeconds / 60);

  const rows = await sql`
    INSERT INTO meetings (
      title,
      meeting_date,
      duration,
      participants,
      source,
      teams_call_record_id,
      teams_meeting_id,
      organizer_email,
      organizer_name,
      join_url,
      processing_status,
      created_at,
      updated_at
    ) VALUES (
      ${title},
      ${callRecord.startDateTime},
      ${durationMinutes},
      ${participantsJson},
      'teams',
      ${callRecordId},
      ${callRecord.joinWebUrl ?? null},
      ${organizerParticipant?.email ?? null},
      ${organizerParticipant?.displayName ?? organizer?.displayName ?? null},
      ${callRecord.joinWebUrl ?? null},
      'fetching',
      NOW(),
      NOW()
    )
    ON CONFLICT (teams_call_record_id) DO UPDATE SET
      title              = EXCLUDED.title,
      duration           = EXCLUDED.duration,
      participants       = EXCLUDED.participants,
      organizer_email    = EXCLUDED.organizer_email,
      organizer_name     = EXCLUDED.organizer_name,
      processing_status  = 'fetching',
      processing_error   = NULL,
      updated_at         = NOW()
    RETURNING id
  `;

  const meetingId = rows[0]!.id as number;
  log.info('Meeting upserted', { meetingId, callRecordId, durationMinutes }, LOGGER);

  try {
    // 5. Fetch transcript and recording (requires joinWebUrl + a resolved organizer)
    if (callRecord.joinWebUrl && organizerParticipant) {
      const meetingInfo = await fetchOnlineMeetingInfo(
        organizerParticipant.graphUserId,
        callRecord.joinWebUrl
      );

      // Update title from calendar subject if available
      if (meetingInfo?.subject) {
        await sql`UPDATE meetings SET title = ${meetingInfo.subject}, updated_at = NOW() WHERE id = ${meetingId}`;
        log.info('Title updated from calendar subject', { meetingId, subject: meetingInfo.subject }, LOGGER);
      }

      if (meetingInfo?.id) {
        await fetchAndStoreTranscript(
          meetingId,
          organizerParticipant.graphUserId,
          meetingInfo.id
        );

        await fetchAndStoreRecording(
          meetingId,
          organizerParticipant.graphUserId,
          meetingInfo.id
        );
      }
    }

    // 6. LLM enrichment
    await sql`UPDATE meetings SET processing_status = 'processing', updated_at = NOW() WHERE id = ${meetingId}`;
    await processWithLLM(meetingId);

    // 7. Mark complete
    await sql`
      UPDATE meetings
      SET processing_status = 'completed',
          processed_at      = NOW(),
          updated_at        = NOW()
      WHERE id = ${meetingId}
    `;

    log.info('Meeting processing complete', { meetingId }, LOGGER);
    return meetingId;
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Meeting processing failed', { meetingId, error: errorMsg }, LOGGER);

    await sql`
      UPDATE meetings
      SET processing_status = 'failed',
          processing_error  = ${errorMsg},
          updated_at        = NOW()
      WHERE id = ${meetingId}
    `;

    throw error;
  }
}

/**
 * Fetches the transcript for an online meeting and persists it.
 * Transcripts under TRANSCRIPT_INLINE_LIMIT are stored inline on the meetings row.
 * Larger transcripts are written to the meeting_transcripts table.
 */
async function fetchAndStoreTranscript(
  meetingId: number,
  organizerUserId: string,
  onlineMeetingId: string
): Promise<void> {
  const transcripts = await listTranscripts(organizerUserId, onlineMeetingId);

  if (transcripts.length === 0) {
    log.info('No transcripts available', { meetingId, onlineMeetingId }, LOGGER);
    return;
  }

  // Take the most recent transcript (first in list from Graph)
  const vtt = await downloadTranscriptContent(
    organizerUserId,
    onlineMeetingId,
    transcripts[0]!.id
  );

  if (vtt.length <= TRANSCRIPT_INLINE_LIMIT) {
    await sql`UPDATE meetings SET raw_transcript = ${vtt}, updated_at = NOW() WHERE id = ${meetingId}`;
  } else {
    // Spill to meeting_transcripts; store first 50 speakers in speaker_map for quick lookup
    const speakerMap = JSON.stringify(parseVttSpeakers(vtt).slice(0, 50));
    await sql`
      INSERT INTO meeting_transcripts (meeting_id, format, content, speaker_map, created_at)
      VALUES (${meetingId}, 'vtt', ${vtt}, ${speakerMap}, NOW())
      ON CONFLICT (meeting_id) DO UPDATE SET
        content    = EXCLUDED.content,
        speaker_map = EXCLUDED.speaker_map
    `;
  }

  log.info('Transcript stored', { meetingId, size: vtt.length }, LOGGER);
}

/**
 * Downloads the first recording for an online meeting and persists the path + size.
 */
async function fetchAndStoreRecording(
  meetingId: number,
  organizerUserId: string,
  onlineMeetingId: string
): Promise<void> {
  const recordings = await listRecordings(organizerUserId, onlineMeetingId);

  if (recordings.length === 0) {
    log.info('No recordings available', { meetingId, onlineMeetingId }, LOGGER);
    return;
  }

  const { filePath, sizeBytes } = await downloadRecordingToDisk(
    organizerUserId,
    onlineMeetingId,
    recordings[0]!.id,
    meetingId
  );

  await sql`
    UPDATE meetings
    SET recording_path        = ${filePath},
        recording_size_bytes  = ${sizeBytes},
        updated_at            = NOW()
    WHERE id = ${meetingId}
  `;

  log.info('Recording stored', { meetingId, filePath, sizeBytes }, LOGGER);
}

// 🟢 WORKING: Microsoft Graph API recording download — streams MP4 to local disk
import { graphFetch } from './auth';
import { log } from '@/lib/logger';
import * as fs from 'fs';
import * as path from 'path';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

/** Metadata record for a single recording attached to an online meeting */
export interface RecordingMeta {
  id: string;
  createdDateTime: string;
  contentCorrelationId?: string;
}

/** Result of a successful recording download */
export interface RecordingDownloadResult {
  /** Absolute path to the saved MP4 file */
  filePath: string;
  /** File size in bytes */
  sizeBytes: number;
}

/**
 * Lists all recording metadata records for the given online meeting.
 * Returns an empty array if no recordings exist or the request fails.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param onlineMeetingId - Graph onlineMeeting ID
 */
export async function listRecordings(
  organizerUserId: string,
  onlineMeetingId: string
): Promise<RecordingMeta[]> {
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${onlineMeetingId}/recordings`;
  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'No recordings found',
      { onlineMeetingId, status: response.status },
      'GraphRecordings'
    );
    return [];
  }

  const data = await response.json();
  return (data.value as RecordingMeta[]) || [];
}

/**
 * Downloads a Teams meeting recording to the local filesystem as an MP4.
 * Files are organised under `$MEETING_RECORDINGS_PATH/YYYY/MM/<dbMeetingId>.mp4`.
 * The directory tree is created automatically if it does not exist.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param meetingId - Graph onlineMeeting ID
 * @param recordingId - ID of the specific recording to download
 * @param dbMeetingId - Primary key from the local `meetings` table (used as filename)
 * @returns Resolved file path and file size in bytes
 */
export async function downloadRecordingToDisk(
  organizerUserId: string,
  meetingId: string,
  recordingId: string,
  dbMeetingId: number
): Promise<RecordingDownloadResult> {
  const basePath =
    process.env.MEETING_RECORDINGS_PATH || '/home/velo/meeting-recordings';

  const now = new Date();
  const year = now.getFullYear().toString();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const dir = path.join(basePath, year, month);

  // Ensure target directory exists before writing
  fs.mkdirSync(dir, { recursive: true });

  const filePath = path.join(dir, `${dbMeetingId}.mp4`);

  const url = [
    `${GRAPH_BASE}/users/${organizerUserId}`,
    `/onlineMeetings/${meetingId}`,
    `/recordings/${recordingId}/content`,
  ].join('');

  const response = await graphFetch(url);

  if (!response.ok) {
    throw new Error(`Failed to download recording: ${response.status}`);
  }

  // Buffer the entire response in memory then write atomically
  const buffer = Buffer.from(await response.arrayBuffer());
  fs.writeFileSync(filePath, buffer);

  const sizeBytes = buffer.length;
  log.info(
    'Recording downloaded',
    { filePath, sizeBytes, dbMeetingId },
    'GraphRecordings'
  );

  return { filePath, sizeBytes };
}

// 🟢 WORKING: Microsoft Graph API call records — fetch and paginate callRecords
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

/** A participant endpoint (caller or callee) within a session or segment */
export interface CallEndpoint {
  user?: {
    id: string;
    displayName: string;
  };
}

/** A single segment within a call session */
export interface CallRecordSegment {
  startDateTime: string;
  endDateTime: string;
  caller: CallEndpoint;
  callee: CallEndpoint;
}

/** A session (one-to-one leg) within a call record */
export interface CallRecordSession {
  id: string;
  caller: CallEndpoint;
  callee: CallEndpoint;
  startDateTime: string;
  endDateTime: string;
  segments: CallRecordSegment[];
}

/** Top-level call record from Microsoft Graph callRecords API */
export interface CallRecord {
  id: string;
  type: string;
  startDateTime: string;
  endDateTime: string;
  joinWebUrl?: string;
  organizer?: CallEndpoint;
  participants?: CallEndpoint[];
  sessions?: CallRecordSession[];
}

/**
 * Fetches all call records created on or after the given date.
 * Follows @odata.nextLink pagination until all pages are consumed.
 *
 * @param since - Lower bound for startDateTime filter (inclusive)
 * @returns Flat array of CallRecord objects across all pages
 */
export async function fetchRecentCallRecords(since: Date): Promise<CallRecord[]> {
  const sinceISO = since.toISOString();
  // callRecords endpoint does not support $top or $orderby — only $filter
  let url = `${GRAPH_BASE}/communications/callRecords?$filter=startDateTime ge ${sinceISO}`;

  const records: CallRecord[] = [];

  while (url) {
    const response = await graphFetch(url);

    if (!response.ok) {
      const errorText = await response.text();
      log.error(
        'Failed to fetch call records',
        { status: response.status, error: errorText },
        'GraphCallRecords'
      );
      throw new Error(`Failed to fetch call records: ${response.status}`);
    }

    const data = await response.json();
    records.push(...((data.value as CallRecord[]) || []));

    // Graph OData pagination — empty string stops the loop
    url = (data['@odata.nextLink'] as string) || '';
  }

  log.info('Fetched call records', { count: records.length, since: sinceISO }, 'GraphCallRecords');
  return records;
}

/**
 * Fetches a single call record by ID, expanding sessions and their segments.
 * Use this to get full participant and timing details for a specific call.
 *
 * @param id - Graph callRecord ID (UUID format)
 */
export async function fetchCallRecordById(id: string): Promise<CallRecord> {
  const url = `${GRAPH_BASE}/communications/callRecords/${id}?$expand=sessions($expand=segments)`;
  const response = await graphFetch(url);

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Failed to fetch call record ${id}: ${response.status} ${errorText}`);
  }

  return response.json() as Promise<CallRecord>;
}

// 🟢 WORKING: Microsoft Graph API transcript fetch and VTT parser
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

/** Metadata record for a single transcript file attached to a meeting */
export interface TranscriptMeta {
  id: string;
  createdDateTime: string;
  contentCorrelationId?: string;
}

/** A single speaker utterance extracted from a VTT transcript */
export interface ParsedUtterance {
  /** Offset in milliseconds from the start of the recording */
  startMs: number;
  /** Speaker display name extracted from the VTT <v> tag */
  speaker: string;
  /** Spoken text with VTT markup stripped */
  text: string;
}

/** Result of resolving an online meeting from a join URL */
export interface OnlineMeetingInfo {
  id: string;
  subject: string | null;
}

/**
 * Resolves the Graph onlineMeeting ID and subject for a meeting identified by its join URL.
 * Returns null if the meeting cannot be found (e.g. organizer mismatch).
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param joinUrl - The joinWebUrl from the callRecord
 */
export async function fetchOnlineMeetingId(
  organizerUserId: string,
  joinUrl: string
): Promise<string | null> {
  const info = await fetchOnlineMeetingInfo(organizerUserId, joinUrl);
  return info?.id ?? null;
}

/**
 * Resolves the Graph onlineMeeting ID and subject for a meeting identified by its join URL.
 * Returns null if the meeting cannot be found (e.g. organizer mismatch).
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param joinUrl - The joinWebUrl from the callRecord
 */
export async function fetchOnlineMeetingInfo(
  organizerUserId: string,
  joinUrl: string
): Promise<OnlineMeetingInfo | null> {
  const encodedUrl = encodeURIComponent(joinUrl);
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings?$filter=joinWebUrl eq '${encodedUrl}'&$select=id,subject`;

  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'Failed to fetch online meeting',
      { organizerUserId, status: response.status },
      'GraphTranscripts'
    );
    return null;
  }

  const data = await response.json();
  const meeting = (data.value as Array<{ id: string; subject?: string }>)?.[0];
  if (!meeting) return null;

  return { id: meeting.id, subject: meeting.subject ?? null };
}

/**
 * Lists all transcript metadata records for the given online meeting.
 * Returns an empty array if no transcripts exist or the request fails.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param onlineMeetingId - Graph onlineMeeting ID (from fetchOnlineMeetingId)
 */
export async function listTranscripts(
  organizerUserId: string,
  onlineMeetingId: string
): Promise<TranscriptMeta[]> {
  const url = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${onlineMeetingId}/transcripts`;
  const response = await graphFetch(url);

  if (!response.ok) {
    log.warn(
      'No transcripts found',
      { onlineMeetingId, status: response.status },
      'GraphTranscripts'
    );
    return [];
  }

  const data = await response.json();
  return (data.value as TranscriptMeta[]) || [];
}

/**
 * Downloads the raw VTT content for a specific transcript.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param meetingId - Graph onlineMeeting ID
 * @param transcriptId - ID of the transcript to download
 * @returns Raw VTT string
 */
export async function downloadTranscriptContent(
  organizerUserId: string,
  meetingId: string,
  transcriptId: string
): Promise<string> {
  const url = [
    `${GRAPH_BASE}/users/${organizerUserId}`,
    `/onlineMeetings/${meetingId}`,
    `/transcripts/${transcriptId}/content?$format=text/vtt`,
  ].join('');

  const response = await graphFetch(url, {
    headers: { Accept: 'text/vtt' },
  });

  if (!response.ok) {
    throw new Error(`Failed to download transcript: ${response.status}`);
  }

  return response.text();
}

/**
 * Parses a VTT string into structured utterances with speaker attribution.
 * Handles the Teams-flavoured VTT dialect that uses <v SpeakerName> inline tags.
 *
 * @param vtt - Raw WebVTT content
 * @returns Ordered array of utterances sorted by startMs
 */
export function parseVttSpeakers(vtt: string): ParsedUtterance[] {
  const utterances: ParsedUtterance[] = [];

  // VTT cue blocks are separated by blank lines
  const blocks = vtt.split(/\n\n+/);

  for (const block of blocks) {
    const lines = block.trim().split('\n');

    // Locate the cue timing line (contains "-->")
    const tsLine = lines.find(l => l.includes('-->'));
    if (!tsLine) continue;

    // Parse HH:MM:SS.mmm from the start timestamp
    const startMatch = tsLine.match(/^(\d{2}):(\d{2}):(\d{2})\.(\d{3})/);
    if (!startMatch) continue;

    // startMatch[1..4] are guaranteed non-undefined because we checked `!startMatch` above
    const startMs =
      parseInt(startMatch[1]!, 10) * 3_600_000 +
      parseInt(startMatch[2]!, 10) * 60_000 +
      parseInt(startMatch[3]!, 10) * 1_000 +
      parseInt(startMatch[4]!, 10);

    // Text payload follows the timestamp line
    const tsIndex = lines.indexOf(tsLine);
    const textLines = lines.slice(tsIndex + 1);
    const fullText = textLines.join(' ').trim();

    // Teams VTT uses <v DisplayName>text</v> markup for speaker attribution
    const speakerMatch = fullText.match(/<v\s+([^>]+)>/);
    // speakerMatch[1] is non-undefined when speakerMatch is truthy (capture group 1 always present)
    const speaker = speakerMatch ? speakerMatch[1]! : 'Unknown';
    const text = fullText.replace(/<\/?v[^>]*>/g, '').trim();

    if (text) {
      utterances.push({ startMs, speaker, text });
    }
  }

  return utterances;
}

// 🟢 WORKING: Microsoft Graph webhook subscriptions — create, renew, and query expiring subs
import { graphFetch } from './auth';
import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const sql = neon(process.env.DATABASE_URL!);

/** Graph API subscription object returned on create/read */
export interface GraphSubscription {
  id: string;
  resource: string;
  changeType: string;
  notificationUrl: string;
  expirationDateTime: string;
  clientState?: string;
}

/** Row shape returned by getExpiringSubscriptions */
export interface ExpiringSubscription {
  subscriptionId: string;
  expiresAt: string;
}

/**
 * Creates a new Microsoft Graph webhook subscription for call records.
 * Persists the subscription metadata to the `graph_subscriptions` table.
 *
 * Call record subscriptions have a maximum lifetime of 3 days — callers should
 * schedule renewal via `renewSubscription` before expiry.
 *
 * @param notificationUrl - Public HTTPS URL that Graph will POST change notifications to
 * @returns The created GraphSubscription object
 */
export async function createWebhookSubscription(
  notificationUrl: string
): Promise<GraphSubscription> {
  const clientState = process.env.GRAPH_WEBHOOK_SECRET;
  if (!clientState) {
    throw new Error('GRAPH_WEBHOOK_SECRET required for webhook subscriptions');
  }

  // Graph enforces a maximum of 4230 minutes (~2.94 days) for callRecords subscriptions
  const expiresAt = new Date(Date.now() + 4200 * 60 * 1000);

  const body = {
    changeType: 'created',
    notificationUrl,
    resource: '/communications/callRecords',
    expirationDateTime: expiresAt.toISOString(),
    clientState,
  };

  const response = await graphFetch(`${GRAPH_BASE}/subscriptions`, {
    method: 'POST',
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Failed to create Graph subscription: ${response.status} ${errorText}`
    );
  }

  const sub = (await response.json()) as GraphSubscription;

  await sql`
    INSERT INTO graph_subscriptions
      (subscription_id, resource, change_type, notification_url, expires_at, client_state)
    VALUES
      (${sub.id}, ${sub.resource}, ${sub.changeType}, ${sub.notificationUrl},
       ${expiresAt.toISOString()}, ${clientState})
  `;

  log.info(
    'Graph webhook subscription created',
    { subscriptionId: sub.id, expiresAt: expiresAt.toISOString() },
    'GraphSubscriptions'
  );

  return sub;
}

/**
 * Extends an existing subscription by 3 more days.
 * Updates the `graph_subscriptions` table with the new expiry timestamp.
 *
 * @param subscriptionId - The Graph subscription ID to renew
 */
export async function renewSubscription(subscriptionId: string): Promise<void> {
  const expiresAt = new Date(Date.now() + 4200 * 60 * 1000);

  const response = await graphFetch(
    `${GRAPH_BASE}/subscriptions/${subscriptionId}`,
    {
      method: 'PATCH',
      body: JSON.stringify({ expirationDateTime: expiresAt.toISOString() }),
    }
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Failed to renew subscription ${subscriptionId}: ${response.status} ${errorText}`
    );
  }

  await sql`
    UPDATE graph_subscriptions
    SET expires_at  = ${expiresAt.toISOString()},
        renewed_at  = NOW()
    WHERE subscription_id = ${subscriptionId}
  `;

  log.info(
    'Subscription renewed',
    { subscriptionId, expiresAt: expiresAt.toISOString() },
    'GraphSubscriptions'
  );
}

/**
 * Returns all active subscriptions that expire within the next 12 hours.
 * Use this in a scheduled job to renew subscriptions before they lapse.
 */
export async function getExpiringSubscriptions(): Promise<ExpiringSubscription[]> {
  const rows = await sql`
    SELECT subscription_id, expires_at
    FROM graph_subscriptions
    WHERE status = 'active'
      AND expires_at < NOW() + INTERVAL '12 hours'
  `;

  return rows.map(r => ({
    subscriptionId: r.subscription_id as string,
    expiresAt: r.expires_at as string,
  }));
}

/**
 * Returns the count of active, non-expired subscriptions.
 * Used to detect when no webhook subscription exists and one needs to be bootstrapped.
 */
export async function getActiveSubscriptionCount(): Promise<number> {
  const rows = await sql`
    SELECT COUNT(*) as cnt
    FROM graph_subscriptions
    WHERE status = 'active'
      AND expires_at > NOW()
  `;

  return Number(rows[0]?.cnt ?? 0);
}

// 🟢 WORKING: Enable auto-recording on upcoming Teams meetings via Graph API
// Requires: Calendars.Read + OnlineMeetings.ReadWrite.All application permissions
// Also requires Teams Application Access Policy (PowerShell)
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const LOGGER = 'AutoRecording';

// Only scan calendars for users in these email domains
const INTERNAL_DOMAINS = ['velocityfibre.co.za', 'blitzfibre.com'];

/** Calendar event from Graph calendarView API */
interface CalendarEvent {
  id: string;
  subject: string;
  start: { dateTime: string; timeZone: string };
  end: { dateTime: string; timeZone: string };
  isOnlineMeeting: boolean;
  isCancelled?: boolean;
  onlineMeeting?: { joinUrl: string };
