/**
 * Downloads a Teams meeting recording to the local filesystem as an MP4.
 * Files are organised under `$MEETING_RECORDINGS_PATH/YYYY/MM/<dbMeetingId>.mp4`.
 * The directory tree is created automatically if it does not exist.
 *
 * @param organizerUserId - Graph user ID of the meeting organizer
 * @param meetingId - Graph onlineMeeting ID
 * @param recordingId - ID of the specific recording to download
 * @param dbMeetingId - Primary key from the local `meetings` table (used as filename)
 * @returns Resolved file path and file size in bytes
 */
export async function downloadRecordingToDisk(
  organizerUserId: string,
  meetingId: string,
  recordingId: string,
  dbMeetingId: number
): Promise<RecordingDownloadResult> {
  const basePath =
    process.env.MEETING_RECORDINGS_PATH || '/home/velo/meeting-recordings';

  const now = new Date();
  const year = now.getFullYear().toString();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const dir = path.join(basePath, year, month);

  // Ensure target directory exists before writing
  fs.mkdirSync(dir, { recursive: true });

  const filePath = path.join(dir, `${dbMeetingId}.mp4`);

  const url = [
    `${GRAPH_BASE}/users/${organizerUserId}`,
    `/onlineMeetings/${meetingId}`,
    `/recordings/${recordingId}/content`,
  ].join('');

  const response = await graphFetch(url);

  if (!response.ok) {
    throw new Error(`Failed to download recording: ${response.status}`);
  }

  // Buffer the entire response in memory then write atomically
  const buffer = Buffer.from(await response.arrayBuffer());
  fs.writeFileSync(filePath, buffer);

  const sizeBytes = buffer.length;
  log.info(
    'Recording downloaded',
    { filePath, sizeBytes, dbMeetingId },
    'GraphRecordings'
  );

  return { filePath, sizeBytes };
}

// 🟢 WORKING: Enable auto-recording on upcoming Teams meetings via Graph API
// Requires: Calendars.Read + OnlineMeetings.ReadWrite.All application permissions
// Also requires Teams Application Access Policy (PowerShell)
import { graphFetch } from './auth';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const LOGGER = 'AutoRecording';

// Only scan calendars for users in these email domains
const INTERNAL_DOMAINS = ['velocityfibre.co.za', 'blitzfibre.com'];

/** Calendar event from Graph calendarView API */
interface CalendarEvent {
  id: string;
  subject: string;
  start: { dateTime: string; timeZone: string };
  end: { dateTime: string; timeZone: string };
  isOnlineMeeting: boolean;
  isCancelled?: boolean;
  onlineMeeting?: { joinUrl: string };
  organizer?: { emailAddress: { address: string; name: string } };
}

/** Online meeting resource from Graph */
interface OnlineMeeting {
  id: string;
  subject: string;
  recordAutomatically: boolean;
}

/** Result of enabling auto-recording for a batch of meetings */
export interface AutoRecordingResult {
  usersChecked: number;
  meetingsFound: number;
  alreadyEnabled: number;
  newlyEnabled: number;
  failed: number;
  errors: string[];
  calendarAccessDenied?: boolean;
  meetingAccessDenied?: boolean;
}

/**
 * Fetches internal users in the tenant (VelocityFibre/BlitzFibre domains only).
 * Skips external/guest accounts (#EXT#) and service accounts.
 */
export async function getInternalUsers(): Promise<{ id: string; displayName: string; mail: string }[]> {
  const users: { id: string; displayName: string; mail: string }[] = [];
  let url = `${GRAPH_BASE}/users?$filter=accountEnabled eq true&$select=id,displayName,mail,userPrincipalName&$top=100`;

  while (url) {
    const response = await graphFetch(url);
    if (!response.ok) {
      const err = await response.text();
      log.error('Failed to fetch users', { status: response.status, error: err }, LOGGER);
      throw new Error(`Graph API /users failed: ${response.status} — ${err.slice(0, 200)}`);
    }

    const data = await response.json();
    const pageUsers = (data.value || [])
      .map((u: Record<string, string>) => ({
        id: u.id,
        displayName: u.displayName || '',
        mail: u.mail || u.userPrincipalName || '',
        upn: u.userPrincipalName || '',
      }))
      .filter((u: { mail: string; upn: string }) => {
        // Skip external/guest users
        if (u.upn.includes('#EXT#')) return false;
        // Only keep internal domain users
        const domain = u.mail.split('@')[1]?.toLowerCase();
        return domain && INTERNAL_DOMAINS.includes(domain);
      })
      .map((u: { id: string; displayName: string; mail: string }) => ({
        id: u.id,
        displayName: u.displayName,
        mail: u.mail,
      }));

    users.push(...pageUsers);
    url = data['@odata.nextLink'] || '';
  }

  return users;
}

/**
 * Fetches upcoming calendar events for a user within a time window.
 * Only returns Teams online meetings.
 *
 * @returns events array, or null if calendar access is denied (missing Calendars.Read)
 */
async function getUpcomingTeamsMeetings(
  userId: string,
  hoursAhead: number
): Promise<CalendarEvent[] | null> {
  const now = new Date();
  const end = new Date(now.getTime() + hoursAhead * 60 * 60 * 1000);

  // Note: isOnlineMeeting does not support $filter — filter client-side
  const url = `${GRAPH_BASE}/users/${userId}/calendarView` +
    `?startDateTime=${now.toISOString()}` +
    `&endDateTime=${end.toISOString()}` +
    `&$select=id,subject,start,end,isOnlineMeeting,isCancelled,onlineMeeting,organizer` +
    `&$top=50`;

  const response = await graphFetch(url);
  if (!response.ok) {
    const err = await response.text();
    // 403 = Access Denied — missing Calendars.Read permission
    if (response.status === 403) return null;
    // 404 = Mailbox not found (shared/inactive mailbox) — skip user
    if (response.status === 404) return [];
    log.warn('Failed to fetch calendar', { userId, status: response.status, error: err }, LOGGER);
    return [];
  }

  const data = await response.json();
  // Client-side filter: only active Teams online meetings with a join URL
  return ((data.value || []) as CalendarEvent[]).filter(
    e => e.isOnlineMeeting && e.onlineMeeting?.joinUrl && !e.isCancelled
  );
}

/**
 * Resolves a join URL to an online meeting ID, then PATCHes it to enable
 * auto-recording.
 *
 * @returns 'enabled' | 'already' | 'failed' | 'access_denied'
 */
async function enableAutoRecordForMeeting(
  organizerUserId: string,
  joinUrl: string,
  subject: string
): Promise<'enabled' | 'already' | 'failed' | 'access_denied'> {
  // encodeURIComponent the $filter value (NOT the $filter key — $ must stay literal)
  // Join URLs contain %3a etc. that corrupt query strings if embedded raw
  const filterValue = encodeURIComponent(`JoinWebUrl eq '${joinUrl}'`);
  const findUrl = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings?$filter=${filterValue}`;

  const findResp = await graphFetch(findUrl);
  if (findResp.status === 403) {
    log.warn('OnlineMeetings access denied — application access policy required', { subject }, LOGGER);
    return 'access_denied';
  }
  if (!findResp.ok) {
    const err = await findResp.text();
    log.warn('Cannot find online meeting', { subject, status: findResp.status, error: err.slice(0, 200) }, LOGGER);
    return 'failed';
  }

  const data = await findResp.json();
  const meetings = (data.value || []) as OnlineMeeting[];
  if (meetings.length === 0) {
    log.warn('Online meeting not found for join URL', { subject }, LOGGER);
    return 'failed';
  }

  return await patchMeeting(organizerUserId, meetings[0]!, subject);
}

async function patchMeeting(
  organizerUserId: string,
  meeting: OnlineMeeting,
  subject: string
): Promise<'enabled' | 'already' | 'access_denied'> {
  if (meeting.recordAutomatically) {
    return 'already';
  }

  const patchUrl = `${GRAPH_BASE}/users/${organizerUserId}/onlineMeetings/${meeting.id}`;
  const patchResp = await graphFetch(patchUrl, {
    method: 'PATCH',
    body: JSON.stringify({ recordAutomatically: true }),
  });

  if (patchResp.status === 403) {
    log.warn('PATCH denied — application access policy required', { subject, meetingId: meeting.id }, LOGGER);
    return 'access_denied';
  }

  if (!patchResp.ok) {
    const err = await patchResp.text();
    log.error('Failed to PATCH meeting', { subject, meetingId: meeting.id, error: err }, LOGGER);
    return 'already'; // Don't count as failed — unknown permission issue
  }

  log.info('Auto-recording enabled', { subject, meetingId: meeting.id }, LOGGER);
  return 'enabled';
}

/**
 * Main entry point: scans internal users' calendars for upcoming Teams meetings
 * and enables auto-recording on each one.
 *
 * @param hoursAhead - How far ahead to look for meetings (default: 24)
 */
export async function enableAutoRecordingForUpcomingMeetings(
  hoursAhead = 24
): Promise<AutoRecordingResult> {
  const result: AutoRecordingResult = {
    usersChecked: 0,
    meetingsFound: 0,
    alreadyEnabled: 0,
    newlyEnabled: 0,
    failed: 0,
    errors: [],
  };

  const users = await getInternalUsers();
  result.usersChecked = users.length;

  log.info('Auto-recording scan started', { users: users.length, hoursAhead }, LOGGER);

  // Fast-fail: check calendar access on first user
  if (users.length > 0) {
    const testEvents = await getUpcomingTeamsMeetings(users[0]!.id, hoursAhead);
    if (testEvents === null) {
      result.calendarAccessDenied = true;
      result.errors.push(
        'Calendar access denied (403). Add Calendars.Read application permission ' +
        'in Azure AD → API permissions → Grant admin consent.'
      );
      log.error('Calendar access denied — Calendars.Read permission missing', {}, LOGGER);
      return result;
    }
  }

  // Track meetings: seenUrls for counting, processedUrls for organizer-processed
  const seenUrls = new Set<string>();
  const processedUrls = new Set<string>();

  for (const user of users) {
    try {
      const events = await getUpcomingTeamsMeetings(user.id, hoursAhead);
      if (events === null) continue; // Skip users with no calendar access

      for (const event of events) {
        const joinUrl = event.onlineMeeting?.joinUrl;
        if (!joinUrl) continue;

        // Count each unique meeting once
        if (!seenUrls.has(joinUrl)) {
          seenUrls.add(joinUrl);
          result.meetingsFound++;
        }

        // Skip if already processed by the organizer
        if (processedUrls.has(joinUrl)) continue;

        // Only the organizer can modify meeting settings
        const isOrganizer = event.organizer?.emailAddress?.address?.toLowerCase() === user.mail?.toLowerCase();
        if (!isOrganizer) continue;

        processedUrls.add(joinUrl);

        try {
          const status = await enableAutoRecordForMeeting(user.id, joinUrl, event.subject);
          if (status === 'enabled') result.newlyEnabled++;
          else if (status === 'already') result.alreadyEnabled++;
          else if (status === 'access_denied') {
            result.meetingAccessDenied = true;
            result.failed++;
            result.errors.push(
              `${event.subject}: OnlineMeetings access denied. ` +
              'Create a Teams Application Access Policy via PowerShell.'
            );
            break;
          } else {
            result.failed++;
          }
        } catch (error: unknown) {
          result.failed++;
          const msg = error instanceof Error ? error.message : String(error);
          result.errors.push(`${event.subject}: ${msg}`);
        }
      }

      if (result.meetingAccessDenied) break;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      log.warn('Failed to scan user calendar', { user: user.mail, error: msg }, LOGGER);
    }
  }

  log.info('Auto-recording scan complete', result, LOGGER);
  return result;
}

// 🟢 WORKING: Microsoft Graph webhook subscriptions — create, renew, and query expiring subs
import { graphFetch } from './auth';
import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const sql = neon(process.env.DATABASE_URL!);

/** Graph API subscription object returned on create/read */
export interface GraphSubscription {
  id: string;
  resource: string;
  changeType: string;
  notificationUrl: string;
  expirationDateTime: string;
  clientState?: string;
}

/** Row shape returned by getExpiringSubscriptions */
export interface ExpiringSubscription {
  subscriptionId: string;
  expiresAt: string;
}

/**
 * Creates a new Microsoft Graph webhook subscription for call records.
 * Persists the subscription metadata to the `graph_subscriptions` table.
 *
 * Call record subscriptions have a maximum lifetime of 3 days — callers should
 * schedule renewal via `renewSubscription` before expiry.
 *
 * @param notificationUrl - Public HTTPS URL that Graph will POST change notifications to
 * @returns The created GraphSubscription object
 */
export async function createWebhookSubscription(
  notificationUrl: string
): Promise<GraphSubscription> {
  const clientState = process.env.GRAPH_WEBHOOK_SECRET;
  if (!clientState) {
    throw new Error('GRAPH_WEBHOOK_SECRET required for webhook subscriptions');
  }

  // Graph enforces a maximum of 4230 minutes (~2.94 days) for callRecords subscriptions
  const expiresAt = new Date(Date.now() + 4200 * 60 * 1000);

  const body = {
    changeType: 'created',
    notificationUrl,
    resource: '/communications/callRecords',
    expirationDateTime: expiresAt.toISOString(),
    clientState,
  };

  const response = await graphFetch(`${GRAPH_BASE}/subscriptions`, {
    method: 'POST',
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Failed to create Graph subscription: ${response.status} ${errorText}`
    );
  }

  const sub = (await response.json()) as GraphSubscription;

  await sql`
    INSERT INTO graph_subscriptions
      (subscription_id, resource, change_type, notification_url, expires_at, client_state)
    VALUES
      (${sub.id}, ${sub.resource}, ${sub.changeType}, ${sub.notificationUrl},
       ${expiresAt.toISOString()}, ${clientState})
  `;

  log.info(
    'Graph webhook subscription created',
    { subscriptionId: sub.id, expiresAt: expiresAt.toISOString() },
    'GraphSubscriptions'
  );

  return sub;
}

/**
 * Extends an existing subscription by 3 more days.
 * Updates the `graph_subscriptions` table with the new expiry timestamp.
 *
 * @param subscriptionId - The Graph subscription ID to renew
 */
export async function renewSubscription(subscriptionId: string): Promise<void> {
  const expiresAt = new Date(Date.now() + 4200 * 60 * 1000);

  const response = await graphFetch(
    `${GRAPH_BASE}/subscriptions/${subscriptionId}`,
    {
      method: 'PATCH',
      body: JSON.stringify({ expirationDateTime: expiresAt.toISOString() }),
    }
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Failed to renew subscription ${subscriptionId}: ${response.status} ${errorText}`
    );
  }

  await sql`
    UPDATE graph_subscriptions
    SET expires_at  = ${expiresAt.toISOString()},
        renewed_at  = NOW()
    WHERE subscription_id = ${subscriptionId}
  `;

  log.info(
    'Subscription renewed',
    { subscriptionId, expiresAt: expiresAt.toISOString() },
    'GraphSubscriptions'
  );
}

/**
 * Returns all active subscriptions that expire within the next 12 hours.
 * Use this in a scheduled job to renew subscriptions before they lapse.
 */
export async function getExpiringSubscriptions(): Promise<ExpiringSubscription[]> {
  const rows = await sql`
    SELECT subscription_id, expires_at
    FROM graph_subscriptions
    WHERE status = 'active'
      AND expires_at < NOW() + INTERVAL '12 hours'
  `;

  return rows.map(r => ({
    subscriptionId: r.subscription_id as string,
    expiresAt: r.expires_at as string,
  }));
}

/**
 * Returns the count of active, non-expired subscriptions.
 * Used to detect when no webhook subscription exists and one needs to be bootstrapped.
 */
export async function getActiveSubscriptionCount(): Promise<number> {
  const rows = await sql`
    SELECT COUNT(*) as cnt
    FROM graph_subscriptions
    WHERE status = 'active'
      AND expires_at > NOW()
  `;

  return Number(rows[0]?.cnt ?? 0);
}

// 🟢 WORKING: Scrape Teams meeting recordings from users' OneDrive /Recordings/ folders
import { graphFetch } from './auth';
import { log } from '@/lib/logger';
import { getInternalUsers } from './auto-recording';
import { processWithLLM } from '@/lib/llm/meeting-processor';
import * as fs from 'fs';
import * as path from 'path';

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const LOGGER = 'OneDriveRecordings';

const RECORDINGS_BASE =
  process.env.MEETING_RECORDINGS_PATH || '/home/velo/meeting-recordings';

/** OneDrive driveItem representing a recording file */
interface DriveItem {
  id: string;
  name: string;
  size: number;
  createdDateTime: string;
  lastModifiedDateTime: string;
  createdBy?: {
    user?: { id?: string; displayName?: string; email?: string };
  };
  '@microsoft.graph.downloadUrl'?: string;
}

/** Result of a single scrape run */
export interface OneDriveScrapeResult {
  usersScanned: number;
  recordingsFound: number;
  newDownloads: number;
  alreadyProcessed: number;
  matched: number;
  created: number;
  enriched: number;
  failed: number;
  errors: string[];
}

/**
 * Lists all .mp4 files in a user's OneDrive /Recordings/ folder.
 * Returns empty array if folder doesn't exist or access is denied.
 */
async function listUserRecordings(userId: string): Promise<DriveItem[]> {
  const url =
    `${GRAPH_BASE}/users/${userId}/drive/root:/Recordings:/children` +
    `?$select=id,name,size,createdDateTime,lastModifiedDateTime,createdBy` +
    `&$top=200&$orderby=createdDateTime desc`;

  const response = await graphFetch(url);

  if (response.status === 404) return []; // No Recordings folder
  if (response.status === 403) {
    log.warn('OneDrive access denied', { userId }, LOGGER);
    return [];
  }
  if (!response.ok) {
    log.warn('OneDrive listing failed', { userId, status: response.status }, LOGGER);
    return [];
  }

  const data = await response.json();
  const items = (data.value || []) as DriveItem[];

  // Only MP4 files (Teams recordings)
  return items.filter(
    (item) => item.name.toLowerCase().endsWith('.mp4') && item.size > 0
  );
}

/**
 * Downloads a file from OneDrive to local disk.
 * Uses the @microsoft.graph.downloadUrl for direct download (no auth needed on that URL).
 * Falls back to /content endpoint if download URL is not present.
 */
async function downloadDriveItem(
  userId: string,
  itemId: string,
  destPath: string
): Promise<number> {
  // Get the item with download URL
  const metaUrl = `${GRAPH_BASE}/users/${userId}/drive/items/${itemId}?$select=id,@microsoft.graph.downloadUrl`;
  const metaResp = await graphFetch(metaUrl);

  if (!metaResp.ok) {
    throw new Error(`Failed to get download URL: ${metaResp.status}`);
  }

  const meta = await metaResp.json();
  const downloadUrl =
    meta['@microsoft.graph.downloadUrl'] ||
    `${GRAPH_BASE}/users/${userId}/drive/items/${itemId}/content`;

  // Download — use direct URL if available (faster, no auth needed)
  const isDirectUrl = !!meta['@microsoft.graph.downloadUrl'];
  const response = isDirectUrl
    ? await fetch(downloadUrl)
    : await graphFetch(downloadUrl);

  if (!response.ok) {
    throw new Error(`Download failed: ${response.status}`);
  }

  const buffer = Buffer.from(await response.arrayBuffer());
  const dir = path.dirname(destPath);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(destPath, buffer);

  return buffer.length;
}

/**
 * Parse a Teams recording filename to extract title and approximate date.
 * Format: "Meeting Title-YYYYMMDD_HHMMSS-Meeting Recording.mp4"
 * Also handles: "Meeting Title (YYYY-MM-DD HH_MM_SS).mp4"
 */
function parseRecordingFilename(name: string): { title: string; date: Date | null } {
  // Pattern 1: "Title-20260313_100000-Meeting Recording.mp4"
  const m1 = name.match(/^(.+?)-(\d{8})_(\d{6})-Meeting Recording\.mp4$/i);
  if (m1) {
    const title = m1[1]!.trim();
    const ds = m1[2]!;
    const ts = m1[3]!;
    const date = new Date(
      `${ds.slice(0, 4)}-${ds.slice(4, 6)}-${ds.slice(6, 8)}T${ts.slice(0, 2)}:${ts.slice(2, 4)}:${ts.slice(4, 6)}Z`
    );
    return { title, date: isNaN(date.getTime()) ? null : date };
  }

  // Pattern 2: fallback — just use filename without extension
  const title = name.replace(/\.mp4$/i, '').replace(/-Meeting Recording$/i, '').trim();
  return { title, date: null };
}

/**
 * Main entry point: scans all internal users' OneDrive Recordings folders,
 * downloads new recordings, matches to existing meetings or creates new ones,
 * and triggers LLM enrichment.
 */
export async function scrapeOneDriveRecordings(
  sql: ReturnType<typeof import('@neondatabase/serverless').neon>,
  options: { lookbackDays?: number; limit?: number } = {}
): Promise<OneDriveScrapeResult> {
  const { lookbackDays = 30, limit = 50 } = options;
  const cutoff = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);

  const result: OneDriveScrapeResult = {
    usersScanned: 0,
    recordingsFound: 0,
    newDownloads: 0,
    alreadyProcessed: 0,
    matched: 0,
    created: 0,
    enriched: 0,
    failed: 0,
    errors: [],
  };

  const users = await getInternalUsers();
  result.usersScanned = users.length;
  log.info('OneDrive scrape started', { users: users.length, lookbackDays, limit }, LOGGER);

  let totalProcessed = 0;

  for (const user of users) {
    if (totalProcessed >= limit) break;

    try {
      const recordings = await listUserRecordings(user.id);
      if (recordings.length === 0) continue;

      log.info('User recordings found', { user: user.mail, count: recordings.length }, LOGGER);

      for (const item of recordings) {
        if (totalProcessed >= limit) break;

        // Skip old recordings
        const itemDate = new Date(item.createdDateTime);
        if (itemDate < cutoff) continue;

        result.recordingsFound++;

        // Check if already scraped
        const existing = await sql`
          SELECT id FROM meetings WHERE onedrive_item_id = ${item.id}
        `;
        if (existing.length > 0) {
          result.alreadyProcessed++;
          continue;
        }

        try {
          const parsed = parseRecordingFilename(item.name);
          const recordingDate = parsed.date || itemDate;

          // Try to match to existing meeting by date (± 2 hours) that lacks a recording
          const windowMs = 2 * 60 * 60 * 1000;
          const dateStart = new Date(recordingDate.getTime() - windowMs).toISOString();
          const dateEnd = new Date(recordingDate.getTime() + windowMs).toISOString();

          const matchRows = await sql`
            SELECT id, title, recording_path
            FROM meetings
            WHERE source = 'teams'
              AND meeting_date >= ${dateStart}
              AND meeting_date <= ${dateEnd}
              AND recording_path IS NULL
              AND onedrive_item_id IS NULL
            ORDER BY ABS(EXTRACT(EPOCH FROM (meeting_date - ${recordingDate.toISOString()}::timestamptz)))
            LIMIT 1
          `;

          let meetingId: number;

          if (matchRows.length > 0) {
            // Match to existing meeting
            meetingId = matchRows[0]!.id as number;
            result.matched++;
            log.info('Matched to existing meeting', {
              meetingId,
              title: matchRows[0]!.title,
              recording: item.name,
            }, LOGGER);
          } else {
            // Create new meeting entry
            const title = parsed.title || `Teams Recording - ${recordingDate.toLocaleDateString('en-ZA')}`;
            const newRows = await sql`
              INSERT INTO meetings (
                title, meeting_date, source, onedrive_item_id,
                organizer_email, organizer_name,
                processing_status, created_at, updated_at
              ) VALUES (
                ${title}, ${recordingDate.toISOString()}, 'teams', ${item.id},
                ${user.mail}, ${user.displayName},
                'fetching', NOW(), NOW()
              )
              RETURNING id
            `;
            meetingId = newRows[0]!.id as number;
            result.created++;
            log.info('Created meeting from OneDrive recording', {
              meetingId, title, recording: item.name,
            }, LOGGER);
          }

          // Download recording to disk
          const year = recordingDate.getFullYear().toString();
          const month = String(recordingDate.getMonth() + 1).padStart(2, '0');
          const filePath = path.join(RECORDINGS_BASE, year, month, `${meetingId}.mp4`);

          if (!fs.existsSync(filePath)) {
            const sizeBytes = await downloadDriveItem(user.id, item.id, filePath);
            await sql`
              UPDATE meetings
              SET recording_path = ${filePath},
                  recording_size_bytes = ${sizeBytes},
                  onedrive_item_id = ${item.id},
                  updated_at = NOW()
              WHERE id = ${meetingId}
            `;
            result.newDownloads++;
            log.info('Recording downloaded', {
              meetingId, filePath, sizeMB: (sizeBytes / 1024 / 1024).toFixed(1),
            }, LOGGER);
          } else {
            // File already on disk, just update the tracking
            const stats = fs.statSync(filePath);
            await sql`
              UPDATE meetings
              SET recording_path = ${filePath},
                  recording_size_bytes = ${stats.size},
                  onedrive_item_id = ${item.id},
                  updated_at = NOW()
              WHERE id = ${meetingId}
            `;
          }

          // Run LLM enrichment if not already done
          const meetingRow = await sql`
            SELECT processing_status FROM meetings WHERE id = ${meetingId}
          `;
          if (meetingRow[0]?.processing_status !== 'completed') {
            try {
              await sql`UPDATE meetings SET processing_status = 'processing', updated_at = NOW() WHERE id = ${meetingId}`;
              await processWithLLM(meetingId);
              await sql`UPDATE meetings SET processing_status = 'completed', processed_at = NOW(), updated_at = NOW() WHERE id = ${meetingId}`;
              result.enriched++;
            } catch (llmErr: unknown) {
              const msg = llmErr instanceof Error ? llmErr.message : String(llmErr);
              log.warn('LLM enrichment failed', { meetingId, error: msg }, LOGGER);
              await sql`UPDATE meetings SET processing_status = 'failed', processing_error = ${msg}, updated_at = NOW() WHERE id = ${meetingId}`;
            }
          }

          totalProcessed++;
        } catch (itemErr: unknown) {
          result.failed++;
          const msg = itemErr instanceof Error ? itemErr.message : String(itemErr);
          result.errors.push(`${item.name}: ${msg}`);
          log.error('Failed to process recording', { item: item.name, error: msg }, LOGGER);
        }
      }
    } catch (userErr: unknown) {
      const msg = userErr instanceof Error ? userErr.message : String(userErr);
      log.warn('Failed to scan user OneDrive', { user: user.mail, error: msg }, LOGGER);
    }
  }

  log.info('OneDrive scrape complete', result, LOGGER);
  return result;
}

#!/usr/bin/env node
/**
 * Backfill Teams Meeting Transcripts & Recordings
 *
 * Finds all Teams meetings that have a join_url but no raw_transcript,
 * and re-attempts transcript/recording fetch. Unlike the original processor,
 * this tries EVERY participant in the tenant (not just the organizer) when
 * looking up the onlineMeeting via Graph API.
 *
 * Usage:
 *   npx tsx scripts/backfill-teams-transcripts.ts [--dry-run] [--limit N]
 */

import { neon } from '@neondatabase/serverless';
import { getGraphAccessToken } from '../src/lib/graph/auth';
import { fetchOnlineMeetingId, listTranscripts, downloadTranscriptContent, parseVttSpeakers } from '../src/lib/graph/transcripts';
import { listRecordings, downloadRecordingToDisk } from '../src/lib/graph/recordings';
import { processWithLLM } from '../src/lib/llm/meeting-processor';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('DATABASE_URL not set');
  process.exit(1);
}

const sql = neon(DATABASE_URL);

const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const TRANSCRIPT_INLINE_LIMIT = 500_000;

const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const limitIdx = args.indexOf('--limit');
const limit = limitIdx >= 0 ? parseInt(args[limitIdx + 1] || '10', 10) : 999;

interface MeetingRow {
  id: number;
  title: string;
  meeting_date: string;
  join_url: string;
  organizer_email: string | null;
  teams_call_record_id: string;
  participants: string;
}

interface Participant {
  name: string;
  email: string;
  displayName: string;
}

/**
 * Resolve a tenant email to a Graph user ID.
 * Uses the /users/{email} endpoint.
 */
async function resolveGraphUserId(email: string): Promise<string | null> {
  const token = await getGraphAccessToken();
  const response = await fetch(
    `${GRAPH_BASE}/users/${encodeURIComponent(email)}?$select=id`,
    { headers: { Authorization: `Bearer ${token}` } }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return (data.id as string) || null;
}

/**
 * Try each participant to find the onlineMeeting and fetch transcript/recording.
 * Returns true if transcript was found and stored.
 */
async function tryFetchTranscriptAndRecording(
  meeting: MeetingRow,
  participants: Participant[]
): Promise<{ transcriptStored: boolean; recordingStored: boolean }> {
  // Collect all tenant emails to try (organizer first, then others)
  const emailsToTry: string[] = [];

  if (meeting.organizer_email) {
    emailsToTry.push(meeting.organizer_email);
  }

  for (const p of participants) {
    if (p.email && !emailsToTry.includes(p.email)) {
      emailsToTry.push(p.email);
    }
  }

  // Only try velocityfibre.co.za and blitzfibre.com emails (in our tenant)
  const tenantEmails = emailsToTry.filter(
    e => e.endsWith('@velocityfibre.co.za') || e.endsWith('@blitzfibre.com')
  );

  if (tenantEmails.length === 0) {
    console.log(`  [SKIP] No tenant emails found for meeting ${meeting.id}`);
    return { transcriptStored: false, recordingStored: false };
  }

  let transcriptStored = false;
  let recordingStored = false;

  for (const email of tenantEmails) {
    const userId = await resolveGraphUserId(email);
    if (!userId) {
      console.log(`  [SKIP] Could not resolve Graph user for ${email}`);
      continue;
    }

    const onlineMeetingId = await fetchOnlineMeetingId(userId, meeting.join_url);
    if (!onlineMeetingId) {
      continue;
    }

    console.log(`  [FOUND] onlineMeeting via ${email} (userId: ${userId.substring(0, 8)}...)`);

    // Fetch transcript
    if (!transcriptStored) {
      const transcripts = await listTranscripts(userId, onlineMeetingId);
      if (transcripts.length > 0) {
        const vtt = await downloadTranscriptContent(userId, onlineMeetingId, transcripts[0]!.id);
        console.log(`  [TRANSCRIPT] ${vtt.length} bytes`);

        if (!dryRun) {
          if (vtt.length <= TRANSCRIPT_INLINE_LIMIT) {
            await sql`UPDATE meetings SET raw_transcript = ${vtt}, updated_at = NOW() WHERE id = ${meeting.id}`;
          } else {
            const speakerMap = JSON.stringify(parseVttSpeakers(vtt).slice(0, 50));
            await sql`
              INSERT INTO meeting_transcripts (meeting_id, format, content, speaker_map, created_at)
              VALUES (${meeting.id}, 'vtt', ${vtt}, ${speakerMap}, NOW())
              ON CONFLICT (meeting_id) DO UPDATE SET content = EXCLUDED.content, speaker_map = EXCLUDED.speaker_map
            `;
          }
          transcriptStored = true;
        } else {
          transcriptStored = true;
        }
      } else {
        console.log(`  [NO TRANSCRIPT] No transcripts available via ${email}`);
      }
    }

    // Fetch recording
    if (!recordingStored) {
      const recordings = await listRecordings(userId, onlineMeetingId);
      if (recordings.length > 0) {
        console.log(`  [RECORDING] Found ${recordings.length} recording(s)`);
        if (!dryRun) {
          try {
            const { filePath, sizeBytes } = await downloadRecordingToDisk(
              userId, onlineMeetingId, recordings[0]!.id, meeting.id
            );
            await sql`
              UPDATE meetings
              SET recording_path = ${filePath}, recording_size_bytes = ${sizeBytes}, updated_at = NOW()
              WHERE id = ${meeting.id}
            `;
            recordingStored = true;
            console.log(`  [RECORDING] Saved ${sizeBytes} bytes to ${filePath}`);
          } catch (err: unknown) {
            console.error(`  [RECORDING ERROR] ${err instanceof Error ? err.message : String(err)}`);
          }
        } else {
          recordingStored = true;
        }
      }
    }

    // If we found transcript or recording, no need to try more participants
    if (transcriptStored || recordingStored) break;
  }

  return { transcriptStored, recordingStored };
}

async function main() {
  console.log(`\nTeams Transcript Backfill ${dryRun ? '(DRY RUN)' : ''}`);
  console.log(`Limit: ${limit} meetings\n`);

  // Verify Graph auth works
  try {
    await getGraphAccessToken();
    console.log('Graph API auth: OK\n');
  } catch (err: unknown) {
    console.error('Graph API auth failed:', err instanceof Error ? err.message : String(err));
    process.exit(1);
  }

  // Find meetings to backfill
  const meetings = await sql`
    SELECT id, title, meeting_date::text, join_url, organizer_email,
           teams_call_record_id, participants::text
    FROM meetings
    WHERE source = 'teams'
      AND join_url IS NOT NULL
      AND raw_transcript IS NULL
      AND NOT EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)
    ORDER BY meeting_date DESC
    LIMIT ${limit}
  ` as MeetingRow[];

  console.log(`Found ${meetings.length} meetings to process\n`);

  let transcriptsFound = 0;
  let recordingsFound = 0;
  let noTranscriptAvailable = 0;
  let errors = 0;

  for (let i = 0; i < meetings.length; i++) {
    const m = meetings[i]!;
    const participants: Participant[] = JSON.parse(m.participants || '[]');
    console.log(`[${i + 1}/${meetings.length}] Meeting ${m.id}: ${m.title} (${m.meeting_date})`);

    try {
      const result = await tryFetchTranscriptAndRecording(m, participants);
      if (result.transcriptStored) transcriptsFound++;
      if (result.recordingStored) recordingsFound++;
      if (!result.transcriptStored && !result.recordingStored) noTranscriptAvailable++;
    } catch (err: unknown) {
      errors++;
      console.error(`  [ERROR] ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  console.log(`\n${'='.repeat(50)}`);
  console.log(`Results:`);
  console.log(`  Processed:    ${meetings.length}`);
  console.log(`  Transcripts:  ${transcriptsFound}`);
  console.log(`  Recordings:   ${recordingsFound}`);
  console.log(`  No data:      ${noTranscriptAvailable}`);
  console.log(`  Errors:       ${errors}`);
  console.log(`${'='.repeat(50)}`);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

/**
 * Probe how many Teams meetings with joinUrl can be resolved to an onlineMeeting.
 * Tests a sample to estimate yield before running the full reprocess.
 */
import { neon } from '@neondatabase/serverless';
import { fetchOnlineMeetingInfo } from '../src/lib/graph/transcripts';
import { listTranscripts, listRecordings } from '../src/lib/graph/transcripts';
import { graphFetch } from '../src/lib/graph/auth';

const sql = neon(process.env.DATABASE_URL || '');

async function main() {
  const meetings = await sql`
    SELECT id, join_url, organizer_email, title, meeting_date, duration
    FROM meetings
    WHERE source = 'teams' AND join_url IS NOT NULL
      AND raw_transcript IS NULL
      AND NOT EXISTS (SELECT 1 FROM meeting_transcripts mt WHERE mt.meeting_id = meetings.id)
    ORDER BY meeting_date DESC
  `;

  console.log(`Total meetings to check: ${meetings.length}`);

  // Resolve organizer user IDs
  const orgEmails = [...new Set(meetings.map((m: any) => m.organizer_email).filter(Boolean))] as string[];
  const userMap = new Map<string, string>();
  for (const email of orgEmails) {
    try {
      const resp = await graphFetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(email)}?$select=id`);
      if (resp.ok) userMap.set(email.toLowerCase(), (await resp.json()).id);
    } catch { /* skip */ }
  }
  console.log(`Resolved ${userMap.size} organizer user IDs out of ${orgEmails.length} unique emails`);

  let found = 0;
  let notFound = 0;
  let noUserId = 0;
  let hasTranscript = 0;
  let hasRecording = 0;

  for (const m of meetings) {
    const email = (m.organizer_email as string)?.toLowerCase();
    const userId = email ? userMap.get(email) : null;
    if (!userId) { noUserId++; continue; }

    const info = await fetchOnlineMeetingInfo(userId, m.join_url as string);
    if (info?.id) {
      found++;
      const transcripts = await listTranscripts(userId, info.id);
      const recordings = await listRecordings(userId, info.id);
      if (transcripts.length > 0) hasTranscript++;
      if (recordings.length > 0) hasRecording++;
      console.log(`  FOUND ${m.id} ${(m.meeting_date as string)?.toString().slice(0, 10)} ${m.duration}min — "${info.subject}" T:${transcripts.length} R:${recordings.length}`);
    } else {
      notFound++;
    }
  }

  console.log(`\nResults:`);
  console.log(`  Resolvable online meetings: ${found}`);
  console.log(`  With transcripts: ${hasTranscript}`);
  console.log(`  With recordings: ${hasRecording}`);
  console.log(`  Not resolvable (Meet Now / chat calls): ${notFound}`);
  console.log(`  No organizer user ID: ${noUserId}`);
}

main().catch(e => { console.error(e); process.exit(1); });

// 🟢 WORKING: Cron — enables auto-recording on upcoming Teams meetings
// Scans org calendars for the next 24h and PATCHes meetings to record automatically
// Schedule: every 30 minutes via system cron
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { enableAutoRecordingForUpcomingMeetings } from '@/lib/graph/auto-recording';

const LOGGER = 'AutoRecordCron';

/**
 * POST /api/cron/enable-auto-recording
 *
 * Scans all org users' upcoming Teams meetings (next 24h) and enables
 * auto-recording via Graph API PATCH.
 *
 * Auth: CRON_SECRET bearer token.
 * Schedule: every 30 minutes via system cron.
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/enable-auto-recording \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const hoursAhead = typeof req.body?.hours === 'number' ? req.body.hours : 24;
    const result = await enableAutoRecordingForUpcomingMeetings(hoursAhead);

    log.info('Auto-recording cron complete', result, LOGGER);

    res.status(200).json({ success: true, ...result });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Auto-recording cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

