/**
 * QField Ingestion Service for Construction QA
 *
 * Reads from qfield_photo_validations and creates:
 *   - construction_qa_reviews (one per feature)
 *   - construction_qa_photos (one per photo)
 *   - construction_qa_activity log entries
 *
 * Maps work_type to discipline:
 *   pole_installation → civil (feature_type: pole)
 *   cable_stringing   → optical (feature_type: cable_span)
 *   dome_joint        → optical (feature_type: joint)
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { parseQFieldCaptureDate } from '@/lib/exifUtils';
import { copyQFieldPhotoToStorage } from '@/services/qaPhotoStorageService';
import type { Discipline, FeatureType } from '../types';

const sql = neon(process.env.DATABASE_URL!);

const MODULE = 'construction-qa-ingest';

/** Map QField work_type to construction QA discipline + feature_type */
const WORK_TYPE_MAP: Record<string, { discipline: Discipline; featureType: FeatureType }> = {
  pole_installation: { discipline: 'civil', featureType: 'pole' },
  cable_stringing: { discipline: 'optical', featureType: 'cable_span' },
  dome_joint: { discipline: 'optical', featureType: 'joint' },
  activation: { discipline: 'civil', featureType: 'pole' }, // default — overridden per-row below
};

/** Map feature_type string to discipline (used for activation rows with mixed types) */
const FEATURE_TYPE_DISCIPLINE: Record<string, { discipline: Discipline; featureType: FeatureType }> = {
  pole: { discipline: 'civil', featureType: 'pole' },
  cable_span: { discipline: 'optical', featureType: 'cable_span' },
  joint: { discipline: 'optical', featureType: 'joint' },
};

/**
 * QFieldCloud project UUID → FibreFlow project UUID mapping.
 * QFieldCloud uses its own project UUIDs which differ from FibreFlow's.
 */
const QFIELD_TO_FIBREFLOW: Record<string, string> = {
  // Original Pole Audit projects
  '07b7109f-479b-4a7b-b33c-13e2af0c6bd3': '4eb13426-b2a1-472d-9b3c-277082ae9b55', // LAW Pole Audit → Lawley
  '137eb5ec-4c0b-4eab-8a5c-de046eb06349': 'bf9a90db-e758-4c05-b999-694cd63c451f', // MOA Pole Audit → Mohadin
  '04900ce2-1f2e-45bf-b3c8-8c78bc6540db': 'c7255076-1d2f-41ce-97bb-858b8c87ee27', // ETW Pole Audit → Etwatwa
  'c1e14ea2-489c-4376-a59a-1253df404dde': '7003dc06-9af7-4a7c-bc6c-a177d77784f2', // MAM Pole Audit → Mamelodi
  // Site Audit 2026 projects
  '2e988631-462b-448f-ae15-bb693a68cd55': '4eb13426-b2a1-472d-9b3c-277082ae9b55', // LAW Site Audit 2026 → Lawley
  '2ce80264-170c-4f05-ada1-68220d7e5885': '7003dc06-9af7-4a7c-bc6c-a177d77784f2', // MAM1 Site Audit 2026 → Mamelodi
  'bec5f353-2e83-4f6b-989a-fca83ad94e16': 'bf9a90db-e758-4c05-b999-694cd63c451f', // MOA Site Audit 2026 → Mohadin
  '63341eb4-bc81-4607-a3d6-580ea2a7457c': '7d8b94d6-8e5a-4dbb-9ede-69ce3884e004', // THM1 Site Audit 2026 → Thembisa POP 1
  '5f3b962a-7901-43f7-a284-1c1a9ed7f3d1': '1de088dd-fe24-43fb-b8d3-94fca61ef91d', // THM3 Site Audit 2026 → Thembisa POP 3
  '47585401-1b25-4d3b-8d18-4337ea26df88': 'c7255076-1d2f-41ce-97bb-858b8c87ee27', // ETW POP 2 Site Audit 2026 → Etwatwa
  // Additional projects
  '47eb39f5-d6a8-4ce7-9421-9133872c1951': '7003dc06-9af7-4a7c-bc6c-a177d77784f2', // MAM Pole Audit (offline) → Mamelodi
  '380147aa-0c25-4b09-a745-2480addd8cca': 'c7255076-1d2f-41ce-97bb-858b8c87ee27', // ETWpoc1 → Etwatwa
  '7fe59cdc-b1d5-475d-8448-5cf2e9f7175b': 'ce3bf310-d6ba-4ede-ab36-a8c902a5efc6', // Tonga Site Audit 2026 → Tonga
};

/** Reverse map: FibreFlow project UUID → QFieldCloud project UUIDs */
const FIBREFLOW_TO_QFIELD: Record<string, string[]> = {};
for (const [qfId, ffId] of Object.entries(QFIELD_TO_FIBREFLOW)) {
  if (!FIBREFLOW_TO_QFIELD[ffId]) FIBREFLOW_TO_QFIELD[ffId] = [];
  FIBREFLOW_TO_QFIELD[ffId].push(qfId);
}

interface IngestOptions {
  projectId: string;
  discipline?: Discipline | 'all';
  sinceDate?: string;
  dryRun?: boolean;
}

interface IngestResult {
  projectId: string;
  projectName?: string;
  photosFound: number;
  photosIngested: number;
  reviewsCreated: number;
  reviewsUpdated: number;
  errors: string[];
}

interface IngestAllResult {
  projects: IngestResult[];
  totalPhotosIngested: number;
  totalReviewsCreated: number;
  totalReviewsUpdated: number;
  totalErrors: number;
}

/**
 * Ingest QField photos for ALL mapped projects.
 */
export async function ingestAllQFieldPhotos(opts: { dryRun?: boolean; discipline?: Discipline | 'all' }): Promise<IngestAllResult> {
  const ffProjectIds = Object.values(QFIELD_TO_FIBREFLOW);
  const unique = [...new Set(ffProjectIds)];

  const results: IngestResult[] = [];
  for (const projectId of unique) {
    const r = await ingestQFieldPhotos({ projectId, discipline: opts.discipline, dryRun: opts.dryRun });
    results.push(r);
  }

  return {
    projects: results,
    totalPhotosIngested: results.reduce((s, r) => s + r.photosIngested, 0),
    totalReviewsCreated: results.reduce((s, r) => s + r.reviewsCreated, 0),
    totalReviewsUpdated: results.reduce((s, r) => s + r.reviewsUpdated, 0),
    totalErrors: results.reduce((s, r) => s + r.errors.length, 0),
  };
}

/**
 * Ingest QField photos into the Construction QA system for a single project.
 *
 * Reads from qfield_photo_validations and creates/updates
 * construction_qa_reviews and construction_qa_photos records.
 */
export async function ingestQFieldPhotos(opts: IngestOptions): Promise<IngestResult> {
  const { projectId, discipline = 'all', sinceDate, dryRun = false } = opts;
  const result: IngestResult = {
    projectId,
    photosFound: 0,
    photosIngested: 0,
    reviewsCreated: 0,
    reviewsUpdated: 0,
    errors: [],
  };

  // Look up QField project IDs for this FibreFlow project
  const qfProjectIds = FIBREFLOW_TO_QFIELD[projectId];
  if (!qfProjectIds || qfProjectIds.length === 0) {
    result.errors.push(`No QField project mapping for FibreFlow project ${projectId}`);
    return result;
  }

  log.info('Starting QField ingestion', { projectId, qfProjectIds, discipline, sinceDate, dryRun }, MODULE);

  try {
    // Build work_type filter
    const workTypes: string[] = discipline === 'all'
      ? Object.keys(WORK_TYPE_MAP)
      : [Object.entries(WORK_TYPE_MAP).find(([, v]) => v.discipline === discipline)?.[0]].filter((x): x is string => x !== undefined);

    if (workTypes.length === 0) {
      result.errors.push(`No work types found for discipline: ${discipline}`);
      return result;
    }

    // Build parameterized query
    // $1..$N = qfProjectIds, then workTypes, then optional sinceDate
    let paramIdx = 1;
    const qfPlaceholders = qfProjectIds.map(() => `$${paramIdx++}`).join(', ');
    const wtPlaceholders = workTypes.map(() => `$${paramIdx++}`).join(', ');
    const params: (string | number)[] = [...qfProjectIds, ...workTypes];

    let query = `
      SELECT
        qpv.id AS qfield_id,
        qpv.photo_key,
        qpv.feature_id,
        qpv.feature_type,
        qpv.work_type,
        qpv.project_id AS qfield_project_id,
        qpv.vlm_confidence,
        qpv.vlm_feedback,
        qpv.vlm_raw_response,
        qpv.needs_retake,
        qpv.validated_at,
        qpv.created_at
      FROM qfield_photo_validations qpv
      WHERE qpv.feature_id IS NOT NULL
        AND qpv.project_id IN (${qfPlaceholders})
        AND qpv.work_type IN (${wtPlaceholders})
        AND NOT EXISTS (
          SELECT 1 FROM construction_qa_photos cqp
          WHERE cqp.storage_key = qpv.photo_key
            AND cqp.source = 'qfield'
        )
    `;

    if (sinceDate) {
      query += ` AND qpv.created_at >= $${paramIdx++}`;
      params.push(sinceDate);
    }

    query += ' ORDER BY qpv.created_at ASC';

    const photos = await sql.query(query, params);
    result.photosFound = photos.length;

    if (photos.length === 0) {
      log.info('No new photos to ingest', { projectId }, MODULE);
      return result;
    }

    if (dryRun) {
      log.info('Dry run — skipping writes', { projectId, photosFound: photos.length }, MODULE);
      return result;
    }

    // Deduplicate by photo_key (multiple qfield_photo_validations can reference same photo)
    const seenKeys = new Set<string>();
    const uniquePhotos = photos.filter(p => {
      const pk = p.photo_key as string;
      if (seenKeys.has(pk)) return false;
      seenKeys.add(pk);
      return true;
    });
    result.photosFound = uniquePhotos.length;

    // Group photos by feature_type + feature_id for review creation
    const byFeature = new Map<string, typeof photos>();
    for (const photo of uniquePhotos) {
      const ft = photo.feature_type as string || 'pole';
      const key = `${ft}::${photo.feature_id}`;
      if (!byFeature.has(key)) byFeature.set(key, []);
      byFeature.get(key)!.push(photo);
    }

    // Process each feature group
    for (const [featureKey, featurePhotos] of byFeature) {
      try {
        const sample = featurePhotos[0];
        if (!sample) continue;

        // For activation work_type, derive discipline from actual feature_type
        const rowFeatureType = sample.feature_type as string;
        const mapping = (sample.work_type === 'activation' && rowFeatureType && FEATURE_TYPE_DISCIPLINE[rowFeatureType])
          ? FEATURE_TYPE_DISCIPLINE[rowFeatureType]
          : WORK_TYPE_MAP[sample.work_type as string];
        if (!mapping) continue;

        // Upsert the review record
        const reviewId = await upsertReview(
          projectId,
          mapping.discipline,
          mapping.featureType,
          sample.feature_id as string,
          featurePhotos.length,
          result,
        );

        // Insert photo records and track earliest capture date
        let earliestCapture: Date | null = null;
        const featureId = sample.feature_id as string;
        for (const photo of featurePhotos) {
          const capturedAt = await insertPhoto(reviewId, projectId, photo, featureId);
          if (capturedAt && (!earliestCapture || capturedAt < earliestCapture)) {
            earliestCapture = capturedAt;
          }
          result.photosIngested++;
        }

        // Update review's last_photo_at to earliest capture date
        if (earliestCapture) {
          await sql`
            UPDATE construction_qa_reviews
            SET last_photo_at = LEAST(last_photo_at, ${earliestCapture.toISOString()}::timestamptz)
            WHERE id = ${reviewId}::uuid
          `;
        }
      } catch (err) {
        const msg = `Failed to process feature ${featureKey}: ${(err as Error).message}`;
        log.error('Ingestion error', { error: msg }, MODULE);
        result.errors.push(msg);
      }
    }

    log.info('QField ingestion complete', result, MODULE);
    return result;
  } catch (err) {
    const msg = `Ingestion failed: ${(err as Error).message}`;
    log.error('Fatal ingestion error', { error: msg }, MODULE);
    result.errors.push(msg);
    return result;
  }
}

/**
 * Upsert a construction_qa_reviews record.
 * Returns the review UUID.
 */
async function upsertReview(
  projectId: string,
  discipline: Discipline,
  featureType: FeatureType,
  featureId: string,
  newPhotoCount: number,
  result: IngestResult,
): Promise<string> {
  // Check if review exists
  const existing = await sql`
    SELECT id, photo_count FROM construction_qa_reviews
    WHERE project_id = ${projectId}::uuid
      AND feature_type = ${featureType}
      AND feature_id = ${featureId}
    LIMIT 1
  `;

  if (existing.length > 0) {
    // Update photo count from actual photo records (not additive — prevents drift)
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const existingRow = existing[0]!;
    await sql`
      UPDATE construction_qa_reviews
      SET photo_count = (
            SELECT COUNT(*)::int FROM construction_qa_photos
            WHERE review_id = ${existingRow.id}::uuid
          ),
          last_photo_at = NOW(),
          updated_at = NOW()
      WHERE id = ${existingRow.id}::uuid
    `;
    result.reviewsUpdated++;
    return existingRow.id as string;
  }

  // Look up zone/PON from the feature table
  let zoneNo: number | null = null;
  let ponNo: number | null = null;

  if (featureType === 'pole') {
    const pole = await sql`
      SELECT zone_no, pon_no FROM poles
      WHERE project_id = ${projectId}::uuid AND pole_number = ${featureId}
      LIMIT 1
    `;
    if (pole.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const p = pole[0]!;
      zoneNo = p.zone_no != null ? Number(p.zone_no) : null;
      ponNo = p.pon_no != null ? Number(p.pon_no) : null;
    }
  } else if (featureType === 'cable_span') {
    const span = await sql`
      SELECT zone_no, pon_no FROM cable_spans
      WHERE project_id = ${projectId}::uuid AND span_label = ${featureId}
      LIMIT 1
    `;
    if (span.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const s = span[0]!;
      zoneNo = s.zone_no != null ? Number(s.zone_no) : null;
      ponNo = s.pon_no != null ? Number(s.pon_no) : null;
    }
  } else if (featureType === 'joint') {
    const joint = await sql`
      SELECT zone_no, pon_no FROM joints
      WHERE project_id = ${projectId}::uuid AND joint_label = ${featureId}
      LIMIT 1
    `;
    if (joint.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const j = joint[0]!;
      zoneNo = j.zone_no != null ? Number(j.zone_no) : null;
      ponNo = j.pon_no != null ? Number(j.pon_no) : null;
    }
  }

  // Create new review
  const newReview = await sql`
    INSERT INTO construction_qa_reviews (
      project_id, discipline, feature_type, feature_id,
      zone_no, pon_no, photo_count, last_photo_at,
      workflow_status, vlm_status, priority
    ) VALUES (
      ${projectId}::uuid, ${discipline}, ${featureType}, ${featureId},
      ${zoneNo}, ${ponNo}, ${newPhotoCount}, NOW(),
      'pending', 'pending', 'normal'
    )
    RETURNING id
  `;

  result.reviewsCreated++;

  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const newReviewRow = newReview[0]!;

  // Log activity
  await sql`
    INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
    VALUES (
      ${newReviewRow.id}::uuid,
      'photo_ingested',
      'system',
      ${JSON.stringify({ source: 'qfield', photo_count: newPhotoCount })}::jsonb
    )
  `;

  return newReviewRow.id as string;
}

/**
 * Insert a construction_qa_photos record from a QField photo validation row.
 */
async function insertPhoto(
  reviewId: string,
  projectId: string,
  qfPhoto: Record<string, unknown>,
  featureId: string,
): Promise<Date | null> {
  const photoKey = qfPhoto.photo_key as string;
  const filename = photoKey.split('/').pop() || photoKey;

  // Determine MIME type from extension
  const ext = filename.split('.').pop()?.toLowerCase() || 'jpg';
  const mimeMap: Record<string, string> = {
    jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png',
    gif: 'image/gif', webp: 'image/webp', heic: 'image/heic',
  };
  const mimeType = mimeMap[ext] || 'image/jpeg';

  // Extract capture date from QField filename
  const capturedAt = parseQFieldCaptureDate(photoKey);

  // Copy photo from MinIO to local storage for fast serving
  const localPath = await copyQFieldPhotoToStorage(photoKey, projectId, featureId, filename);
  const source = localPath ? 'local' : 'qfield';
  const storageKey = localPath || photoKey;

  await sql`
    INSERT INTO construction_qa_photos (
      review_id, project_id, source, storage_key, filename, mime_type,
      vlm_valid, vlm_confidence, vlm_feedback,
      needs_retake, captured_at
    ) VALUES (
      ${reviewId}::uuid,
      ${projectId}::uuid,
      ${source},
      ${storageKey},
      ${filename},
      ${mimeType},
      ${qfPhoto.vlm_confidence != null ? Number(qfPhoto.vlm_confidence) >= 0.6 : null},
      ${qfPhoto.vlm_confidence != null ? Number(qfPhoto.vlm_confidence) : null},
      ${(qfPhoto.vlm_feedback as string) || null},
      ${Boolean(qfPhoto.needs_retake)},
      ${capturedAt ? capturedAt.toISOString() : null}
    )
  `;

  return capturedAt;
}

/**
 * POST /api/construction-qa/ingest-qfield
 *
 * Triggers ingestion of QField photos into the Construction QA system.
 * Reads from qfield_photo_validations and creates review + photo records.
 *
 * Auth: session cookie OR x-cron-secret header (for cron jobs)
 *
 * Body: { projectId?, discipline?, sinceDate?, dryRun? }
 *   - projectId: FibreFlow project UUID (optional — omit to ingest ALL mapped projects)
 *   - discipline: 'civil' | 'optical' | 'all' (default: 'all')
 *   - sinceDate: ISO date string to filter photos (optional)
 *   - dryRun: boolean (default: false)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { ingestQFieldPhotos, ingestAllQFieldPhotos } from '@/modules/construction-qa/services/qfieldIngestionService';

const CRON_SECRET = process.env.CRON_SECRET || '';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['POST']);
  }

  // Auth: cron secret or session cookie
  const cronSecret = req.headers['x-cron-secret'] || req.query.secret;
  if (cronSecret !== CRON_SECRET && !req.headers.cookie) {
    return apiResponse.unauthorized(res, 'Invalid cron secret');
  }

  try {
    const { projectId, discipline, sinceDate, dryRun } = req.body;

    if (!projectId) {
      // Ingest all mapped projects
      const result = await ingestAllQFieldPhotos({
        discipline: discipline || 'all',
        dryRun: Boolean(dryRun),
      });
      return apiResponse.success(res, { mode: 'all', dryRun: Boolean(dryRun), ...result });
    }

    const result = await ingestQFieldPhotos({
      projectId,
      discipline: discipline || 'all',
      sinceDate,
      dryRun: Boolean(dryRun),
    });

    return apiResponse.success(res, { mode: 'single', dryRun: Boolean(dryRun), ...result });
  } catch (error) {
    log.error('Ingest API error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default handler;

/**
 * QA Photo Local Storage Service
 *
 * Copies photos from MinIO (QField) or SharePoint to local disk storage
 * at /home/velo/storage/qa-photos/ for fast serving without API calls.
 *
 * Used by ingestion pipelines to ensure new photos are immediately
 * available from local disk across all environments.
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);
const STORAGE_ROOT = process.env.QA_PHOTO_STORAGE || '/home/velo/storage/qa-photos';
const MINIO_BUCKET = process.env.MINIO_BUCKET || 'qfieldcloud-prod';
const MODULE = 'qa-photo-storage';

// Project UUID → slug cache
const projectSlugCache = new Map<string, string>();

/**
 * Get a filesystem-safe project slug from its UUID.
 * Caches lookups to avoid repeated DB queries.
 */
async function getProjectSlug(projectId: string): Promise<string> {
  if (projectSlugCache.has(projectId)) {
    return projectSlugCache.get(projectId)!;
  }

  const rows = await sql`
    SELECT project_name FROM projects WHERE id = ${projectId}::uuid LIMIT 1
  `;

  const name = rows[0]?.project_name as string || projectId;
  const slug = name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
  projectSlugCache.set(projectId, slug);
  return slug;
}

/**
 * Sanitize a filename for filesystem use.
 */
function sanitize(name: string): string {
  return name.replace(/[<>:"|?*]/g, '_');
}

/**
 * Build the local storage relative path for a photo.
 */
async function buildLocalPath(
  projectId: string,
  featureId: string,
  filename: string,
): Promise<string> {
  const projectSlug = await getProjectSlug(projectId);
  const safeFeature = sanitize(featureId);
  const safeFilename = sanitize(filename);
  return `${projectSlug}/${safeFeature}/${safeFilename}`;
}

/**
 * Copy a QField photo from MinIO to local storage.
 *
 * @returns The relative storage path if successful, null on failure.
 *          On failure, the caller should fall back to source='qfield'.
 */
export async function copyQFieldPhotoToStorage(
  minioKey: string,
  projectId: string,
  featureId: string,
  filename: string,
): Promise<string | null> {
  try {
    const relPath = await buildLocalPath(projectId, featureId, filename);
    const destPath = path.join(STORAGE_ROOT, relPath);

    // Skip if already exists
    if (fs.existsSync(destPath)) {
      return relPath;
    }

    // Ensure directory
    fs.mkdirSync(path.dirname(destPath), { recursive: true });

    // Copy from MinIO
    const objectPath = minioKey.startsWith('/') ? minioKey.slice(1) : minioKey;
    const mcPath = `local/${MINIO_BUCKET}/${objectPath}`;
    const escapedPath = mcPath.replace(/'/g, "'\\''");

    const buffer = execSync(`docker exec qfieldcloud-minio-1 mc cat '${escapedPath}'`, {
      maxBuffer: 50 * 1024 * 1024,
    });

    if (buffer.length < 100) {
      log.warn('MinIO photo too small, skipping local copy', { minioKey, size: buffer.length }, MODULE);
      return null;
    }

    fs.writeFileSync(destPath, buffer);
    return relPath;
  } catch (err) {
    log.warn('Failed to copy QField photo to local storage', {
      minioKey,
      error: (err as Error).message.slice(0, 100),
    }, MODULE);
    return null;
  }
}

/**
 * Download a SharePoint photo to local storage.
 *
 * @param graphUrl - Full MS Graph API URL for the photo content
 * @param token - Valid MS Graph bearer token
 * @returns The relative storage path if successful, null on failure.
 */
export async function downloadSharePointPhotoToStorage(
  graphUrl: string,
  token: string,
  projectId: string,
  featureId: string,
  filename: string,
): Promise<string | null> {
  try {
    const relPath = await buildLocalPath(projectId, featureId, filename);
    const destPath = path.join(STORAGE_ROOT, relPath);

    // Skip if already exists
    if (fs.existsSync(destPath)) {
      return relPath;
    }

    // Ensure directory
    fs.mkdirSync(path.dirname(destPath), { recursive: true });

    let url = graphUrl;
    if (!url.endsWith('/content')) url += '/content';

    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
      redirect: 'follow',
    });

    if (!res.ok) {
      log.warn('SharePoint download failed', { status: res.status, graphUrl }, MODULE);
      return null;
    }

    const buffer = Buffer.from(await res.arrayBuffer());
    if (buffer.length < 100) {
      log.warn('SharePoint photo too small', { graphUrl, size: buffer.length }, MODULE);
      return null;
    }

    fs.writeFileSync(destPath, buffer);
    return relPath;
  } catch (err) {
    log.warn('Failed to download SharePoint photo to local storage', {
      graphUrl,
      error: (err as Error).message.slice(0, 100),
    }, MODULE);
    return null;
  }
}

/**
 * EXIF / capture-date utilities for Construction QA photos.
 *
 * Two strategies:
 *   1. parseQFieldCaptureDate — extracts timestamp from QField filename pattern
 *      (no I/O, instant, works for all 5 834 QField photos)
 *   2. extractExifFromBuffer — reads EXIF DateTimeOriginal + GPS from image buffer
 *      (needs sharp + exif-reader, used for future non-QField sources)
 */

import { log } from '@/lib/logger';

const MODULE = 'exif-utils';

/**
 * QField storage keys encode capture time in the filename portion:
 *   projects/.../DCIM/law-poles_20251120145759971.JPG/v20251120130451-5e8d1c2f
 *   Pattern: _YYYYMMDDHHMMSSmmm  (mmm = milliseconds, may be absent)
 *
 * The filename is NOT the last segment (that's the version suffix).
 * We match the timestamp pattern anywhere in the key.
 */
const QF_TS_RE = /_(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})(\d{3})?\.(?:jpg|jpeg|png|gif|webp|heic)/i;

export function parseQFieldCaptureDate(storageKey: string): Date | null {
  const m = QF_TS_RE.exec(storageKey);
  if (!m) return null;

  const [, year, month, day, hour, min, sec, ms] = m;
  const iso = `${year}-${month}-${day}T${hour}:${min}:${sec}.${ms || '000'}Z`;

  const d = new Date(iso);
  if (isNaN(d.getTime())) {
    log.warn('Invalid QField capture date', { storageKey, iso }, MODULE);
    return null;
  }
  return d;
}

interface ExifResult {
  capturedAt?: Date;
  gpsLat?: number;
  gpsLon?: number;
}

/**
 * Extract EXIF metadata from an image buffer using sharp + exif-reader.
 * Returns DateTimeOriginal and GPS coordinates when available.
 */
export async function extractExifFromBuffer(buffer: Buffer): Promise<ExifResult> {
  const result: ExifResult = {};

  try {
    // Dynamic imports to keep module lightweight when only using parseQFieldCaptureDate
    const sharp = (await import('sharp')).default;
    const exifReader = (await import('exif-reader')).default;

    const metadata = await sharp(buffer).metadata();
    if (!metadata.exif) return result;

    const exif = exifReader(metadata.exif);

    // DateTimeOriginal
    if (exif?.Photo?.DateTimeOriginal) {
      const dt = exif.Photo.DateTimeOriginal;
      if (dt instanceof Date && !isNaN(dt.getTime())) {
        result.capturedAt = dt;
      }
    }

    // GPS coordinates
    if (exif?.GPSInfo) {
      const gps = exif.GPSInfo;
      if (gps.GPSLatitude != null && gps.GPSLongitude != null) {
        result.gpsLat = gps.GPSLatitude as number;
        result.gpsLon = gps.GPSLongitude as number;
      }
    }
  } catch (err) {
    log.warn('EXIF extraction failed', { error: (err as Error).message }, MODULE);
  }

  return result;
}

/**
 * Construction QA Module — Type Exports
 *
 * Re-exports all public types from construction.types.ts.
 * Import from this barrel file rather than the implementation file directly.
 *
 * Example:
 *   import type { ConstructionQaReview, Discipline, QaDecision } from '@/modules/construction-qa/types';
 */
export * from './construction.types';

/**
 * VLM Construction Service
 *
 * AI-powered photo validation for construction QA using Qwen3-VL on Velocity:8100.
 * Evaluates photos per checklist step and returns structured results.
 *
 * Pattern: OpenAI-compatible chat/completions API with image_url messages.
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { getChecklist } from '../types/construction.types';
import type { Discipline, VlmStepResult, VlmOverallResult } from '../types';
import { recordCorrectExtraction, getVlmFewShotExamples, buildVlmFewShotPrompt } from '@/services/vlmLearningService';

const sql = neon(process.env.DATABASE_URL!);
const MODULE = 'cqa-vlm';
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';
const MAX_IMAGE_DIM = 1024;

interface ValidateOptions {
  reviewId: string;
  discipline: Discipline;
  photoId?: string;
  forceRerun?: boolean;
}

interface ValidateResult {
  photosProcessed: number;
  overallConfidence: number | null;
  vlmStatus: string;
  stepResults: VlmStepResult[];
  error?: string;
}

/**
 * Run VLM validation on a review's photos.
 * Updates construction_qa_reviews and construction_qa_photos with results.
 */
export async function validateReviewPhotos(opts: ValidateOptions): Promise<ValidateResult> {
  const { reviewId, discipline, photoId, forceRerun = false } = opts;
  const result: ValidateResult = {
    photosProcessed: 0,
    overallConfidence: null,
    vlmStatus: 'processing',
    stepResults: [],
  };

  try {
    // Mark review as processing
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'processing', updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log activity
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_started', 'vlm', '{}'::jsonb)
    `;

    // Fetch photos to validate
    let photosQuery = `
      SELECT id, storage_key, source, checklist_step, filename
      FROM construction_qa_photos
      WHERE review_id = $1::uuid
    `;
    const params: (string | boolean)[] = [reviewId];

    if (photoId) {
      photosQuery += ` AND id = $2::uuid`;
      params.push(photoId);
    } else if (!forceRerun) {
      photosQuery += ` AND vlm_processed_at IS NULL`;
    }

    photosQuery += ` ORDER BY checklist_step ASC NULLS LAST`;

    const photos = await sql.query(photosQuery, params);

    if (photos.length === 0) {
      result.vlmStatus = 'completed';
      await sql`
        UPDATE construction_qa_reviews
        SET vlm_status = 'completed', updated_at = NOW()
        WHERE id = ${reviewId}::uuid
      `;
      return result;
    }

    const checklist = getChecklist(discipline);

    // Fetch few-shot correction examples for prompt enhancement (non-blocking on failure)
    let fewShotSection = '';
    try {
      const fewShotExamples = await getVlmFewShotExamples({
        module: 'construction_qa',
        analysisType: 'construction_photo_qa',
        context: { discipline },
        maxExamples: 3,
        prioritizeCanonical: true,
      });
      fewShotSection = buildVlmFewShotPrompt(fewShotExamples, 'markdown');
    } catch (fewShotErr) {
      log.warn('Few-shot retrieval failed, continuing without', {
        error: (fewShotErr as Error).message,
      }, MODULE);
    }

    // Process each photo
    for (const photo of photos) {
      try {
        const step = photo.checklist_step;
        const stepDef = step ? checklist.find(s => s.step === step) : null;

        // Build the prompt for this photo
        const prompt = buildPhotoPrompt(discipline, step, stepDef ?? null, fewShotSection);

        // Build the photo URL for VLM
        const photoUrl = buildPhotoUrl(photo.storage_key, photo.source);

        // Call VLM
        const vlmResult = await callVlm(photoUrl, prompt, step || 0, stepDef?.label || 'Uncategorized');

        // Update photo with results
        await sql`
          UPDATE construction_qa_photos
          SET vlm_valid = ${vlmResult.valid},
              vlm_confidence = ${vlmResult.confidence},
              vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
              vlm_feedback = ${vlmResult.feedback},
              vlm_raw = ${JSON.stringify(vlmResult)}::jsonb,
              vlm_processed_at = NOW(),
              updated_at = NOW()
          WHERE id = ${photo.id}::uuid
        `;

        result.stepResults.push(vlmResult);
        result.photosProcessed++;

        // Record VLM learning metric (fire-and-forget)
        if (vlmResult.confidence >= 0.7) {
          recordCorrectExtraction('construction_qa', 'construction_photo_qa', vlmResult.confidence)
            .catch(() => {});
        }
      } catch (photoErr) {
        log.error('Photo VLM failed', { photoId: photo.id, error: (photoErr as Error).message }, MODULE);
      }
    }

    // Calculate overall confidence
    if (result.stepResults.length > 0) {
      const totalConf = result.stepResults.reduce((sum, r) => sum + r.confidence, 0);
      result.overallConfidence = Number((totalConf / result.stepResults.length).toFixed(3));
    }

    // Build overall result
    const overallResult: VlmOverallResult = {
      overall_valid: result.stepResults.every(r => r.valid),
      overall_confidence: result.overallConfidence || 0,
      steps: Object.fromEntries(result.stepResults.map(r => [String(r.step), r])),
      cross_step_issues: [],
      processed_at: new Date().toISOString(),
      model_version: VLM_MODEL,
    };

    // Build step scores
    const stepScores: Record<string, number> = {};
    for (const sr of result.stepResults) {
      stepScores[`step_${String(sr.step).padStart(2, '0')}`] = sr.confidence;
    }

    // Update review with aggregate results
    result.vlmStatus = 'completed';
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'completed',
          vlm_confidence = ${result.overallConfidence},
          vlm_step_scores = ${JSON.stringify(stepScores)}::jsonb,
          vlm_issues = ${JSON.stringify(overallResult.cross_step_issues)}::jsonb,
          vlm_raw_response = ${JSON.stringify(overallResult)}::jsonb,
          vlm_processed_at = NOW(),
          vlm_model_version = ${VLM_MODEL},
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log completion
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_completed', 'vlm',
        ${JSON.stringify({ photos_processed: result.photosProcessed, overall_confidence: result.overallConfidence })}::jsonb)
    `;

    return result;
  } catch (err) {
    result.vlmStatus = 'failed';
    result.error = (err as Error).message;

    // Mark as failed
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'failed',
          vlm_retry_count = vlm_retry_count + 1,
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_failed', 'vlm',
        ${JSON.stringify({ error: result.error })}::jsonb)
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    log.error('VLM validation failed', { reviewId, error: result.error }, MODULE);
    return result;
  }
}

/**
 * Call the VLM API with a photo and prompt.
 */
async function callVlm(
  imageUrl: string,
  prompt: string,
  step: number,
  stepLabel: string,
): Promise<VlmStepResult> {
  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 1024,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || '';

    // Parse structured JSON from VLM response
    return parseVlmResponse(text, step, stepLabel);
  } catch (err) {
    log.error('VLM call failed', { error: (err as Error).message }, MODULE);

    // Return a failure result
    return {
      valid: false,
      confidence: 0,
      step,
      step_label: stepLabel,
      issues: [`VLM error: ${(err as Error).message}`],
      feedback: 'AI validation unavailable — manual review required',
      extracted_data: {},
    };
  }
}

/**
 * Parse VLM text response into structured result.
 */
function parseVlmResponse(text: string, step: number, stepLabel: string): VlmStepResult {
  try {
    // Try to find JSON in the response
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return {
        valid: Boolean(parsed.valid ?? parsed.pass ?? false),
        confidence: Number(parsed.confidence ?? parsed.score ?? 0) / (parsed.score != null && parsed.score > 1 ? 10 : 1),
        step,
        step_label: stepLabel,
        issues: Array.isArray(parsed.issues) ? parsed.issues : parsed.issue ? [parsed.issue] : [],
        feedback: parsed.feedback || parsed.comment || '',
        extracted_data: parsed.extracted_data || parsed.data || {},
      };
    }
  } catch {
    // JSON parse failed — fall through to text analysis
  }

  // Fallback: analyze text for pass/fail indicators
  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable') || lower.includes('meets');
  const confidence = valid ? 0.7 : 0.3;

  return {
    valid,
    confidence,
    step,
    step_label: stepLabel,
    issues: valid ? [] : ['See VLM feedback for details'],
    feedback: text.slice(0, 500),
    extracted_data: {},
  };
}

/**
 * Build discipline-specific VLM prompt for a checklist step.
 */
function buildPhotoPrompt(
  discipline: Discipline,
  step: number | null,
  stepDef: { label: string; vlmCheck: string; notes?: string } | null,
  fewShotSection = '',
): string {
  const base = `You are a construction quality assurance AI inspector for fiber network installations.
Discipline: ${discipline}
${step ? `Checklist Step ${step}: ${stepDef?.label || 'Unknown'}` : 'General photo evaluation'}

${stepDef?.vlmCheck ? `Check: ${stepDef.vlmCheck}` : ''}
${stepDef?.notes ? `Notes: ${stepDef.notes}` : ''}
${fewShotSection ? `\n${fewShotSection}\n` : ''}
Evaluate this photo and respond with ONLY a JSON object:
{
  "valid": true/false,
  "confidence": 0.0-1.0,
  "issues": ["list of specific issues found"],
  "feedback": "one sentence of actionable feedback for the field technician",
  "extracted_data": { any relevant data extracted from the photo }
}

Be strict but fair. A photo must clearly show the required element to pass.`;

  return base;
}

/**
 * Build a URL for the VLM to access the photo.
 */
function buildPhotoUrl(storageKey: string, source: string): string {
  // VLM runs on Velocity, so we use the local API to proxy the photo
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  return `${baseUrl}/api/construction-qa/photo-proxy?key=${encodeURIComponent(storageKey)}&source=${source}`;
}

/**
 * Field Ops VLM Validation Service
 *
 * Two-stage AI validation for field_ops_wa_photos (upload_status='uploaded', vlm_processed=false):
 * 1. VLM Visual Analysis — Qwen3-VL-8B inspects photos for discipline-specific QA criteria
 *    and extracts the pole number from visible labels.
 * 2. Project Cross-Reference — Validates the extracted pole number against the project SOW
 *    (poles table) and checks PON stage progression.
 *
 * @module field-ops/services/fieldOpsVlmService
 */

import { neon } from '@/lib/db-neon';
import { createLogger } from '@/lib/logger';

const logger = createLogger('fieldOpsVlmService');
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';

function getDb() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  return neon(process.env.DATABASE_URL);
}

// ============================================================================
// Types
// ============================================================================

interface UploadedPhoto {
  id: string;
  group_type: string;
  project: string;
  storage_key: string;
  local_path: string;
  wa_group_jid: string;
  message_timestamp: string;
}

interface VlmResult {
  extracted_pole_number: string | null;
  vlm_valid: boolean;
  confidence: number;
  issues: string[];
  feedback: string;
}

interface CrossRefResult {
  valid: boolean;
  issues: string[];
  pole_number: string | null;
  zone_no: number | null;
  pon_no: number | null;
}

// ============================================================================
// VLM Prompts
// ============================================================================

const CIVIL_PROMPT = `You are a civil construction QA inspector for fiber network pole installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Pole verticality, 2) Depth marker visible, 3) Ground compaction, 4) Stay wires installed, 5) Pole label/number.
JSON format:
{"extracted_pole_number":"POL-001 or null","valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

const OPTICAL_PROMPT = `You are a fiber optic construction QA inspector for aerial fiber installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Cable tension appropriate, 2) Sag within spec, 3) Splice dome sealed, 4) Cable markings.
JSON format:
{"extracted_pole_number":null,"valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

// ============================================================================
// Stage 1: VLM Visual Analysis
// ============================================================================

function parseVlmResponse(text: string): VlmResult {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const p = JSON.parse(jsonMatch[0]);
      return {
        extracted_pole_number: p.extracted_pole_number ? String(p.extracted_pole_number) : null,
        vlm_valid: Boolean(p.valid ?? p.pass ?? false),
        confidence: Math.min(1, Math.max(0, Number(p.confidence ?? 0))),
        issues: Array.isArray(p.issues) ? p.issues : [],
        feedback: String(p.feedback || ''),
      };
    }
  } catch { /* fall through */ }

  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable');
  return {
    extracted_pole_number: null,
    vlm_valid: valid,
    confidence: valid ? 0.5 : 0.2,
    issues: valid ? [] : ['Manual review required — AI could not parse response'],
    feedback: text.slice(0, 300),
  };
}

/**
 * Call Qwen3-VL to analyse a construction photo and extract QA results.
 */
async function runVlmAnalysis(photoPath: string, discipline: string): Promise<VlmResult> {
  const prompt = discipline === 'civil' ? CIVIL_PROMPT : OPTICAL_PROMPT;
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  const imageUrl = photoPath.startsWith('http')
    ? photoPath
    : `${baseUrl}/api/field-ops/photo-proxy?path=${encodeURIComponent(photoPath)}`;

  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 512,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text: string = data.choices?.[0]?.message?.content || '';
    return parseVlmResponse(text);
  } catch (error) {
    logger.error('VLM analysis failed', {
      error: error instanceof Error ? error.message : 'Unknown',
      photoPath,
    });
    return {
      extracted_pole_number: null,
      vlm_valid: false,
      confidence: 0,
      issues: [`VLM error: ${error instanceof Error ? error.message : 'Unknown'}`],
      feedback: 'AI validation unavailable — manual review required',
    };
  }
}

// ============================================================================
// Stage 2: Project Cross-Reference
// ============================================================================

/**
 * Validate extracted pole number against the project SOW and PON stage tracking.
 */
async function crossReferenceProject(
  poleNumber: string | null,
  projectName: string
): Promise<CrossRefResult> {
  if (!poleNumber) {
    return { valid: false, issues: ['Could not extract pole number from photo'], pole_number: null, zone_no: null, pon_no: null };
  }

  const sql = getDb();
  const projects = await sql`SELECT id FROM projects WHERE project_name = ${projectName} LIMIT 1`;

  if (projects.length === 0) {
    return { valid: false, issues: [`Project '${projectName}' not found`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const projectRow = projects[0] as Record<string, unknown> | undefined;
  const projectId = projectRow?.id as string | undefined;
  if (!projectId) {
    return { valid: false, issues: [`Project '${projectName}' has no ID`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poles = await sql`
    SELECT zone_no, pon_no FROM poles
    WHERE project_id = ${projectId}::uuid AND pole_number = ${poleNumber}
    LIMIT 1
  `;

  if (poles.length === 0) {
    return { valid: false, issues: [`Pole ${poleNumber} not in SOW for '${projectName}'`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poleRow = poles[0] as Record<string, unknown> | undefined;
  const ponNo = poleRow?.pon_no ? Number(poleRow.pon_no) : null;
  const zoneNo = poleRow?.zone_no ? Number(poleRow.zone_no) : null;
  const issues: string[] = [];

  if (ponNo !== null) {
    const stages = await sql`
      SELECT overall_stage FROM pon_stage_tracking
      WHERE project_id = ${projectId}::uuid AND pon_no = ${ponNo}
      LIMIT 1
    `;
    if (stages.length > 0) {
      const stageRow = stages[0] as Record<string, unknown> | undefined;
      const stage = stageRow?.overall_stage as string | undefined;
      if (stage === 'design' || stage === 'planning') {
        issues.push(`PON ${ponNo} is in '${stage}' stage — pole work may be premature`);
      }
    }
  }

  return { valid: issues.length === 0, issues, pole_number: poleNumber, zone_no: zoneNo, pon_no: ponNo };
}

