// Exports
// ============================================================================

/**
 * Run VLM + cross-reference validation for a single uploaded photo.
 * Updates field_ops_wa_photos with all results.
 */
export async function validatePhoto(photo: UploadedPhoto): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();
  const discipline = photo.group_type;

  try {
    const vlmResult = await runVlmAnalysis(photo.local_path || photo.storage_key, discipline);

    let crossRef: CrossRefResult = { valid: true, issues: [], pole_number: null, zone_no: null, pon_no: null };
    if (discipline === 'civil' && photo.project) {
      crossRef = await crossReferenceProject(vlmResult.extracted_pole_number, photo.project);
    }

    await sql`
      UPDATE field_ops_wa_photos SET
        vlm_processed = true,
        vlm_valid = ${vlmResult.vlm_valid},
        vlm_confidence = ${vlmResult.confidence},
        vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
        vlm_feedback = ${vlmResult.feedback},
        vlm_processed_at = NOW(),
        cross_ref_valid = ${crossRef.valid},
        cross_ref_issues = ${JSON.stringify(crossRef.issues)}::jsonb,
        matched_pole_number = ${crossRef.pole_number},
        matched_zone_no = ${crossRef.zone_no},
        matched_pon_no = ${crossRef.pon_no},
        updated_at = NOW()
      WHERE id = ${photo.id}
    `;

    logger.info('Photo validation complete', {
      photoId: photo.id,
      discipline,
      vlmValid: vlmResult.vlm_valid,
      crossRefValid: crossRef.valid,
      poleNumber: crossRef.pole_number,
    });

    return { success: true };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Photo validation failed', { photoId: photo.id, error: errorMessage });
    return { success: false, error: errorMessage };
  }
}

/**
 * Batch validate uploaded photos pending VLM processing
 */
export async function validatePendingPhotos(limit = 5): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
}> {
  const sql = getDb();
  const photos = await sql`
    SELECT id, group_type, project, storage_key, local_path, wa_group_jid, message_timestamp
    FROM field_ops_wa_photos
    WHERE upload_status = 'uploaded' AND vlm_processed = false
    ORDER BY created_at ASC
    LIMIT ${limit}
  `;

  const results = { processed: 0, succeeded: 0, failed: 0 };

  for (const photo of photos) {
    results.processed++;
    try {
      const result = await validatePhoto(photo as unknown as UploadedPhoto);
      if (result.success) results.succeeded++;
      else results.failed++;
    } catch {
      results.failed++;
    }
  }

  logger.info('Batch VLM validation complete', results);
  return results;
}

/**
 * Construction QA Module — TypeScript Type Definitions
 *
 * Covers the two pre-activation construction disciplines:
 *   • Civil      — pole planting
 *   • Optical    — dome joint installation (Phase A: distribution dome, Phase B: main joint)
 *
 * Database alignment: construction_qa_reviews, construction_qa_photos,
 *   construction_qa_activity, construction_qa_assignments (migrations 200–203, 240).
 *
 * NLNH Confidence: HIGH — types derived directly from PRD sections 6, 7, and 14.
 */

// ============================================================================
// PRIMITIVE UNION TYPES (Enums as const-unions for type safety)
// ============================================================================

/** The construction discipline being quality-assured. */
export type Discipline = 'civil' | 'optical';

/**
 * The physical infrastructure feature under review.
 * Maps 1:1 with database tables: poles, cable_spans, joints.
 */
export type FeatureType = 'pole' | 'cable_span' | 'joint';

/**
 * Workflow lifecycle for a construction QA review record.
 * Mirrors dr_photo_unified_reviews workflow in the Activate module.
 */
export type WorkflowStatus =
  | 'pending'
  | 'in_review'
  | 'approved'
  | 'rejected'
  | 'rework_needed'
  | 'escalated'
  | 'unidentified';

/** Processing state of the VLM validation pipeline for a review. */
export type VlmStatus = 'pending' | 'processing' | 'completed' | 'failed';

/** Photo storage origin — used for proxy routing and audit trail. */
export type PhotoSource = 'qfield' | 'sharepoint' | 'whatsapp' | 'upload';

/**
 * Formal QA decision on a feature, made in Phase 4 of the wizard.
 * REWORK_NEEDED sends the feature back to the field without failing it permanently.
 */
export type QaDecision = 'PASS' | 'FAIL' | 'REWORK_NEEDED';

/** Review queue priority for triage and assignment ordering. */
export type Priority = 'low' | 'normal' | 'high' | 'urgent';

/**
 * Manual override on a single photo (distinct from whole-feature QaDecision).
 * NULL means no manual review yet.
 */
export type PhotoManualStatus = 'approved' | 'rejected' | 'pending' | null;

/**
 * Activity event types logged to construction_qa_activity.
 * Provides a full audit trail of every state change.
 */
export type ActivityEventType =
  | 'photo_ingested'
  | 'vlm_started'
  | 'vlm_completed'
  | 'vlm_failed'
  | 'review_opened'
  | 'step_checked'
  | 'step_unchecked'
  | 'decision_made'
  | 'feedback_sent'
  | 'rework_requested'
  | 'resubmission_received'
  | 'assigned'
  | 'escalated'
  | 'comment_added';

