/**
 * Activate Group Component
 * Wraps activate import tabs: OES Import, ARCH Import, Manual Entry
 */

'use client';

import React, { useEffect, useMemo } from 'react';
import { FileSpreadsheet, WifiOff, PlusCircle, FileSearch, Loader2, Lock } from 'lucide-react';
import type { ActivateTabId } from '../../types';
import { usePermission } from '@/hooks/usePermission';

// Import existing activate components
import { OESImportTab } from '@/modules/activate/components/OESImportTab';
import { OfflineImportTab } from '@/modules/activate/components/OfflineImportTab';
import { ManualDREntry } from '@/modules/activate/components/ManualDREntry';
import { PPDataTab } from '@/modules/activate/components/PPDataTab';

// Tab configuration with permission keys
const TABS: { id: ActivateTabId; label: string; icon: React.ElementType; permissionKey: string }[] = [
  { id: 'oes', label: 'OES Import', icon: FileSpreadsheet, permissionKey: 'system.data-sync.activate.oes' },
  { id: 'arch', label: 'ARCH Import', icon: WifiOff, permissionKey: 'system.data-sync.activate.arch' },
  { id: 'manual', label: 'Manual Entry', icon: PlusCircle, permissionKey: 'system.data-sync.activate.manual' },
  { id: 'pp-data', label: 'PP Data', icon: FileSearch, permissionKey: 'system.data-sync.activate.pp-data' },
];

interface ActivateGroupProps {
  activeTab: string | null;
  onTabChange: (tabId: string) => void;
}

export function ActivateGroup({ activeTab, onTabChange }: ActivateGroupProps) {
  const { can, isLoading: permissionsLoading } = usePermission();

  // Filter tabs based on permissions
  const accessibleTabs = useMemo(() => {
    if (permissionsLoading) return [];
    return TABS.filter(tab => can(tab.permissionKey, 'view'));
  }, [permissionsLoading, can]);

  // Default to first accessible tab
  const currentTab = useMemo(() => {
    const requested = activeTab as ActivateTabId;
    if (accessibleTabs.some(t => t.id === requested)) {
      return requested;
    }
    return accessibleTabs[0]?.id || 'oes';
  }, [activeTab, accessibleTabs]);

  // Sync URL with active tab on mount
  useEffect(() => {
    if (!activeTab && accessibleTabs.length > 0) {
      onTabChange(accessibleTabs[0].id);
    }
  }, [activeTab, onTabChange, accessibleTabs]);

  // Callback for when an import completes (optional refresh trigger)
  const handleImportComplete = () => {
    // Could trigger a refresh or show notification
    // For now, components handle their own success states
  };

  // Show loading state
  if (permissionsLoading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-8 h-8 animate-spin text-[var(--ff-accent)]" />
        <span className="ml-3 text-[var(--ff-text-secondary)]">Loading...</span>
      </div>
    );
  }

  // Show access denied if no tabs accessible
  if (accessibleTabs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center">
        <div className="w-16 h-16 mb-4 rounded-full bg-red-500/10 flex items-center justify-center">
          <Lock className="w-8 h-8 text-red-400" />
        </div>
        <h2 className="text-xl font-semibold text-[var(--ff-text-primary)] mb-2">Access Restricted</h2>
        <p className="text-[var(--ff-text-secondary)] max-w-md">
          You don&apos;t have permission to access any Activate tabs.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="border-b border-[var(--ff-border-light)]">
        <nav className="flex gap-1 overflow-x-auto scrollbar-hide" aria-label="Activate Tabs">
          {accessibleTabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = currentTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => onTabChange(tab.id)}
                className={`
                  flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap
                  ${
                    isActive
                      ? 'border-[var(--ff-accent)] text-[var(--ff-accent)]'
                      : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-[var(--ff-border-medium)]'
                  }
                `}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            );
          })}
        </nav>
      </div>

      {/* Tab Content */}
      {currentTab === 'oes' && (
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg shadow-md p-6 border border-[var(--ff-border-light)]">
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
              OES Activation Import
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)]">
              Import Nokia OES activation reports to reconcile drops with actual activations
            </p>
          </div>
          <OESImportTab onImportComplete={handleImportComplete} />
        </div>
      )}

      {currentTab === 'arch' && (
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg shadow-md p-6 border border-[var(--ff-border-light)]">
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
              ARCH Offline Import
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)]">
              Import ARCH network audit reports to detect offline devices and serial mismatches
            </p>
          </div>
          <OfflineImportTab onImportComplete={handleImportComplete} />
        </div>
      )}

      {currentTab === 'manual' && (
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg shadow-md p-6 border border-[var(--ff-border-light)]">
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Manual DR Entry</h2>
            <p className="text-sm text-[var(--ff-text-secondary)]">
              Add DRs manually when WhatsApp bridge is down or for special processing
            </p>
          </div>
          <ManualDREntry />
        </div>
      )}

      {currentTab === 'pp-data' && (
        <div className="bg-[var(--ff-bg-secondary)] rounded-lg shadow-md p-6 border border-[var(--ff-border-light)]">
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
              PP Data (Pre-Provision)
            </h2>
            <p className="text-sm text-[var(--ff-text-secondary)]">
              Import and resolve pre-provisioned ONT serial numbers from OES PP DATA tab
            </p>
          </div>
          <PPDataTab />
        </div>
      )}
    </div>
  );
}

/**
 * Permission Service
 * Database-driven RBAC with module/page/tab/action hierarchy
 */

import { neon } from '@/lib/db-neon';

const sql = neon(process.env.DATABASE_URL!);

// Types
export type PermissionType = 'module' | 'page' | 'tab' | 'action';

export type PermissionAction = 'view' | 'create' | 'edit' | 'delete';

export interface Permission {
  id: string;
  type: PermissionType;
  key: string;
  parentKey: string | null;
  label: string;
  description: string | null;
  route: string | null;
  sortOrder: number;
  isActive: boolean;
}

export interface PermissionActions {
  view: boolean;
  create: boolean;
  edit: boolean;
  delete: boolean;
}

export interface RolePermission {
  role: string;
  permissionKey: string;
  actions: PermissionActions;
}

export interface RolePermissionWithLabel extends RolePermission {
  key: string;
  label: string;
  type?: string;
}

export interface UserPermissionOverride {
  userId: string;
  permissionKey: string;
  overrideType: 'grant' | 'revoke';
  actions: PermissionActions;
  grantedBy: string | null;
  grantedAt: Date;
  expiresAt: Date | null;
  reason: string | null;
}

export interface EffectivePermission {
  permissionKey: string;
  canView: boolean;
  canCreate: boolean;
  canEdit: boolean;
  canDelete: boolean;
}

// =====================================================
// Permission Queries
// =====================================================

/**
 * Get all permissions (optionally filtered by type)
 */
export async function getPermissions(type?: PermissionType): Promise<Permission[]> {
  const result = type
    ? await sql`
        SELECT id, type, key, parent_key, label, description, route, sort_order, is_active
        FROM access_permissions
        WHERE is_active = true AND type = ${type}
        ORDER BY sort_order
      `
    : await sql`
        SELECT id, type, key, parent_key, label, description, route, sort_order, is_active
        FROM access_permissions
        WHERE is_active = true
        ORDER BY
          CASE type
            WHEN 'module' THEN 1
            WHEN 'page' THEN 2
            WHEN 'tab' THEN 3
            WHEN 'action' THEN 4
          END,
          sort_order
      `;

  return result.map(row => ({
    id: row.id,
    type: row.type as PermissionType,
    key: row.key,
    parentKey: row.parent_key,
    label: row.label,
    description: row.description,
    route: row.route,
    sortOrder: row.sort_order,
    isActive: row.is_active,
  }));
}

/**
 * Get permission tree (hierarchical structure)
 */
export async function getPermissionTree(): Promise<Permission[]> {
  return getPermissions();
}

/**
 * Get permissions for a specific module (and its children)
 */
export async function getModulePermissions(moduleKey: string): Promise<Permission[]> {
  const result = await sql`
    SELECT id, type, key, parent_key, label, description, route, sort_order, is_active
    FROM access_permissions
    WHERE is_active = true
      AND (key = ${moduleKey} OR key LIKE ${moduleKey + '.%'})
    ORDER BY
      CASE type
        WHEN 'module' THEN 1
        WHEN 'page' THEN 2
        WHEN 'tab' THEN 3
        WHEN 'action' THEN 4
      END,
      sort_order
  `;

  return result.map(row => ({
    id: row.id,
    type: row.type as PermissionType,
    key: row.key,
    parentKey: row.parent_key,
    label: row.label,
    description: row.description,
    route: row.route,
    sortOrder: row.sort_order,
    isActive: row.is_active,
  }));
}

// =====================================================
// Role Queries
// =====================================================

/**
 * Get all unique roles
 */
export async function getRoles(): Promise<string[]> {
  const result = await sql`
    SELECT DISTINCT role FROM role_permissions ORDER BY role
  `;
  return result.map(row => row.role);
}

/**
 * Get permissions for a specific role
 */
export async function getRolePermissions(role: string): Promise<RolePermissionWithLabel[]> {
  const result = await sql`
    SELECT rp.role, rp.permission_key, rp.actions, ap.label, ap.type
    FROM role_permissions rp
    JOIN access_permissions ap ON rp.permission_key = ap.key
    WHERE rp.role = ${role} AND ap.is_active = true
    ORDER BY ap.sort_order
  `;

  return result.map(row => ({
    role: row.role,
    permissionKey: row.permission_key,
    key: row.permission_key,
    label: row.label || row.permission_key,
    type: row.type,
    actions: row.actions as PermissionActions,
  }));
}

/**
 * Update role permission
 */
export async function updateRolePermission(
  role: string,
  permissionKey: string,
  actions: Partial<PermissionActions>
): Promise<void> {
  const currentActions = await sql`
    SELECT actions FROM role_permissions
    WHERE role = ${role} AND permission_key = ${permissionKey}
  `;

  const merged = {
    view: false,
    create: false,
    edit: false,
    delete: false,
    ...(currentActions[0]?.actions || {}),
    ...actions,
  };

  await sql`
    INSERT INTO role_permissions (role, permission_key, actions)
    VALUES (${role}, ${permissionKey}, ${JSON.stringify(merged)}::jsonb)
    ON CONFLICT (role, permission_key)
    DO UPDATE SET actions = ${JSON.stringify(merged)}::jsonb, updated_at = NOW()
  `;
}

// =====================================================
// User Permission Queries
// =====================================================

/**
 * Check if user has a specific permission action
 */
export async function userHasPermission(
  userId: string,
  permissionKey: string,
  action: PermissionAction = 'view'
): Promise<boolean> {
  // Check for legacy 'all' permission (super admin)
  const userResult = await sql`
    SELECT role, permissions FROM users WHERE id = ${userId}
  `;

  if (userResult.length === 0) return false;

  const user = userResult[0];

  // Super admin with 'all' permission
  if (user.permissions && Array.isArray(user.permissions) && user.permissions.includes('all')) {
    return true;
  }

  // Get role-based permission
  const rolePermResult = await sql`
    SELECT actions FROM role_permissions
    WHERE role = ${user.role} AND permission_key = ${permissionKey}
  `;

  let hasPermission = false;
  if (rolePermResult.length > 0 && rolePermResult[0].actions) {
    hasPermission = rolePermResult[0].actions[action] === true;
  }

  // Check for user override
  const overrideResult = await sql`
    SELECT override_type, actions FROM user_permission_overrides
    WHERE user_id = ${userId}
      AND permission_key = ${permissionKey}
      AND (expires_at IS NULL OR expires_at > NOW())
  `;

  if (overrideResult.length > 0) {
    const override = overrideResult[0];
    if (override.override_type === 'grant' && override.actions[action]) {
      return true;
    }
    if (override.override_type === 'revoke' && override.actions[action]) {
      return false;
    }
  }

  return hasPermission;
}

/**
 * Get user's effective permissions
 */
export async function getUserEffectivePermissions(userId: string): Promise<EffectivePermission[]> {
  // Check for super admin
  const userResult = await sql`
    SELECT role, permissions FROM users WHERE id = ${userId}
  `;

  if (userResult.length === 0) return [];

  const user = userResult[0];
  const isSuperAdmin = user.permissions && Array.isArray(user.permissions) && user.permissions.includes('all');

  if (isSuperAdmin) {
    // Super admin gets all permissions
    const allPerms = await sql`
      SELECT key FROM access_permissions WHERE is_active = true
    `;
    return allPerms.map(p => ({
      permissionKey: p.key,
      canView: true,
      canCreate: true,
      canEdit: true,
      canDelete: true,
    }));
  }

  // Get role permissions + overrides
  const result = await sql`
    SELECT
      ap.key as permission_key,
      COALESCE(
        CASE
          WHEN upo.override_type = 'grant' THEN (upo.actions->>'view')::boolean
          WHEN upo.override_type = 'revoke' AND (upo.actions->>'view')::boolean THEN FALSE
          ELSE (rp.actions->>'view')::boolean
        END,
        FALSE
      ) as can_view,
      COALESCE(
        CASE
          WHEN upo.override_type = 'grant' THEN (upo.actions->>'create')::boolean
          WHEN upo.override_type = 'revoke' AND (upo.actions->>'create')::boolean THEN FALSE
          ELSE (rp.actions->>'create')::boolean
        END,
        FALSE
      ) as can_create,
      COALESCE(
        CASE
          WHEN upo.override_type = 'grant' THEN (upo.actions->>'edit')::boolean
          WHEN upo.override_type = 'revoke' AND (upo.actions->>'edit')::boolean THEN FALSE
          ELSE (rp.actions->>'edit')::boolean
        END,
        FALSE
      ) as can_edit,
      COALESCE(
        CASE
          WHEN upo.override_type = 'grant' THEN (upo.actions->>'delete')::boolean
          WHEN upo.override_type = 'revoke' AND (upo.actions->>'delete')::boolean THEN FALSE
          ELSE (rp.actions->>'delete')::boolean
        END,
        FALSE
      ) as can_delete
    FROM access_permissions ap
    LEFT JOIN role_permissions rp ON rp.permission_key = ap.key AND rp.role = ${user.role}
    LEFT JOIN user_permission_overrides upo ON upo.permission_key = ap.key
      AND upo.user_id = ${userId}
      AND (upo.expires_at IS NULL OR upo.expires_at > NOW())
    WHERE ap.is_active = true
  `;

  return result.map(row => ({
    permissionKey: row.permission_key,
    canView: row.can_view,
    canCreate: row.can_create,
    canEdit: row.can_edit,
    canDelete: row.can_delete,
  }));
}

/**
 * Get user's permission overrides
 */
export async function getUserPermissionOverrides(userId: string): Promise<UserPermissionOverride[]> {
  const result = await sql`
    SELECT user_id, permission_key, override_type, actions, granted_by, granted_at, expires_at, reason
    FROM user_permission_overrides
    WHERE user_id = ${userId}
      AND (expires_at IS NULL OR expires_at > NOW())
  `;

  return result.map(row => ({
    userId: row.user_id,
    permissionKey: row.permission_key,
    overrideType: row.override_type as 'grant' | 'revoke',
    actions: row.actions as PermissionActions,
    grantedBy: row.granted_by,
    grantedAt: row.granted_at,
    expiresAt: row.expires_at,
    reason: row.reason,
  }));
}

/**
 * Grant permission override to user
 */
export async function grantUserPermission(
  userId: string,
  permissionKey: string,
  actions: Partial<PermissionActions>,
  grantedBy: string,
  reason?: string,
  expiresAt?: Date
): Promise<void> {
  const fullActions = {
    view: false,
    create: false,
    edit: false,
    delete: false,
    ...actions,
  };

  await sql`
    INSERT INTO user_permission_overrides (user_id, permission_key, override_type, actions, granted_by, reason, expires_at)
    VALUES (${userId}, ${permissionKey}, 'grant', ${JSON.stringify(fullActions)}::jsonb, ${grantedBy}, ${reason || null}, ${expiresAt || null})
    ON CONFLICT (user_id, permission_key)
    DO UPDATE SET
      override_type = 'grant',
      actions = ${JSON.stringify(fullActions)}::jsonb,
      granted_by = ${grantedBy},
      granted_at = NOW(),
      reason = ${reason || null},
      expires_at = ${expiresAt || null}
  `;
}

/**
 * Revoke permission from user
 */
export async function revokeUserPermission(
  userId: string,
  permissionKey: string,
  actions: Partial<PermissionActions>,
  revokedBy: string,
  reason?: string
): Promise<void> {
  const fullActions = {
    view: false,
    create: false,
    edit: false,
    delete: false,
    ...actions,
  };

  await sql`
    INSERT INTO user_permission_overrides (user_id, permission_key, override_type, actions, granted_by, reason)
    VALUES (${userId}, ${permissionKey}, 'revoke', ${JSON.stringify(fullActions)}::jsonb, ${revokedBy}, ${reason || null})
    ON CONFLICT (user_id, permission_key)
    DO UPDATE SET
      override_type = 'revoke',
      actions = ${JSON.stringify(fullActions)}::jsonb,
      granted_by = ${revokedBy},
      granted_at = NOW(),
      reason = ${reason || null}
  `;
}

/**
 * Remove permission override from user (revert to role-based)
 */
export async function removeUserPermissionOverride(
  userId: string,
  permissionKey: string
): Promise<void> {
  await sql`
    DELETE FROM user_permission_overrides
    WHERE user_id = ${userId} AND permission_key = ${permissionKey}
  `;
}

// =====================================================
// Batch Operations
// =====================================================

/**
 * Batch update all permissions for a role (replace all)
 * Deletes existing role_permissions and inserts new ones in a transaction
 */
export async function batchUpdateRolePermissions(
  role: string,
  permissions: Array<{ key: string; actions: PermissionActions }>
): Promise<number> {
  // Delete all existing permissions for this role
  await sql`DELETE FROM role_permissions WHERE role = ${role}`;

  // Insert new permissions
  let inserted = 0;
  for (const perm of permissions) {
    // Only insert if at least one action is true
    const hasAnyAction = perm.actions.view || perm.actions.create || perm.actions.edit || perm.actions.delete;
    if (hasAnyAction) {
      await sql`
        INSERT INTO role_permissions (role, permission_key, actions)
        VALUES (${role}, ${perm.key}, ${JSON.stringify(perm.actions)}::jsonb)
      `;
      inserted++;
    }
  }

  return inserted;
}

/**
 * Batch set user permissions by computing overrides from desired state.
 * Compares desired effective permissions against role defaults.
 * If desired differs from role default, creates a 'grant' override
 * with the full desired actions (grant type replaces role defaults entirely).
 * If desired matches role default, no override is needed.
 */
export async function batchSetUserPermissions(
  userId: string,
  desiredPermissions: Array<{ key: string; actions: PermissionActions }>,
  grantedBy: string
): Promise<{ overridesCreated: number; overridesRemoved: number }> {
  // Get user's role
  const userResult = await sql`SELECT role FROM users WHERE id = ${userId}`;
  if (userResult.length === 0) throw new Error('User not found');
  const userRole = userResult[0].role;

  // Get role-based permissions
  const rolePerms = await getRolePermissions(userRole);
  const rolePermMap = new Map(
    rolePerms.map(rp => [rp.permissionKey, rp.actions])
  );

  // Count existing overrides before clearing
  const existingCount = await sql`
    SELECT COUNT(*)::int as count FROM user_permission_overrides WHERE user_id = ${userId}
  `;
  const removedCount = existingCount[0]?.count || 0;

  // Delete all existing overrides for this user
  await sql`DELETE FROM user_permission_overrides WHERE user_id = ${userId}`;

  let overridesCreated = 0;

  for (const desired of desiredPermissions) {
    const roleDefault = rolePermMap.get(desired.key) || {
      view: false, create: false, edit: false, delete: false,
    };

    // Check if desired differs from role default
    const differs = (
      desired.actions.view !== roleDefault.view ||
      desired.actions.create !== roleDefault.create ||
      desired.actions.edit !== roleDefault.edit ||
      desired.actions.delete !== roleDefault.delete
    );

    if (differs) {
      // Grant type with full desired actions replaces role defaults entirely
      // in the getUserEffectivePermissions SQL resolution
      await sql`
        INSERT INTO user_permission_overrides
          (user_id, permission_key, override_type, actions, granted_by, reason)
        VALUES (
          ${userId}, ${desired.key}, 'grant',
          ${JSON.stringify(desired.actions)}::jsonb,
          ${grantedBy}, 'Batch permission update'
        )
      `;
      overridesCreated++;
    }
    // No override needed if desired === role default
  }

  return { overridesCreated, overridesRemoved: removedCount };
}

/**
 * Create a role from a user's effective permissions
 */
export async function createRoleFromUserPermissions(
  userId: string,
  roleName: string,
  displayName: string,
  description: string | null,
  createdBy: string
): Promise<{ roleId: string; permissionCount: number }> {
  // Get user's effective permissions
  const effectivePerms = await getUserEffectivePermissions(userId);

  // Create the role
  const newRole = await sql`
    INSERT INTO custom_roles (name, display_name, description, color, is_system, created_by)
    VALUES (${roleName}, ${displayName}, ${description}, '#6b7280', FALSE, ${createdBy})
    RETURNING id
  `;

  const roleId = newRole[0].id;

  // Insert permissions that have at least one action enabled
  let count = 0;
  for (const perm of effectivePerms) {
    const hasAny = perm.canView || perm.canCreate || perm.canEdit || perm.canDelete;
    if (hasAny) {
      const actions = {
        view: perm.canView,
        create: perm.canCreate,
        edit: perm.canEdit,
        delete: perm.canDelete,
      };
      await sql`
        INSERT INTO role_permissions (role, permission_key, actions)
        VALUES (${roleName}, ${perm.permissionKey}, ${JSON.stringify(actions)}::jsonb)
      `;
      count++;
    }
  }

  return { roleId, permissionCount: count };
}

/**
 * Update an existing role's permissions from a user's effective permissions
 */
export async function updateRoleFromUserPermissions(
  userId: string,
  targetRole: string
): Promise<{ permissionCount: number }> {
  // Get user's effective permissions
  const effectivePerms = await getUserEffectivePermissions(userId);

  // Delete existing permissions for this role
  await sql`DELETE FROM role_permissions WHERE role = ${targetRole}`;

  // Insert new permissions
  let count = 0;
  for (const perm of effectivePerms) {
    const hasAny = perm.canView || perm.canCreate || perm.canEdit || perm.canDelete;
    if (hasAny) {
      const actions = {
        view: perm.canView,
        create: perm.canCreate,
        edit: perm.canEdit,
        delete: perm.canDelete,
      };
      await sql`
        INSERT INTO role_permissions (role, permission_key, actions)
        VALUES (${targetRole}, ${perm.permissionKey}, ${JSON.stringify(actions)}::jsonb)
      `;
      count++;
    }
  }

  return { permissionCount: count };
}

// =====================================================
// Helper functions for common checks
// =====================================================

/**
 * Check if user can view a module
 */
export async function canViewModule(userId: string, moduleKey: string): Promise<boolean> {
  return userHasPermission(userId, moduleKey, 'view');
}

/**
 * Check if user can access a page
 */
export async function canAccessPage(userId: string, pageKey: string): Promise<boolean> {
  return userHasPermission(userId, pageKey, 'view');
}

/**
 * Get modules user can view
 */
export async function getAccessibleModules(userId: string): Promise<Permission[]> {
  const allModules = await getPermissions('module');
  const effectivePerms = await getUserEffectivePermissions(userId);

  const viewableKeys = new Set(
    effectivePerms.filter(p => p.canView).map(p => p.permissionKey)
  );

  return allModules.filter(m => viewableKeys.has(m.key));
}

/**
 * Get pages user can view for a module
 */
export async function getAccessiblePages(userId: string, moduleKey: string): Promise<Permission[]> {
  const modulePerms = await getModulePermissions(moduleKey);
  const pages = modulePerms.filter(p => p.type === 'page');
  const effectivePerms = await getUserEffectivePermissions(userId);

  const viewableKeys = new Set(
    effectivePerms.filter(p => p.canView).map(p => p.permissionKey)
  );

  return pages.filter(p => viewableKeys.has(p.key));
}

